        const arcanaLayerKeys = Object.freeze(["kaynak","yontem","etkilesim","odak","bicim","amac"]);
        const arcanaOptionById = (layerKey, optionId) => arcanaLayers[layerKey]?.opts?.find(option => option.id === optionId) || null;
        const arcanaOptionEmoji = option => String(option?.isim || "✧").split(" ")[0] || "✧";
        const arcanaSignatureOfState = state => arcanaLayerKeys.map(key => String(state?.[key] || "")).join("|");
        const arcanaSelectionsOfState = state => Object.fromEntries(arcanaLayerKeys.map(key => [key, String(state?.[key] || "")]));
        const arcanaEmojiOfState = state => arcanaLayerKeys.map(key => arcanaOptionEmoji(arcanaOptionById(key,state?.[key]))).join("");
        const arcanaStateComplete = state => arcanaLayerKeys.every(key => !!arcanaOptionById(key,state?.[key]));
        const arcanaLegacyPrefixMap = (() => {
            const map = new Map();
            const walk = (depth, state) => {
                if (depth >= arcanaLayerKeys.length) {
                    map.set(arcanaEmojiOfState(state), arcanaSignatureOfState(state));
                    return;
                }
                const key = arcanaLayerKeys[depth];
                arcanaLayers[key].opts.forEach(option => walk(depth + 1, {...state,[key]:option.id}));
            };
            walk(0,{});
            return map;
        })();
        const arcanaFamilySignature = family => {
            if (!family || typeof family !== "object") return "";
            if (typeof family.arcanaSignature === "string" && family.arcanaSignature.split("|").length === 6) return family.arcanaSignature;
            if (family.arcanaSelections && typeof family.arcanaSelections === "object") {
                const signature = arcanaSignatureOfState(family.arcanaSelections);
                if (signature.split("|").every(Boolean)) return signature;
            }
            const familyName = String(family.name || "");
            for (const [emojiPrefix,signature] of arcanaLegacyPrefixMap.entries()) if (familyName.startsWith(emojiPrefix)) return signature;
            return "";
        };
        const arcanaFamilyEmoji = family => {
            if (typeof family?.arcanaEmoji === "string" && family.arcanaEmoji.trim()) return family.arcanaEmoji.trim();
            const signature = arcanaFamilySignature(family);
            if (signature) {
                const ids = signature.split("|");
                const state = Object.fromEntries(arcanaLayerKeys.map((key,index) => [key,ids[index]]));
                return arcanaEmojiOfState(state);
            }
            return "✧✧✧✧✧✧";
        };
        const arcanaFamilyManifest = state => {
            if (!arcanaStateComplete(state)) return {emoji:"",name:"",desc:""};
            const picked = Object.fromEntries(arcanaLayerKeys.map(key => [key,arcanaOptionById(key,state[key])]));
            const emoji = arcanaEmojiOfState(state);
            const sourceWord = String(picked.kaynak.isim).split(" ")[1] || "Kök";
            const purposeWord = String(picked.amac.isim).split(" ")[1] || "Yargı";
            return {
                emoji,
                name:`${emoji} ${sourceWord} ${purposeWord} Ekolü`,
                desc:`Bu Arcana Ekolü; ${picked.kaynak.isim} köklerinden beslenir ve enerjiyi ${picked.yontem.isim} bir yaklaşımla yönlendirir. ${picked.etkilesim.isim} yoluyla ${picked.odak.isim} ölçekte çalışır; gerçekliği ${picked.bicim.isim} biçiminde büker ve ${picked.amac.isim} yargısına ulaştırır.`
            };
        };

