const gameFolderFromLogicalPath = path => {
    const normalized=String(path||"").replace(/\\/g,"/"),match=normalized.match(/^Games\/([^/]+)\//);
    return match?.[1]||String(activeAdventure?.folder||"");
};
const gameDocumentKeyFromLogicalPath = path => {
    const file=String(path||"").replace(/\\/g,"/").split("/").pop()||"";
    return DB_DOCUMENT_KEYS[file]||file.replace(/\.json$/i,"").replace(/[^a-zA-Z0-9_.-]/g,"_");
};
const readJsonSafe = async (path, fallback) => {
    try {
        const folder=gameFolderFromLogicalPath(path),key=gameDocumentKeyFromLogicalPath(path);
        if(!_hasBridge||!folder||!key||typeof window.__alekGameRead!=="function")return cloneData(fallback);
        const result=await window.__alekGameRead(folder,key);
        if(!result?.ok||!result.exists||!result.data||typeof result.data!=="object")return cloneData(fallback);
        return cloneData(result.data);
    } catch (err) {
        console.warn("SQLite belgesi okunamadı:", path, err);
        return cloneData(fallback);
    }
};

const writeJsonSafe = async (path, value) => {
    const folder=gameFolderFromLogicalPath(path),key=gameDocumentKeyFromLogicalPath(path);
    if(!_hasBridge||typeof window.__alekGameWrite!=="function")throw new Error("Taşınabilir SQLite köprüsü bulunamadı.");
    if(!folder)throw new Error("Aktif macera klasörü hazırlanamadı.");
    if(!key)throw new Error("SQLite belge anahtarı oluşturulamadı.");
    const serialized=JSON.stringify(value);const safeValue=JSON.parse(serialized);
    const result=await window.__alekGameWrite(folder,key,safeValue);
    if(!result?.ok)throw new Error(result?.error||`SQLite belgesi yazılamadı: ${key}`);
    return true;
};

