    const now=new Date();
    if(runtime.mode==="alekrytha")runtime.time={...runtime.time,year:24000,month:1,day:1,hour:8,minute:0,second:0,season:"",seasonMonthIndex:1,rate:0,progressionMode:"action",startConfigured:false};
