    if(runtime.mode==="other_realm")runtime.time={...runtime.time,year:Math.max(1,Number(runtime.time.year)||1),month:Math.max(1,Number(runtime.time.month)||1),day:Math.max(1,Number(runtime.time.day)||1),hour:Number(runtime.time.hour)||0,minute:Number(runtime.time.minute)||0,second:Number(runtime.time.second)||0,rate:0,progressionMode:"action",startConfigured:false};
