    {const layerKey=String(journeySource.layerKey||"root");data.game.journey3d.layerKey=isValidContainerKey(layerKey)?layerKey:"root";}
    data.game.journey3d.destination=journeySource.destination&&typeof journeySource.destination==="object"?Object.assign({},journeySource.destination):null;
