    const sourceRecordKey=String(route?.sourceRecordKey||subject.sourceEntityKey||""),sourceRecord=joaRecordFromKey(sourceRecordKey),targetRecord=joaRecordFromKey(entryKey);if(!sourceRecord||!targetRecord||!["character","location"].includes(sourceRecord.type)||!["character","location"].includes(targetRecord.type)||sourceRecord.key===targetRecord.key||containerWouldCycle(sourceRecord.key,targetRecord.key))return{hasEntry:true,valid:false,reason:"Geçersiz konteyner hedefi"};return{hasEntry:true,valid:true,type:"record-entity",sourceRecord,targetRecord,targetName:fullNameOf(targetRecord.entity)};
