        {const value=Number(c.healthRecoveryPerHour);c.healthRecoveryPerHour=Math.max(0,Number.isFinite(value)?value:1);}
        {const value=Number(c.manaRecoveryPerHour);c.manaRecoveryPerHour=Math.max(0,Number.isFinite(value)?value:5);}
        {const value=Number(c.staminaRecoveryPerHour);c.staminaRecoveryPerHour=Math.max(0,Number.isFinite(value)?value:8);}
        {const value=Number(c.metanetRecoveryPerHour);c.metanetRecoveryPerHour=Math.max(0,Number.isFinite(value)?value:4);}
        c.metanetDrainCarry=Math.max(0,Math.min(.999999,Number(c.metanetDrainCarry??c.metanetFatigueCarry)||0));
        delete c.metanetFatigueCarry;
        delete c.metanetFatiguePerHour;
