// Kart kimliğinin tek renk kaynağı Taksonomi Dairesindeki gerçek P/S/T/M
// geçişidir. Journey, ayrıntı yüzü ve daire aynı hücre rengini kullanır.
const TAXONOMY_DIAMOND_COLORS=Object.freeze({P:"#f04fff",S:"#ffd05a",T:"#28e5d1",M:"#438dff"});
const TAXONOMY_SECTOR_COLOR_FLOW=Object.freeze({society:["S","T"],systems:["T","M"],places:["M","P"],living:["P","S"]});
const taxonomyHexToRgb=hex=>{const clean=String(hex||"").replace("#","");const full=clean.length===3?clean.split("").map(x=>x+x).join(""):clean;return{r:parseInt(full.slice(0,2),16),g:parseInt(full.slice(2,4),16),b:parseInt(full.slice(4,6),16)};};
const taxonomyRgbToHex=({r,g,b})=>`#${[r,g,b].map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,"0")).join("")}`;
const taxonomyMixHex=(from,to,t)=>{const a=taxonomyHexToRgb(from),b=taxonomyHexToRgb(to),p=Math.max(0,Math.min(1,Number(t)||0));return taxonomyRgbToHex({r:a.r+((b.r-a.r)*p),g:a.g+((b.g-a.g)*p),b:a.b+((b.b-a.b)*p)});};
const taxonomyTransitionFor=(sectorId,index)=>{
    const [fromTag,toTag]=TAXONOMY_SECTOR_COLOR_FLOW[sectorId]||["P","S"];
    const fromWeight=5-(4*(Math.max(0,Math.min(5,index))/5));
    const toWeight=6-fromWeight;
    const mix=toWeight/6;
    const fromColor=TAXONOMY_DIAMOND_COLORS[fromTag],toColor=TAXONOMY_DIAMOND_COLORS[toTag];
    return Object.freeze({fromTag,toTag,fromWeight,toWeight,fromColor,toColor,color:taxonomyMixHex(fromColor,toColor,mix),mix});
};
const ALEK_CARD_TAXONOMY_POSITION=Object.freeze({
    character:["living",0],being:["living",1],species:["living",2],people:["living",3],group:["living",4],dynasty:["living",5],
    society:["society",0],sovereignty:["society",1],civilization:["society",2],settlement:["society",3],land:["society",4],plane:["society",5],
    location:["places",0],structure:["places",1],geography:["places",2],habitat:["places",3],celestial:["places",4],realm:["places",5],
    item:["systems",0],mount:["systems",1],mechanism:["systems",2],facility:["systems",3],resource:["systems",4],network:["systems",5]
});
const cardIdentityAccentOf=type=>{const position=ALEK_CARD_TAXONOMY_POSITION[type];return position?taxonomyTransitionFor(position[0],position[1]).color:genericEntityDefinition(type)?.accent||"#8fe3b5";};
// R16 · Macera Grubu taxonomy köklerinden türetilmeyen, sistem-özel bir karttır.
const ALEK_ADVENTURE_PARTY_ACCENT="#79ddff";
const ALEK_GENERIC_ENTITY_TYPES=Object.freeze(Object.keys(ALEK_GENERIC_ENTITY_DEFS));
const entityBehaviorFamily=type=>{
    if(type==="character"||type==="being")return "individual";
    if(type==="group"||type==="location"||type==="realm"||type==="land"||type==="settlement")return "collective";
    if(type==="mount")return "mount";
    if(type==="dynasty"||type==="society")return "institution";
    if(genericEntityDefinition(type)?.behavior==="reference")return "reference";
    return "individual";
};
const usesIndividualSheetType=type=>entityBehaviorFamily(type)==="individual";
const isLeafEntityType=()=>false;
// Her ana kart fiziksel içerik taşıyabilir. Bağ/üyelik ilişkileri ayrıca
// korunur; konteyner olmak bir kartın anlatısal ilişki türünü değiştirmez.
const isContainerEntityType=type=>ALEK_CONTAINER_ENTITY_TYPE_SET.has(String(type||""));
const isCollectiveEntityType=type=>entityBehaviorFamily(type)==="collective";
const isInstitutionEntityType=type=>entityBehaviorFamily(type)==="institution";
const isReferenceEntityType=type=>entityBehaviorFamily(type)==="reference";
const genericEntityCards=()=>{const game=normalizeGameRuntime();if(!Array.isArray(game.entityCards))game.entityCards=[];return game.entityCards;};
const genericEntityDefinition=type=>ALEK_GENERIC_ENTITY_DEFS[type]||null;
const ensureInstitutionResources=entity=>{
    const item=entity&&typeof entity==="object"?entity:{};
    for(const key of ["influence","reputation"]){
        if(!item[key]||typeof item[key]!=="object")item[key]={current:24,maximum:24};
        item[key].maximum=Math.max(1,Math.round(Number(item[key].maximum)||24));
        const raw=Number(item[key].current);item[key].current=Math.max(0,Math.min(item[key].maximum,Number.isFinite(raw)?Math.round(raw):item[key].maximum));
    }
    return item;
};
const normalizeGenericEntity=(entity,type=entity?.entityType)=>{
    const def=genericEntityDefinition(type);if(!def)return null;
    let item=entity&&typeof entity==="object"?entity:{};
    const originalContainer=item.containerKey;
    if(type==="being"||type==="dynasty"||type==="society")item=ensureEntitySheetFields(item,"character");
    else if(type==="realm"||type==="land"||type==="settlement")item=ensureEntitySheetFields(item,"location");
    if(!item.id)item.id=makeId(type);
    ensureNarrativeCardFields(item);
    item.entityType=type;item.name=String(item.name||`İsimsiz ${def.title}`).trim()||`İsimsiz ${def.title}`;item.surname=String(item.surname||"");
    item.title=String(item.title||def.title).trim()||def.title;item.subtype=String(item.subtype||def.title).trim()||def.title;
    if(type==="realm"){
        if(/hareketli diyar/i.test(item.title)||/uçan ada\s*\//i.test(item.title))item.title="Uçan Ada";
        if(/hareketli diyar/i.test(item.subtype)||/uçan ada\s*\//i.test(item.subtype))item.subtype="Uçan Ada";
    }
    item.description=String(item.description||item.lore||"");item.lore=String(item.lore||item.description||"");
    item.avatar=String(item.avatar||item.image||"");item.image=String(item.image||item.avatar||"");
    item.containerKey=isValidContainerKey(originalContainer||item.containerKey)?String(originalContainer||item.containerKey):"root";
    item.isSpatialContainer=true;item.isLeafEntity=false;
    if(type==="being"){
        item.__being=true;item.isBeing=true;
    }
    if(type==="dynasty"||type==="society"){
        ensureInstitutionResources(item);
        item.isInstitution=true;
    }
    item.inventory=Array.isArray(item.inventory)?item.inventory:[];
    item.envanter=Array.isArray(item.envanter)?item.envanter:item.inventory;
    item.inventory=item.envanter;
    item.journal=Array.isArray(item.journal)?item.journal:[];item.quests=Array.isArray(item.quests)?item.quests:[];
    item.createdAt=item.createdAt||new Date().toISOString();item.updatedAt=item.updatedAt||item.createdAt;return item;
};
const normalizeGenericEntityCards=()=>{const list=genericEntityCards();for(let index=0;index<list.length;index++){const normalized=normalizeGenericEntity(list[index],list[index]?.entityType);if(normalized)list[index]=normalized;}return list;};
const getGenericEntityById=(type,id)=>normalizeGenericEntityCards().find(item=>item.entityType===type&&String(item.id)===String(id))||null;
const ensureAlekrythaRaceGroup=()=>{
    if(normalizeGameRuntime().mode!=="alekrytha")return null;
    if(!Array.isArray(groupData.groups))groupData.groups=[];
    let group=groupData.groups.find(item=>item?.canonicalAlekrythaRaceGroup===true);
    if(!group)group=groupData.groups.find(item=>String(item?.name||"").trim().toLocaleLowerCase("tr")==="24 ırk"&&item?.systemManaged===true);
    if(!group){
        group=normalizeGroup({id:makeId("group"),name:"24 Irk",title:"Alekrytha'nın 24 Irkı",groupType:"Topluluk",description:"Alekrytha Oyunlarında Karakter Kağıtlarının seçebildiği 24 kanonik ırk.",containerKey:"root",canonicalAlekrythaRaceGroup:true,systemManaged:true});
        groupData.groups.push(group);
    }
    group.name="24 Irk";group.title="Alekrytha'nın 24 Irkı";group.canonicalAlekrythaRaceGroup=true;group.systemManaged=true;group.undeletable=true;group.containerKey="root";
    return group;
};
const ensureAlekrythaSpeciesCards=()=>{
    if(normalizeGameRuntime().mode!=="alekrytha")return false;
    let changed=false;
    const beforeGroupCount=Array.isArray(groupData.groups)?groupData.groups.length:0;
    const raceGroup=ensureAlekrythaRaceGroup();
    if((groupData.groups||[]).length!==beforeGroupCount)changed=true;
    const raceGroupKey=raceGroup?`group:${raceGroup.id}`:"root";
    const cards=normalizeGenericEntityCards();
    for(const card of cards){
        if(card?.entityType!=="species"||card?.canonicalAlekrythaRace!==true)continue;
        const nextName=canonicalRaceNameOf(card.name);if(nextName!==String(card.name||"")){card.name=nextName;card.updatedAt=new Date().toISOString();changed=true;__alekCanonicalRaceRenamePending=true;}
    }
    for(const race of irklar){
        const key=String(race).trim().toLocaleLowerCase("tr");
        let card=cards.find(item=>item.entityType==="species"&&item.canonicalAlekrythaRace===true&&String(item.name||"").trim().toLocaleLowerCase("tr")===key);
        if(!card)card=cards.find(item=>item.entityType==="species"&&String(item.name||"").trim().toLocaleLowerCase("tr")===key);
        if(!card){
            card=normalizeGenericEntity({id:makeId("species"),entityType:"species",name:race,title:"Tür",subtype:"Alekrytha'nın 24 kanonik ırkından biri",description:"",lore:"",uniqueTraits:[],containerKey:raceGroupKey,containerSection:"species",canonicalAlekrythaRace:true,systemManaged:true,undeletable:true,isImmortal:true},"species");
            if(card){genericEntityCards().push(card);changed=true;}
        }
        if(card){
            const signature=JSON.stringify([card.canonicalAlekrythaRace,card.systemManaged,card.undeletable,card.isImmortal,card.containerKey,card.containerSection,card.subtype]);
            card.canonicalAlekrythaRace=true;card.systemManaged=true;card.undeletable=true;card.isImmortal=true;card.containerKey=raceGroupKey;card.containerSection="species";card.subtype="Alekrytha'nın 24 kanonik ırkından biri";
            const nextSignature=JSON.stringify([card.canonicalAlekrythaRace,card.systemManaged,card.undeletable,card.isImmortal,card.containerKey,card.containerSection,card.subtype]);
            if(signature!==nextSignature)changed=true;
        }
    }
    return changed;
};
const R21_ADD_CUSTOM_SPECIES="__r21_add_custom_species__";
const r21SpeciesMode=entity=>String(entity?.speciesListMode||"canonical")==="custom"?"custom":"canonical";
const livingOriginCards=(type,entity=null)=>{
    if(type==="species")ensureAlekrythaSpeciesCards();
    let cards=normalizeGenericEntityCards().filter(item=>item.entityType===type);
    if(type==="species"&&normalizeGameRuntime().mode==="alekrytha"){
        cards=r21SpeciesMode(entity)==="custom"
            ? cards.filter(item=>item.canonicalAlekrythaRace!==true)
            : cards.filter(item=>item.canonicalAlekrythaRace===true);
    }
    return cards.sort((a,b)=>String(a.name).localeCompare(String(b.name),"tr"));
};
const r21CreateOriginRegistryCard=async(type,name)=>{
    const clean=String(name||"").trim();if(!clean)return null;
    const existing=normalizeGenericEntityCards().find(item=>item.entityType===type&&String(item.name||"").trim().toLocaleLowerCase("tr")===clean.toLocaleLowerCase("tr"));
    if(existing)return existing;
    const def=genericEntityDefinition(type)||{title:type==="species"?"Tür":"Halk"};
    const item=normalizeGenericEntity({id:makeId(type),entityType:type,name:clean,title:def.title,subtype:def.title,description:"",lore:"",uniqueTraits:[],containerKey:"root",systemManaged:false,canonicalAlekrythaRace:false,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()},type);
    genericEntityCards().push(item);await saveToDB(`${clean} ${type==="species"?"Tür":"Halk"} listesine eklendi.`);return item;
};
const ensureBeingNatureFields=entity=>{entity.anatomyText=String(entity.anatomyText||"");entity.instinctText=String(entity.instinctText||"");entity.ecologyText=String(entity.ecologyText||"");return entity;};
const ALEK_HYBRID_SPECIES_VALUE="__alekrytha_hybrid__";
const livingOriginTraitsFor=entity=>{
    const sources=[];
    if(String(entity?.speciesCardId||"")===ALEK_HYBRID_SPECIES_VALUE||String(entity?.race||"")==="Melez"){
        for(const race of [...new Set((entity?.melezRaces||[]).filter(item=>irklar.includes(item)))]){
            const species=livingOriginCards("species",entity).find(item=>String(item.name||"")===String(race));
            if(species)sources.push({type:"Melez Kök",name:species.name,traits:normalizeNarrativeTraitList(species.uniqueTraits)});
        }
    }else{
        const species=getGenericEntityById("species",entity?.speciesCardId);
        if(species)sources.push({type:"Tür",name:species.name,traits:normalizeNarrativeTraitList(species.uniqueTraits)});
    }
    const people=getGenericEntityById("people",entity?.peopleCardId);
    if(people)sources.push({type:"Halk",name:people.name,traits:normalizeNarrativeTraitList(people.uniqueTraits)});
    return sources;
};
const isAlekrythaCharacterSpeciesContext=entity=>normalizeGameRuntime().mode==="alekrytha";
const livingOriginSelectOptions=(type,selectedId,entity=null)=>{
    const cards=livingOriginCards(type,entity),alekrythaSpecies=type==="species"&&isAlekrythaCharacterSpeciesContext(entity),mode=type==="species"?r21SpeciesMode(entity):"all";
    const hybridSelected=alekrythaSpecies&&mode==="canonical"&&(String(selectedId||"")===ALEK_HYBRID_SPECIES_VALUE||String(entity?.race||entity?.alekrythaeRace||"")==="Melez"||(entity?.melezRaces||[]).length>=2);
    const selectedExists=!hybridSelected&&cards.some(item=>String(item.id)===String(selectedId||""));
    const fallback=alekrythaSpecies&&mode==="canonical"?(cards.find(item=>String(item.name||"").trim().toLocaleLowerCase("tr")==="insan")||cards[0]||null):null;
    const effectiveId=selectedExists?String(selectedId||""):String(fallback?.id||"");
    const empty=mode==="canonical"&&alekrythaSpecies?"":'<option value="">Seçilmedi</option>';
    const cardOptions=cards.map(item=>`<option value="${escapeHtmlValue(item.id)}" ${!hybridSelected&&String(item.id)===effectiveId?'selected':''}>${escapeHtmlValue(alekrythaSpecies&&item.canonicalAlekrythaRace===true?raceDisplayName(item.name):item.name)}</option>`).join("");
    const hybridOption=alekrythaSpecies&&mode==="canonical"?`<option value="${ALEK_HYBRID_SPECIES_VALUE}" ${hybridSelected?'selected':''}>${escapeHtmlValue(hybridRaceCompactLabel(entity?.melezRaces||[]))}</option>`:"";
    // Halk ekleme yalnız yanındaki rün mühründen yapılır. Tür listesinde ise
    // özgün Tür üretme seçeneği listede kalır; Tür mührü yalnız liste kipini değiştirir.
    const addOption=type==="species"&&mode==="custom"?`<option value="${R21_ADD_CUSTOM_SPECIES}">＋ Yeni özgün Tür ekle…</option>`:"";
    return `${empty}${cardOptions}${hybridOption}${addOption}`;
};
const ensureAlekrythaSpeciesBinding=entity=>{
    if(!entity||!isAlekrythaCharacterSpeciesContext(entity))return entity;
    entity.speciesListMode=r21SpeciesMode(entity);
    if(entity.speciesListMode==="custom"){
        const custom=livingOriginCards("species",entity).find(item=>String(item.id)===String(entity.speciesCardId||""));
        if(custom){entity.race=custom.name;entity.alekrythaeRace=custom.name;entity.raceMode="alekrythae";entity.outerRealmRace="";entity.melezRaces=[];}
        return entity;
    }
    if(String(entity.speciesCardId||"")===ALEK_HYBRID_SPECIES_VALUE||String(entity.race||entity.alekrythaeRace||"")==="Melez"){
        entity.speciesCardId=ALEK_HYBRID_SPECIES_VALUE;entity.race="Melez";entity.alekrythaeRace="Melez";entity.raceMode="alekrythae";entity.outerRealmRace="";entity.melezRaces=[...new Set((entity.melezRaces||[]).filter(race=>irklar.includes(race)))];
        return entity;
    }
    const cards=livingOriginCards("species",entity);
    let selected=cards.find(item=>String(item.id)===String(entity.speciesCardId||""));
    if(!selected){const wanted=String(entity.race||entity.alekrythaeRace||irklar[0]).trim().toLocaleLowerCase("tr");selected=cards.find(item=>String(item.name||"").trim().toLocaleLowerCase("tr")===wanted)||cards.find(item=>String(item.name||"")===irklar[0])||cards[0]||null;}
    if(selected){entity.speciesCardId=String(selected.id);entity.race=selected.name;entity.alekrythaeRace=selected.name;entity.raceMode="alekrythae";entity.outerRealmRace="";entity.melezRaces=[];}
    return entity;
};
