    <label><span>Anatomi ve Beden</span><textarea id="i_being_anatomy" ${isLocked?'disabled':''} style="${inpStyle}min-height:100px;resize:vertical;" placeholder="Duyular, uzuvlar, hareket biçimi, zayıflıklar ve doğal yetiler…">${escapeHtmlValue(entity.anatomyText)}</textarea></label>
