        const ensureCharacterFlags=char=>{if(!char||typeof char!=="object")return char;if(typeof char.isImmortal!=="boolean")char.isImmortal=false;if(typeof char.genderLocked!=="boolean")char.genderLocked=false;if(typeof char.isDead!=="boolean")char.isDead=!!char.isDead;if(typeof char.isUnconscious!=="boolean")char.isUnconscious=!!char.isUnconscious;if(char.isDead)char.isImmortal=false;return char;};
        const cloneSerializableState=value=>{try{return JSON.parse(JSON.stringify(value));}catch(_){return null;}};
        const normalizeSavedResource=(resource,fallbackCurrent,fallbackMaximum)=>{
            const maximum=Math.max(1,Math.round(Number(resource?.maximum)||fallbackMaximum));
            const raw=Number(resource?.current);
            const current=Math.max(0,Math.min(maximum,Number.isFinite(raw)?Math.round(raw):fallbackCurrent));
            return{current,maximum};
        };
        const captureLifeBeforeDeath=char=>{
            if(!char||typeof char!=="object")return null;
            ensureCharacterFlags(char);
            const health=normalizeSavedResource(char.health,24,24);
            const arcanaReserve=normalizeSavedResource(char.arcanaReserve,240,240);
            const stamina=normalizeSavedResource(char.stamina,100,100);
            const metanet=normalizeSavedResource(char.metanet,100,100);
            // Ölüm sonrası isim, lore, çanta, görev ve diğer alanlar düzenlenebilir.
            // Bu nedenle yalnız ölüm öncesi can, Æřɨŧqʉɍ ve Takat değerleri saklanır.
            char._lifeBeforeDeath={version:4,capturedAt:Date.now(),health,arcanaReserve,stamina,metanet};
            return char._lifeBeforeDeath;
        };
        const restoreLifeBeforeDeath=char=>{
            if(!char||typeof char!=="object")return{restored:false};
            const pack=char._lifeBeforeDeath||{};
            // v1 paketleriyle geriye uyumluluk: eski tam anlık görüntüden yalnız kaynakları al.
            const oldState=pack&&pack.state&&typeof pack.state==="object"?pack.state:null;
            const healthSource=pack.health||oldState?.health||null;
            const manaSource=pack.arcanaReserve||oldState?.arcanaReserve||null;
            const staminaSource=pack.stamina||oldState?.stamina||null;
            const metanetSource=pack.metanet||oldState?.metanet||null;
            const hasSnapshot=!!(healthSource||manaSource||staminaSource||metanetSource);
            char.isDead=false;
            char.isImmortal=false;
            ensureEntitySheetFields(char,char.__location?"location":"character");
            const health=normalizeSavedResource(healthSource,char.health?.maximum||24,char.health?.maximum||24);
            const arcanaReserve=normalizeSavedResource(manaSource,char.arcanaReserve?.maximum||240,char.arcanaReserve?.maximum||240);
            const stamina=normalizeSavedResource(staminaSource,char.stamina?.maximum||100,char.stamina?.maximum||100);
            const metanet=normalizeSavedResource(metanetSource,char.metanet?.maximum||100,char.metanet?.maximum||100);
            char.health=health;
            char.arcanaReserve=arcanaReserve;
            char.stamina=stamina;
            char.metanet=metanet;
            syncCharacterThresholdStates(char);
            delete char._lifeBeforeDeath;
            return{restored:hasSnapshot,fallback:!hasSnapshot};
        };
        // Ölüm artık genel bir salt-okunur kip değildir. Yalnız can/Æřɨŧqʉɍ kontrolleri
        // ve yetenek ağacındaki yapısal ekleme-silme işlemleri kilitlenir.
        const DEAD_ALLOWED_SELECTOR='[data-dead-allowed="true"]';
        const applyDeadReadOnlyState=(scope,char)=>{
            if(!scope)return;
            scope.classList.toggle("dead-limited-mode",!!char?.isDead);
            scope.classList.remove("dead-readonly-mode");
        };
        const installDeadReadOnlyGuard=(scope,char)=>{
            if(!scope)return;
            try{scope.__deadReadonlyCleanup?.();}catch(_){ }
            scope.__deadReadonlyCleanup=()=>{};
            applyDeadReadOnlyState(scope,char);
        };
        const enforceDeadResourceLock=char=>{
            if(!char||typeof char!=="object")return char;
            ensureCharacterFlags(char);
            if(!char.health||typeof char.health!=="object")char.health={current:0,maximum:24};
            if(!char.arcanaReserve||typeof char.arcanaReserve!=="object")char.arcanaReserve={current:0,maximum:240};
            if(!char.stamina||typeof char.stamina!=="object")char.stamina={current:0,maximum:100};
            if(!char.metanet||typeof char.metanet!=="object")char.metanet={current:0,maximum:100};
            char.health.maximum=Math.max(1,Math.round(Number(char.health.maximum)||24));
            char.arcanaReserve.maximum=Math.max(1,Math.round(Number(char.arcanaReserve.maximum)||240));
            char.stamina.maximum=Math.max(1,Math.round(Number(char.stamina.maximum)||100));
            char.metanet.maximum=Math.max(1,Math.round(Number(char.metanet.maximum)||100));
            if(char.isDead){
                char.isImmortal=false;
                char.health.current=0;
                char.arcanaReserve.current=0;
                char.stamina.current=0;
                char.metanet.current=0;
                char.isUnconscious=false;
            }
            return char;
        };
        const stateRibbonMarkup=char=>char?.isDead?`<div class="alek-state-ribbon dead"><div class="main">ÖLDÜ</div><div class="sub">Yaşam bağı koptu</div></div>`:char?.isUnconscious?`<div class="alek-state-ribbon unconscious"><div class="main">BAYGIN</div><div class="sub">Yaşam akışı sürüyor</div></div>`:"";
        const immortalChipMarkup=char=>char?.isImmortal&&!char?.isDead?`<div class="alek-immortal-chip">∞ ÖLÜMSÜZ</div>`:"";
        const filterForCharacterState=char=>char?.isDead?"grayscale(100%) brightness(0.4) contrast(1.03)":char?.isUnconscious?"brightness(0.7) saturate(0.82)":"";
        const applyCharacterVisualState=(shell,char,{imageSelector="#activeAvatarImg"}={})=>{
            if(!shell||!char)return;
            enforceDeadResourceLock(char);
            syncCharacterThresholdStates(char);
            const imageStage=shell.querySelector(imageSelector);
            const detailImageStage=imageSelector==="#activeAvatarImg"&&imageStage;
            const visualHost=detailImageStage||shell;
            shell.classList.toggle("is-immortal",!detailImageStage&&!!char.isImmortal);
            shell.classList.toggle("is-dead",!!char.isDead);
            shell.classList.toggle("is-unconscious",!!char.isUnconscious&&!char.isDead);
            if(detailImageStage){
                imageStage.classList.toggle("is-immortal",!!char.isImmortal);
                imageStage.classList.toggle("is-dead",!!char.isDead);
                imageStage.classList.toggle("is-unconscious",!!char.isUnconscious&&!char.isDead);
            }
            shell.querySelectorAll(".alek-state-ribbon,.alek-immortal-chip").forEach(node=>node.remove());
            if(imageStage)imageStage.style.filter=filterForCharacterState(char);
            const imm=immortalChipMarkup(char);
            if(imm)visualHost.insertAdjacentHTML("beforeend",imm);
            const ribbon=stateRibbonMarkup(char);
            if(ribbon)visualHost.insertAdjacentHTML("beforeend",ribbon);
        };

const applyCharacterOperationalState=(scope,char)=>{
    if(!scope||!char)return;
    syncCharacterThresholdStates(char);
    const locked=!!char.isStaminaExhausted&&!char.isDead;
    scope.classList.toggle("is-takat-exhausted",locked);
    let banner=scope.querySelector(".takat-exhaustion-lock");
    if(locked&&!banner){banner=document.createElement("div");banner.className="takat-exhaustion-lock";banner.innerHTML='<strong>TAKAT TÜKENDİ</strong><span>Karakter fiziksel eylem yapamaz. Kağıt, Çanta, Journal, Görevler ve Mevcudat kayıtları açık kalır; dinlenme veya bar girdisiyle Takat yenilenebilir.</span>';scope.querySelector(".character-detail-content")?.prepend(banner);}
    if(!locked&&banner)banner.remove();
};

