            const railCurrent=scope.querySelector(".aia-current-readout"),railMaximum=scope.querySelector(".aia-maximum-rail-readout"),panelMaximum=root.querySelector(".aia-maximum-readout"),impactPanel=root.querySelector(".health-control-panel");
