        let __saveTimer = null;
        const persistNewDataModel = async () => {
            if(!activeAdventure)return[];

            prepareDataModelForPersistence();
            const adventureId=String(activeAdventure?.id||"");
            const adventureFolder=String(activeAdventure?.folder||"");

            // Baseline always belongs to exactly one Adventure.
            if(!__dataBaselineReady||__dataBaselineAdventureId!==adventureId){
                captureDataPersistenceBaseline();
                return[];
            }

            recordViewHistoryChange("map");
            recordViewHistoryChange("tide");

            // Freeze every changed document before the first await.
            // A later UI/adventure change can never mutate an already queued write.
            const jobs=[];
            for(const [key,domain] of Object.entries(dataPersistenceDomains())){
                const path=String(domain.path||"");
                const snapshot=cloneData(domain.value);
                const fingerprint=__dataFingerprint(key,snapshot,path);
                if(__dataBaseline.get(key)===fingerprint)continue;
                jobs.push({key,path,snapshot,fingerprint,adventureId,adventureFolder});
            }
            if(!jobs.length)return[];

            const run=async()=>{
                const changed=[];
                for(const job of jobs){
                    await writeJsonSafe(job.path,job.snapshot);
                    // Never let an old Adventure save alter the active Adventure baseline.
                    if(String(activeAdventure?.id||"")===job.adventureId&&
                       __dataBaselineAdventureId===job.adventureId){
                        __dataBaseline.set(job.key,job.fingerprint);
                    }
                    changed.push(job.key);
                }
                return changed;
            };

            const queued=__alekPersistenceQueue.then(run,run);
            __alekPersistenceQueue=queued.then(()=>undefined,()=>undefined);
            return await queued;
        };

