const alekItemTypeSigilDataUri=typeId=>{
    const index=Math.max(0,ALEK_ITEM_TYPES.findIndex(type=>type.id===String(typeId||""))),hue=ALEK_ITEM_SIGIL_HUES[index]??190,nextHue=ALEK_ITEM_SIGIL_HUES[(index+7)%ALEK_ITEM_SIGIL_HUES.length]??44,glyph=ALEK_ITEM_GLYPHS[String(typeId||"")]||ALEK_ITEM_GLYPHS.other,frame=ALEK_ITEM_SIGIL_FRAMES[index%ALEK_ITEM_SIGIL_FRAMES.length],phase=(index*29)%360,dash=1.1+(index%4)*.65;
    const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><defs><radialGradient id="b" cx="34%" cy="25%"><stop stop-color="hsl(${hue} 91% 42%)" stop-opacity=".88"/><stop offset=".3" stop-color="hsl(${hue} 55% 16%)"/><stop offset=".68" stop-color="#041019"/><stop offset="1" stop-color="#010305"/></radialGradient><linearGradient id="r" x1=".08" y1=".1" x2=".92" y2=".9"><stop stop-color="hsl(${hue} 100% 74%)"/><stop offset=".43" stop-color="#fff0a2"/><stop offset="1" stop-color="hsl(${nextHue} 100% 68%)"/></linearGradient><radialGradient id="c"><stop stop-color="#fffbd1"/><stop offset=".35" stop-color="hsl(${hue} 100% 72%)"/><stop offset="1" stop-color="hsl(${nextHue} 90% 42%)"/></radialGradient><filter id="g" x="-60%" y="-60%" width="220%" height="220%"><feGaussianBlur stdDeviation="1.35" result="x"/><feMerge><feMergeNode in="x"/><feMergeNode in="SourceGraphic"/></feMerge></filter><filter id="s" x="-60%" y="-60%" width="220%" height="220%"><feDropShadow dx="0" dy="0" stdDeviation="1.15" flood-color="hsl(${hue} 100% 68%)"/></filter></defs><circle cx="32" cy="32" r="30.5" fill="url(#b)" stroke="#e9bc4f" stroke-width="1.15"/><circle cx="32" cy="32" r="28.8" fill="none" stroke="hsl(${nextHue} 96% 69%)" stroke-width=".55" opacity=".52"/><circle cx="32" cy="32" r="26" fill="none" stroke="url(#r)" stroke-width=".9" stroke-dasharray="${dash} 2.2" stroke-dashoffset="${index*.8}" opacity=".9"/><g fill="none" stroke="url(#r)" stroke-width=".72" stroke-linecap="round" stroke-linejoin="round" opacity=".78">${frame}</g><g transform="rotate(${phase} 32 32)" fill="none" stroke="hsl(${hue} 100% 73%)" stroke-width=".7" opacity=".72"><path d="M32 5v5m0 44v5M5 32h5m44 0h5"/><path d="M18 7l2 5-5-2m31-3-2 5 5-2m-3 47-2-5 5 2m-31 3 2-5-5 2"/></g><path d="m32 15 17 17-17 17-17-17Z" fill="hsl(${hue} 94% 55%)" fill-opacity=".055" stroke="#e8bd55" stroke-width=".45" opacity=".8"/><g fill="none" stroke="hsl(${hue} 100% 55%)" stroke-width="4.4" stroke-linecap="round" stroke-linejoin="round" opacity=".18" filter="url(#g)">${glyph}</g><g fill="none" stroke="url(#r)" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round" filter="url(#s)">${glyph}</g><circle cx="32" cy="32" r="2.65" fill="url(#c)" stroke="#fff0a7" stroke-width=".55" filter="url(#g)"/></svg>`;
    return`data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;
};
