v19Style.textContent=`.linked-media-status.external{color:#79d5ef}.bard-v19 .bard-now{flex:0 0 auto;min-height:190px;margin:14px 0 10px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;padding:24px;text-align:center}.bard-v19 .bard-track-name{max-width:90%;font-size:1.18em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.bard-play-indicator{display:inline-flex;align-items:center;justify-content:center;border:1px solid #465563;border-radius:999px;padding:6px 12px;font-size:.78em;letter-spacing:.06em}.bard-play-indicator.playing{color:#8ff0bd;border-color:#3d8f68;background:rgba(27,101,67,.18);box-shadow:0 0 16px rgba(65,211,142,.14)}.bard-play-indicator.paused{color:#9ca8b4;background:rgba(255,255,255,.025)}.bard-v19 .bard-controls{margin:4px 0 10px}.bard-v19 .bard-controls button{width:58px;height:46px}.bard-v19 .bard-controls .bard-toggle{width:70px;font-size:1.08em}.bard-v19 .bard-controls .bard-toggle.playing{border-color:#75d6a5;color:#aaf3ca;box-shadow:0 0 16px rgba(75,214,145,.18)}.bard-v19 .bard-channel-meta{position:static;display:flex;align-items:center;justify-content:center;gap:18px;margin:0 0 10px;padding:7px 10px;border:1px solid rgba(62,79,91,.55);border-radius:9px;background:rgba(7,12,16,.55);color:#9eabb8;font-size:.84em}.bard-v19 .bard-channel-meta span+span:before{content:"•";margin-right:18px;color:#d2b660}.bard-v19 .bard-volume{grid-template-columns:auto minmax(0,1fr) 54px;margin:0 0 12px}.bard-v19 .bard-volume-value{text-align:right;color:#d9c071;font-variant-numeric:tabular-nums}`;
