Object.assign(overlay.style,{backdropFilter:"none",WebkitBackdropFilter:"none"});

await refreshPinTypesFromFolder();
ALEK_VOICE_SPEAKERS = []; // Voice özelliği ayrı uygulamadadır.
const syncMediaPowerState=()=>{
    if(!ambianceCanRun()){
        if(performanceConfig.pauseWhenHidden)pauseAmbianceRuntime({release:false});
        v2Content?.querySelectorAll?.("video").forEach(video=>{try{video.pause();}catch(_){}});
        return;
    }
    updateAtmosphereDisplay();
    if(activeV2View==="performer")v2Content?.querySelectorAll?.("video[autoplay]").forEach(video=>video.play().catch(()=>{}));
};
document.addEventListener("visibilitychange",syncMediaPowerState);
window.addEventListener("focus",syncMediaPowerState);
window.addEventListener("blur",syncMediaPowerState);
window.addEventListener("alek:resource-state",syncMediaPowerState);
ensureV4Data();
// Açılışta hiçbir veri dosyası yazılmaz. Kalıcılık tabanı arayüz kurulmadan hemen önce alınır.

// Eski başlık ve sekmeleri sakla. İşlevler bellekte kalır.
header.style.display = "none";
