const modifierIntentAlive=until=>Number(until||0)>=Date.now();
const isEPointerIntent=()=>keyEDown&&modifierIntentAlive(keyEIntentUntil);
const isWPointerIntent=()=>keyWDown&&modifierIntentAlive(keyWIntentUntil);
const isSPointerIntent=()=>keySDown&&modifierIntentAlive(keySIntentUntil);
const consumeEPointerIntent=()=>{const active=isEPointerIntent();keyEDown=false;keyEIntentUntil=0;return active;};
const consumeWPointerIntent=()=>{const active=isWPointerIntent();keyWDown=false;keyWIntentUntil=0;return active;};
const consumeSPointerIntent=()=>{const active=isSPointerIntent();keySDown=false;keySIntentUntil=0;return active;};
