// F1–F3 yüzey geçişleri ve merkezi Esc yöneticisi bu sürüklenebilir paneli de
// tek yaşam-döngüsü kapısından kapatır; aksi halde panel yeni ana yüzeyin üstünde kalıyordu.
window.__alekCloseEmojiKeyboard=()=>{void closeEmojiKeyboard();return true;};
const openEmojiKeyboard = () => {
    if (emojiKeyboardPanel) { closeEmojiKeyboard(); return; }
    const state=storyData.settings.emojiKeyboard;
    const panel=document.createElement("div");panel.className="alek-emoji-keyboard";
    panel.style.left=`${Number(state.x)||40}px`;panel.style.top=`${Number(state.y)||90}px`;
    const head=document.createElement("div");head.className="emoji-keyboard-head";
    const label=document.createElement("strong");label.textContent="A̤ɐ͜ɨǣ́ꞎ͡ƣ İmge Paleti";
    const close=document.createElement("button");close.textContent="×";head.append(label,close);
    const tabs=document.createElement("div");tabs.className="image-palette-tabs";
    const paletteModes=[
        {id:"images",label:"İmgeler",items:()=>ALEK_IMAGE_PALETTE},
        {id:"alphabet",label:"240 Harf",items:()=>ALEK_ALPHABET_240},
        {id:"meaning-weave",label:"24 Anlam-Örgü",items:()=>ALEK_MEANING_WEAVE_24},
        {id:"resonance",label:"24 Rezonans",items:()=>ALEK_RESONANCE_24}
    ];
    if(!paletteModes.some(mode=>mode.id===state.tab)) state.tab="images";
    const tabButtons=new Map();
    paletteModes.forEach(mode=>{
        const button=document.createElement("button");
        button.type="button";button.textContent=mode.label;button.dataset.paletteTab=mode.id;
        button.onclick=()=>{state.tab=mode.id;draw();scheduleAutoSave(null,100);};
        tabs.appendChild(button);tabButtons.set(mode.id,button);
    });
    const grid=document.createElement("div");grid.className="emoji-keyboard-grid";
    const draw=()=>{
        const mode=paletteModes.find(item=>item.id===state.tab)||paletteModes[0];
        tabButtons.forEach((button,id)=>button.classList.toggle("active",id===mode.id));
        grid.className=`emoji-keyboard-grid palette-${mode.id}`;
        grid.innerHTML="";
        mode.items().forEach(item=>{
            const entry=typeof item==="string"?{display:item,insert:item,name:"",description:""}:item;
            const b=document.createElement("button");b.type="button";
            if(entry.name){
                b.classList.add("named-palette-symbol");
                const symbol=document.createElement("span");symbol.className="palette-symbol";symbol.textContent=entry.display;
                const name=document.createElement("small");name.textContent=entry.name;
                b.append(symbol,name);
            } else b.textContent=entry.display;
            b.title=entry.name?`${entry.name} · ${entry.description}`:(mode.id==="alphabet"?`Aktarım harfi: ${entry.display}`:entry.display);
            b.setAttribute("aria-label",entry.name||entry.display);
            b.onclick=()=>insertEmojiIntoTarget(entry.insert);
            grid.appendChild(b);
        });
    };
    panel.append(head,tabs,grid);mainPanel.appendChild(panel);emojiKeyboardPanel=panel;state.open=true;draw();scheduleAutoSave(null,100);
    let drag=null;
    head.addEventListener("pointerdown",e=>{if(e.target===close||e.button!==0)return;drag={x:e.clientX,y:e.clientY,left:panel.offsetLeft,top:panel.offsetTop};try{head.setPointerCapture(e.pointerId);}catch(_){}});
    head.addEventListener("pointermove",e=>{if(!drag)return;const left=drag.left+e.clientX-drag.x,top=drag.top+e.clientY-drag.y;panel.style.left=`${left}px`;panel.style.top=`${top}px`;state.x=left;state.y=top;});
    head.addEventListener("pointerup",e=>{if(!drag)return;drag=null;try{head.releasePointerCapture(e.pointerId);}catch(_){}scheduleAutoSave(null,120);});
    close.onclick=closeEmojiKeyboard;
};
