const downloadDataVaultBlob=(blob,fileName)=>{
    const url=URL.createObjectURL(blob),anchor=document.createElement("a");
    anchor.href=url;anchor.download=fileName;anchor.style.display="none";document.body.appendChild(anchor);anchor.click();anchor.remove();
    setTimeout(()=>URL.revokeObjectURL(url),30000);
};
const listPortableUserFiles=async()=>{
    const found=[];
    const walk=async path=>{
        const listed=await window.__alekList(path);
        if(!listed?.ok)return;
        for(const item of listed.items||[]){
            const child=`${path}/${item.name}`;
            if(item.type==="directory")await walk(child);
            else found.push(child);
        }
    };
    await walk("Data");await walk("Games");return found.sort((a,b)=>a.localeCompare(b,"tr"));
};
const createPortableJsonVault=async({prefix="Alekrythae-Meggy-Veri"}={})=>{
    const paths=await listPortableUserFiles(),files=[];
    for(const path of paths){
        const response=await fetch(`${_toVirtualUrl(path)}?data_vault=${Date.now()}`,{cache:"no-store"});
        if(!response.ok)throw new Error(`Veri dosyası okunamadı: ${path}`);
        const buffer=await response.arrayBuffer();
        files.push({path,size:buffer.byteLength,sha256:await sha256Hex(buffer),base64:arrayBufferToBase64(buffer)});
    }
    const stamp=new Date().toISOString().replace(/[:T]/g,"-").replace(/\.\d+Z$/,""),fileName=`${prefix}-${stamp}.alekdata`;
    const packageData={
        format:"alekrythae.meggy.data-json",formatVersion:2,appVersion:"0.1.0",architectureRevision:3,
        createdUtc:new Date().toISOString(),storage:"portable-raw-sqlite-and-media",migrationPolicy:"preserve-known-and-unknown-fields",forwardCompatible:true,files
    };
    const blob=new Blob([JSON.stringify(packageData)],{type:"application/x-alekrythae-data+json"});
    return{blob,fileName,files:files.length,games:(adventureRegistry?.adventures||[]).length};
};
const exportPortableDataFallback=async({prefix="Alekrythae-Meggy-Veri",notify=true}={})=>{
    const vault=await createPortableJsonVault({prefix});downloadDataVaultBlob(vault.blob,vault.fileName);
    if(notify)new Notice(`✦ ${vault.games} macera ve ${vault.files} veri dosyası ${vault.fileName} kasasına aktarıldı.`,8000);
    return vault;
};
const choosePortableFileFallback=()=>new Promise(resolve=>{
    const input=document.createElement("input");input.type="file";input.accept=".alekdata,.json,application/json";input.style.display="none";
    input.onchange=()=>{const file=input.files?.[0]||null;input.remove();resolve(file);};
    input.addEventListener("cancel",()=>{input.remove();resolve(null);},{once:true});document.body.appendChild(input);input.click();
});
const chooseMeggyFolderFallback=()=>new Promise(resolve=>{
    const input=document.createElement("input");input.type="file";input.multiple=true;input.setAttribute("webkitdirectory","");input.style.display="none";
    input.onchange=()=>{const files=[...(input.files||[])];input.remove();resolve(files);};
    input.addEventListener("cancel",()=>{input.remove();resolve([]);},{once:true});document.body.appendChild(input);input.click();
});
const portablePathFromFolderFile=file=>{
    const raw=String(file.webkitRelativePath||file.name||"").replace(/\\/g,"/"),meggy=raw.lastIndexOf("/Meggy/");
    const relative=meggy>=0?raw.slice(meggy+7):raw;
    if(relative.startsWith("Data/")||relative.startsWith("Games/"))return relative;
    const dataAt=relative.indexOf("/Data/"),gamesAt=relative.indexOf("/Games/");
    if(dataAt>=0)return relative.slice(dataAt+1);if(gamesAt>=0)return relative.slice(gamesAt+1);return"";
};
const packageFromMeggyFolderFiles=async selected=>{
    const files=[];
    for(const file of selected){
        const path=portablePathFromFolderFile(file);
        if(!path||/(?:\.tmp|\.partial)$/i.test(path))continue;
        const buffer=await file.arrayBuffer();files.push({path,size:buffer.byteLength,sha256:await sha256Hex(buffer),base64:arrayBufferToBase64(buffer)});
    }
    if(!files.some(item=>item.path==="Data/meggy.db")&&!files.some(item=>/^Games\/[^/]+\/game\.db$/i.test(item.path)))throw new Error("Seçilen klasörde meggy.db veya game.db bulunamadı.");
    return{format:"alekrythae.meggy.data-json",formatVersion:2,architectureRevision:2,createdUtc:new Date().toISOString(),storage:"legacy-folder-restore",migrationPolicy:"preserve-known-and-unknown-fields",forwardCompatible:true,files};
};
const validatePortableJsonPackage=async data=>{
    if(data?.format!=="alekrythae.meggy.data-json"||Number(data.formatVersion)<1||Number(data.formatVersion)>2||!Array.isArray(data.files))throw new Error("Bu .alekdata paketi tanınmadı veya bu sürümden daha yeni bir kasa biçimi kullanıyor.");
    for(const item of data.files){
        const path=String(item?.path||"").replace(/\\/g,"/");
        if(!/^(Data|Games)\//i.test(path)||path.includes(":")||path.split("/").includes(".."))throw new Error(`Güvenli olmayan veri yolu: ${path}`);
        const binary=atob(String(item.base64||"")),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);
        if(bytes.byteLength!==Number(item.size)||await sha256Hex(bytes.buffer)!==String(item.sha256||"").toLowerCase())throw new Error(`Veri kasası bütünlük denetimi başarısız: ${path}`);
        item.__bytes=bytes;
    }
    return data;
};
const restorePortableJsonPackage=async packageData=>{
    const data=await validatePortableJsonPackage(packageData);
    await exportPortableDataFallback({prefix:"Alekrythae-Oncesi-Yedek",notify:false});
    const databasePaths=data.files.map(item=>item.path).filter(path=>/\.db$/i.test(path));
    for(const path of databasePaths){
        try{await window.__alekDelete(`${path}-wal`);}catch(_){}try{await window.__alekDelete(`${path}-shm`);}catch(_){}
    }
    const ordered=[...data.files].sort((a,b)=>/(?:-wal|-shm)$/i.test(a.path)-/(?:-wal|-shm)$/i.test(b.path));
    for(const item of ordered){
        const result=await window.__alekWriteBinary(item.path,arrayBufferToBase64(item.__bytes.buffer));
        if(!result?.ok)throw new Error(`Veri yazılamadı: ${item.path}`);
        delete item.__bytes;
    }
    return{importedAdventures:Math.max(1,data.files.filter(item=>/\/game\.db$/i.test(item.path)).length)};
};
const importSingleLegacyJsonFallback=async file=>{
    const data=JSON.parse(await file.text()),base=String(file.name||"Eski Meggy Dünyası").replace(/\.json$/i,"")||"Eski Meggy Dünyası";
    const response=await window.__alekRegistryRead(),registry=response?.ok&&response.data?response.data:{meta:{schemaVersion:2},activeId:"",adventures:[]};
    registry.adventures=Array.isArray(registry.adventures)?registry.adventures:[];
    let name=base,folder=normalizeAdventureFolder(base)||"Eski Meggy Dünyası",suffix=2;
    while(registry.adventures.some(item=>String(item.name).localeCompare(name,"tr",{sensitivity:"base"})===0||String(item.folder).localeCompare(folder,"tr",{sensitivity:"base"})===0)){name=`${base} · İçe Aktarılan ${suffix}`;folder=normalizeAdventureFolder(name);suffix++;}
    const id=makeId("adventure_import"),now=new Date().toISOString(),record={id,name,folder,cover:"",mode:"alekrytha",coverPolicy:"none",createdAt:now,updatedAt:now};
    await window.__alekGameEnsure(folder,"alekrytha");
    const key=({"character":"characters","location":"locations","group":"groups","mount":"mounts","forgotten":"forgotten","afmv":"special","map":"map","tideofaia":"tide","lore":"lore","reverie":"reverie","maplibrary":"mapLibrary","harmonizer":"harmonizer"})[base.toLowerCase()]||"story";
    const written=await window.__alekGameWrite(folder,key,data);if(!written?.ok)throw new Error(written?.error||"Eski JSON verisi yazılamadı.");
    registry.adventures.push(record);registry.activeId=id;const saved=await window.__alekRegistryWrite(registry);if(!saved?.ok)throw new Error(saved?.error||"Macera listesi güncellenemedi.");
    return{importedAdventures:1};
};
const importPortableFileFallback=async file=>{
    const parsed=JSON.parse(await file.text());
    if(parsed?.format==="alekrythae.meggy.data-json")return restorePortableJsonPackage(parsed);
    return importSingleLegacyJsonFallback(file);
};
const exportAllMeggyData=async()=>{
    setDataTransferBusy(true,"export");
    try{
        const saved=await saveToDB(null);
        if(!saved)throw new Error("Açık macera dışa aktarmadan önce kaydedilemedi.");
        beginDataTransferLock();
        if(typeof window.__alekDataExport!=="function"){
            await exportPortableDataFallback();return;
        }
        const result=await window.__alekDataExport();
        if(!result?.ok)throw new Error(dataTransferErrorText(result));
        if(result.cancelled)return;
        const games=Math.max(0,Number(result.games)||0),files=Math.max(0,Number(result.files)||0);
        new Notice(`✦ ${games} macera ve ${files} veri dosyası ${result.fileName||".alekdata kasasına"} aktarıldı.`,8000);
    }catch(error){
        console.error("Veri dışa aktarma hatası",error);
        new Notice(`Veri dışa aktarılamadı: ${error?.message||error}`,9000);
    }finally{
        endDataTransferLock();setDataTransferBusy(false);
    }
};
const openImportDataVault=()=>{
    const nativeDataVault=typeof window.__alekDataImport==="function";
    const wrap=document.createElement("div");wrap.className="data-vault-import-sheet";
    wrap.innerHTML=`
        <div class="data-vault-import-sigil" aria-hidden="true"><span>↧</span></div>
        <div class="data-vault-import-copy">
            <small>SÜRÜMLER ARASI VERİ GEÇİDİ</small>
            <strong>Eski verin kaybolmadan güncel sisteme uyarlanacak.</strong>
            <p>${nativeDataVault?`<code>.alekdata</code>, eski Meggy <code>.zip</code> paketleri, <code>meggy.db / game.db</code> ve eski <code>.json</code> kayıtları tanınır.`:`<code>.alekdata</code>, eski <code>.json</code> kaydı veya aşağıdaki düğmeyle eski Meggy klasörü seçilebilir.`}</p>
        </div>
        <div class="data-vault-safety-grid">
            <article><b>Ⅰ</b><span><strong>Önce yedek</strong><small>Mevcut bütün verinin geri dönüş kasası otomatik oluşturulur.</small></span></article>
            <article><b>Ⅱ</b><span><strong>Şema uyarlama</strong><small>Eski JSON ve SQLite belge anahtarları güncel veri katmanına taşınır.</small></span></article>
            ${nativeDataVault?`<article><b>Ⅲ</b><span><strong>Üstüne yazmaz</strong><small>Ad veya klasör çakışırsa içe aktarılan macera güvenli bir kopya olur.</small></span></article>`:`<article><b>Ⅲ</b><span><strong>Güvenli geri yükleme</strong><small>Eski klasör geri yüklenmeden önce bugünkü veri ayrıca .alekdata yedeği olarak indirilir.</small></span></article>`}
        </div>
        <div class="data-vault-import-warning">İşlem bitince Meggy yeni veriyi açmak için bir kez yenilenecek.</div>
        ${nativeDataVault?"":`<button type="button" class="data-vault-folder-import">Eski Sürüm Klasöründen Kurtar</button>`}`;
    const folderButton=wrap.querySelector(".data-vault-folder-import");
    if(folderButton)folderButton.onclick=async()=>{
        const selected=await chooseMeggyFolderFallback();if(!selected.length)return;
        setDataTransferBusy(true,"import");
        try{const saved=await saveToDB(null);if(!saved)throw new Error("Açık macera kaydedilemedi.");beginDataTransferLock();const packageData=await packageFromMeggyFolderFiles(selected);const result=await restorePortableJsonPackage(packageData);new Notice(`✦ ${result.importedAdventures} eski macera içeri alındı. Meggy yenileniyor…`,9000);setTimeout(()=>location.reload(),1250);}catch(error){endDataTransferLock();setDataTransferBusy(false);new Notice(`Eski klasör içeri alınamadı: ${error?.message||error}`,10000);}
    };
    showV2Modal({
        title:"Veriyi İçeri Aktar",
        body:wrap,
        saveText:"Alekdata Dosyasını Seç",
        wide:true,
        onSave:async(_body,shade)=>{
            const saveButton=shade.querySelector(".alek-v2-modal-actions .primary");
            if(saveButton){saveButton.disabled=true;saveButton.textContent="Veri Geçidi Açılıyor…";}
            setDataTransferBusy(true,"import");
            try{
                const saved=await saveToDB(null);
                if(!saved)throw new Error("Açık macera içe aktarmadan önce kaydedilemedi.");
                beginDataTransferLock();
                const result=nativeDataVault?await window.__alekDataImport():await (async()=>{const file=await choosePortableFileFallback();if(!file)return{ok:true,cancelled:true};const imported=await importPortableFileFallback(file);return{ok:true,...imported,reloadRequired:true};})();
                if(!result?.ok)throw new Error(dataTransferErrorText(result));
                if(result.cancelled){endDataTransferLock();return true;}
                const count=Math.max(0,Number(result.importedAdventures)||0);
                new Notice(`✦ ${count} macera uyarlanarak içeri alındı. Meggy yenileniyor…`,9000);
                setTimeout(()=>location.reload(),1250);
                return true;
            }catch(error){
                endDataTransferLock();
                console.error("Veri içe aktarma hatası",error);
                new Notice(`Veri içeri aktarılamadı: ${error?.message||error}`,10000);
                return false;
            }finally{
                if(window.__ALEK_DATA_TRANSFER_LOCK__!==true)setDataTransferBusy(false);
                if(saveButton&&window.__ALEK_DATA_TRANSFER_LOCK__!==true){saveButton.disabled=false;saveButton.textContent="Alekdata Dosyasını Seç";}
            }
        }
    });
};
dataTransferButtons.forEach(button=>button.addEventListener("click",event=>{
    event.preventDefault();event.stopPropagation();
    if(button.dataset.dataTransfer==="export")void exportAllMeggyData();
    else openImportDataVault();
}));

// R58 · Başlangıç zamanı yalnız görünür çalışma arayüzü hazırlandıktan sonra açılır.
// Tek bir bekleyen işlem tutulur; macera değişimi veya silme sırasında eski Promise
// çözümsüz bırakılmaz. Böylece görünmez modal F1/F2/F3'ü sonsuza dek kilitleyemez.
let __alekStartTimeConfiguration=null;
const __alekFinishStartTimeConfiguration=(pending,result,{remove=true}={})=>{
    if(!pending||pending.settled)return false;
    pending.settled=true;
    if(pending.onKeyDown)window.removeEventListener("keydown",pending.onKeyDown,true);
    if(remove)pending.modal?.shade?.remove();
    pending.resolve?.(result===true);
    if(__alekStartTimeConfiguration===pending)__alekStartTimeConfiguration=null;
    return true;
};
const __alekCancelPendingStartTimeConfiguration=()=>{
    const pending=__alekStartTimeConfiguration;
    return pending?__alekFinishStartTimeConfiguration(pending,false):false;
};
window.__alekCancelPendingStartTimeConfiguration=__alekCancelPendingStartTimeConfiguration;
const ensureNonRealtimeStartTimeConfigured = () => {
    const game=normalizeGameRuntime(),adventureId=String(activeAdventure?.id||"");
    if(!adventureId)return Promise.resolve(false);
    if(game.mode==="real_world"||game.time.startConfigured===true)return Promise.resolve(true);
    const existing=__alekStartTimeConfiguration;
    if(existing&&existing.adventureId===adventureId&&existing.modal?.shade?.isConnected)return existing.promise;
    if(existing)__alekCancelPendingStartTimeConfiguration();

    const pending={adventureId,modal:null,promise:null,resolve:null,settled:false,busy:false,onKeyDown:null};
    pending.promise=new Promise(resolve=>{pending.resolve=resolve;});
    __alekStartTimeConfiguration=pending;

    const isAlek=game.mode==="alekrytha";
    const monthNames=calendarMonthsForGameMode(game.mode);
    const wrap=document.createElement("div");wrap.className="fantasy-start-time-builder";
    const intro=document.createElement("div");intro.className="fantasy-start-time-intro";
    intro.innerHTML=`<strong>${isAlek?"Ałek’ryŧhæ Zaman Mührü":"Öte Diyar Başlangıç Mührü"}</strong><span>Bu macerada bilgisayar saati kullanılmaz. Dünyanın ilk gününü bir kez belirle; bundan sonra zaman yalnız eylem, konuşma, seyahat ve dinlenmeyle ilerler.</span>`;
    const year=document.createElement("input");year.type="number";year.step="1";year.min=isAlek?"0":"1";year.value=String(Math.max(isAlek?0:1,Number(game.time.year)||(isAlek?24000:1)));
    const month=document.createElement("select");monthNames.forEach((name,index)=>{const option=document.createElement("option");option.value=String(index+1);option.textContent=`${index+1}. Ay · ${name}`;month.appendChild(option);});month.value=String(Math.max(1,Math.min(monthNames.length,Number(game.time.month)||1)));
    const day=document.createElement("input");day.type="number";day.step="1";day.min="1";
    const maxHour=isAlek?ALEK_HOURS_PER_DAY-1:23,maxMinute=isAlek?ALEK_MINUTES_PER_HOUR-1:59;
    const hour=document.createElement("input");hour.type="number";hour.min="0";hour.max=String(maxHour);hour.step="1";hour.value=String(Math.max(0,Math.min(maxHour,Number(game.time.hour)||8)));
    const minute=document.createElement("input");minute.type="number";minute.min="0";minute.max=String(maxMinute);minute.step="1";minute.value=String(Math.max(0,Math.min(maxMinute,Number(game.time.minute)||0)));
    const preview=document.createElement("div");preview.className="fantasy-start-time-preview";
    const sync=()=>{
        const y=Math.max(isAlek?0:1,Math.trunc(Number(year.value)||(isAlek?0:1)));
        const m=Math.max(1,Math.min(monthNames.length,Math.trunc(Number(month.value)||1)));
        const maxDay=calendarDaysInMonthForMode(game.mode,y,m);day.max=String(maxDay);day.value=String(Math.max(1,Math.min(maxDay,Math.trunc(Number(day.value)||Number(game.time.day)||1))));
        const h=Math.max(0,Math.min(maxHour,Math.trunc(Number(hour.value)||0))),min=Math.max(0,Math.min(maxMinute,Math.trunc(Number(minute.value)||0)));
        preview.innerHTML=`<small>Macera şu vakitte başlayacak</small><strong>${day.value}. Gün · ${m}. Ay · Yıl ${y} · ${String(h).padStart(2,"0")}:${String(min).padStart(isAlek?3:2,"0")}</strong>`;
    };
    day.value=String(Math.max(1,Number(game.time.day)||1));[year,month,day,hour,minute].forEach(control=>control.addEventListener("input",sync));month.addEventListener("change",sync);sync();
    const grid=document.createElement("div");grid.className="fantasy-start-time-grid";grid.append(makeLabeledField("Yıl",year),makeLabeledField("Ay",month),makeLabeledField("Gün",day),makeLabeledField("Saat",hour),makeLabeledField("Dakika",minute));wrap.append(intro,grid,preview);

    let continueButton=null;
    const setBusy=busy=>{pending.busy=!!busy;if(pending.modal?.save)pending.modal.save.disabled=!!busy;if(continueButton)continueButton.disabled=!!busy;};
    const commit=async()=>{
        if(pending.settled)return true;
        if(pending.busy)return false;
        if(String(activeAdventure?.id||"")!==adventureId){__alekFinishStartTimeConfiguration(pending,false);return false;}
        setBusy(true);
        try{
            const y=Math.max(isAlek?0:1,Math.trunc(Number(year.value)||(isAlek?0:1)));
            const m=Math.max(1,Math.min(monthNames.length,Math.trunc(Number(month.value)||1)));
            const maxDay=calendarDaysInMonthForMode(game.mode,y,m);
            const d=Math.max(1,Math.min(maxDay,Math.trunc(Number(day.value)||1)));
            const h=Math.max(0,Math.min(maxHour,Math.trunc(Number(hour.value)||0)));
            const min=Math.max(0,Math.min(maxMinute,Math.trunc(Number(minute.value)||0)));
            Object.assign(game.time,{year:y,month:m,day:d,hour:h,minute:min,second:0,startConfigured:true,startConfiguredAt:new Date().toISOString(),lastRealTimestamp:Date.now()});
            if(game.mode==="other_realm"){const season=otherRealmSeasonInfo(m);game.time.season=season.seasonKey;game.time.seasonMonthIndex=season.monthIndex;}
            storyData.calendar=Object.assign({},storyData.calendar||{},{currentYear:y,currentMonth:m,selectedDay:d,view:"stage"});
            syncCalendarFromGameTime();
            const journeyPath=String(DATA_PATHS.journey||"");
            await writeJsonSafe(journeyPath,storyData);
            if(String(activeAdventure?.id||"")!==adventureId){__alekFinishStartTimeConfiguration(pending,false);return false;}
            updateAdventureNavButton();
            __alekFinishStartTimeConfiguration(pending,true);
            return true;
        }catch(error){
            console.error("Başlangıç zamanı kaydedilemedi",error);
            new Notice(`Başlangıç zamanı kaydedilemedi: ${error?.message||error}`,8000);
            setBusy(false);
            return false;
        }
    };
    const modal=showV2Modal({title:"Başlangıç Gününü Belirle",body:wrap,saveText:"Başlangıcı Mühürle",wide:true,onSave:commit});
    pending.modal=modal;
    modal.shade.classList.add("adventure-start-time-modal");
    modal.shade.dataset.adventureId=adventureId;
    continueButton=modal.box.querySelector(".alek-v2-modal-actions button:not(.primary)");
    if(continueButton){
        continueButton.textContent="Mevcut Değerle Başla";
        continueButton.onclick=event=>{event.preventDefault();event.stopPropagation();void commit();};
    }
    modal.shade.__alekRequestCancel=()=>{void commit();};
    modal.shade.onclick=event=>{if(event.target===modal.shade){event.preventDefault();event.stopPropagation();}};
    pending.onKeyDown=event=>{if(event.key!=="Escape")return;event.preventDefault();event.stopPropagation();event.stopImmediatePropagation?.();void commit();};
    window.addEventListener("keydown",pending.onKeyDown,true);
    requestAnimationFrame(()=>year.focus());
    return pending.promise;
};

const ensureSelectedDate = () => {
    const cal = storyData.calendar,mode=normalizeGameRuntime().mode;
    const minimumYear=mode==="real_world"?1:0,monthCount=calendarMonthsForGameMode(mode).length;
    cal.currentYear=Math.max(minimumYear,Math.trunc(Number(cal.currentYear)||minimumYear));
    cal.currentMonth=Math.max(1,Math.min(monthCount,Math.trunc(Number(cal.currentMonth)||1)));
    const dayCount=calendarDaysInMonthForMode(mode,cal.currentYear,cal.currentMonth);
    cal.selectedDay=Math.max(1,Math.min(dayCount,Math.trunc(Number(cal.selectedDay)||1)));
    return {year:cal.currentYear, month:cal.currentMonth, day:cal.selectedDay};
};

const addEntityToTavern=async entity=>{
    if(!characterCanJoinMeggyDialogue(entity)){new Notice(`${fullNameOf(entity)} Metaneti tamamen çöktüğü için Meggy konuşmasına katılamaz. Metanet en az %50 olunca yeniden konuşabilir.`);return false;}
    const d=ensureSelectedDate(),day=getCalendarDay(d.year,d.month,d.day,true);
    if(!day.speakerIds.some(id=>String(id)===String(entity.id)))day.speakerIds.push(entity.id);
    storyData.calendar.view="stage";
    await saveToDB(`${fullNameOf(entity)} Tavern sahnesine geldi.`);
    return true;
};
const addCharacterToTavern = addEntityToTavern;
const entityIsOnTavernStage=entity=>{
    if(!entity)return false;const d=ensureSelectedDate(),day=getCalendarDay(d.year,d.month,d.day,true);
    return (day.speakerIds||[]).some(id=>String(id)===String(entity.id));
};
const toggleEntityOnTavernStage=async entity=>{
    if(!entity)return {ok:false,active:false};
    const d=ensureSelectedDate(),day=getCalendarDay(d.year,d.month,d.day,true),id=String(entity.id);
    const active=(day.speakerIds||[]).some(value=>String(value)===id);
    if(active){
        day.speakerIds=(day.speakerIds||[]).filter(value=>String(value)!==id);
        await saveToDB(`${fullNameOf(entity)} Tavern sahnesinden çıkarıldı.`);
        return {ok:true,active:false};
    }
    const ok=await addEntityToTavern(entity);return {ok:!!ok,active:!!ok};
};

