// Macera geçidi body seviyesindeki JoA/AI yüzeylerini arkasında açık bırakmaz.
// Devam eden F geçişinin seri numarası da iptal edilir; eski maceradan gecikmiş
// bir frame yeni maceranın üstüne Map/Mevcudat basamaz.
const __alekQuiescePrimarySurfacesForAdventure=async({saveWorld=true,rememberReturn=false}={})=>{
    if(rememberReturn&&!__alekAdventurePortalReturnSurface)__alekAdventurePortalReturnSurface=__alekResolveAdventureReturnSurface();
    ++__alekPrimaryTransitionSerial;
    __alekPrimaryTransitionChain=Promise.resolve();
    try{delete window.__ALEK_PENDING_JOA_SURFACE__;}catch(_){window.__ALEK_PENDING_JOA_SURFACE__=null;}
    try{delete window.__ALEK_SUPPRESS_JOA_AUTO_OPEN__;}catch(_){window.__ALEK_SUPPRESS_JOA_AUTO_OPEN__=null;}
    window.__alekDismissPrimaryNavigationOverlays?.();
    try{window.__alekCloseJoAWorld?.({save:saveWorld===true});}catch(error){console.warn("Macera geçidinde JoA yüzeyi kapatılamadı",error);}
    try{await closeSafeAiView?.();}catch(error){console.warn("Macera geçidinde AI yüzeyi kapatılamadı",error);}
    try{if(typeof journeyWorldOverlay!=="undefined"&&journeyWorldOverlay)await closeJourneyWorld({restore:false});}catch(error){console.warn("Eski Map yüzeyi kapatılamadı",error);}
    return __alekAdventurePortalReturnSurface||"map";
};
