// -------------------------- Reverie --------------------------
function normalizeReverieYearValue(value){let raw=String(value??"").trim().replace(/[^\d]/g,"");raw=raw.replace(/^0+(?=\d)/,"");return raw||"0";}
function stepReverieYearValue(value,delta){try{let next=BigInt(normalizeReverieYearValue(value))+BigInt(delta);if(next<0n)next=0n;return next.toString();}catch(_){const fallback=Math.max(0,(Number(normalizeReverieYearValue(value))||0)+delta);return String(fallback);}}
const reverieDateLabel = entry => {
    const mode=normalizeGameRuntime().mode,date=entry?.startDate||{},months=calendarMonthsForGameMode(mode);
    const minimumYear=mode==="real_world"?1:0,year=Math.max(minimumYear,Number(normalizeReverieYearValue(date.year??storyData.calendar?.currentYear))||minimumYear);
    const monthNumber=clamp(Number(date.month)||1,1,months.length),dayCount=calendarDaysInMonthForMode(mode,year,monthNumber);
    return `${clamp(Number(date.day)||1,1,dayCount)} ${months[monthNumber-1]||`Ay ${monthNumber}`} ${normalizeReverieYearValue(year)}`;
};
const reverieDefaultDate = () => {
    const mode=normalizeGameRuntime().mode,months=calendarMonthsForGameMode(mode),minimumYear=mode==="real_world"?1:0;
    const year=Math.max(minimumYear,Number(storyData.calendar?.currentYear)||minimumYear),month=clamp(Number(storyData.calendar?.currentMonth)||1,1,months.length);
    return{year:normalizeReverieYearValue(year),month,day:clamp(Number(storyData.calendar?.selectedDay)||1,1,calendarDaysInMonthForMode(mode,year,month))};
};
const findReverieEntry = id => (reverieData.entries||[]).find(entry=>String(entry.id)===String(id));
const fitReverieCardFrame=(card,img)=>fitImageRatioCard(card,img,{targetHeight:350,maxWidth:760,maxHeight:430,minWidth:176,minHeight:220});
const makeReverieVisual=(container,path,{sheet=false,title="Reverie"}={})=>{
    container.innerHTML="";container.classList.remove("portrait","landscape","square","ultrawide");
    if(!path){container.textContent="☾";container.style.removeProperty("--reverie-ratio");if(sheet){container.style.width="300px";container.style.height="400px";}return null;}
    const img=document.createElement("img");img.src=getDynamicUrl(path);img.alt=title;
    const apply=()=>{const w=Number(img.naturalWidth)||1,h=Number(img.naturalHeight)||1,ratio=w/h;container.style.setProperty("--reverie-ratio",String(ratio));container.classList.toggle("portrait",ratio<.82);container.classList.toggle("landscape",ratio>1.18);container.classList.toggle("ultrawide",ratio>2.1);container.classList.toggle("square",ratio>=.82&&ratio<=1.18);if(sheet){let height=clamp(400/Math.max(.45,ratio),260,650),width=clamp(height*ratio,230,560);if(ratio>1.18){width=clamp(500,300,560);height=clamp(width/ratio,230,430);}container.style.width=`${Math.round(width)}px`;container.style.height=`${Math.round(height)}px`;}};
    img.onload=apply;img.onerror=()=>{container.innerHTML="";container.textContent="☾";};container.appendChild(img);if(img.complete&&img.naturalWidth)apply();return img;
};
