const fitImageRatioCard=(card,img,{targetHeight=350,maxWidth=900,maxHeight=430,minWidth=168,minHeight=210}={})=>{
    if(!card)return;
    const fallback=()=>{card.style.width="220px";card.style.minWidth="220px";card.style.maxWidth="220px";card.style.height=`${Math.max(minHeight,310)}px`;card.style.minHeight=`${Math.max(minHeight,310)}px`;};
    const apply=()=>{
        const w=Number(img?.naturalWidth||0),h=Number(img?.naturalHeight||0);
        if(!(w>0&&h>0)){fallback();card.classList.remove("portrait","portrait-slim","landscape","landscape-wide","ultrawide","square");return;}
        const ratio=w/h;
        let height=Math.min(maxHeight,targetHeight);
        let width=height*ratio;
        if(width>maxWidth){width=maxWidth;height=width/ratio;}
        if(width<minWidth){width=minWidth;height=width/ratio;}
        if(height<minHeight&&ratio<=maxWidth/minHeight){height=minHeight;width=height*ratio;}
        width=Math.round(Math.min(maxWidth,Math.max(minWidth,width)));
        height=Math.round(Math.min(maxHeight,Math.max(150,height)));
        card.style.width=`${width}px`;
        card.style.minWidth=`${width}px`;
        card.style.maxWidth=`${width}px`;
        card.style.height=`${height}px`;
        card.style.minHeight=`${height}px`;
        card.style.setProperty("--cover-ratio",ratio.toFixed(4));
        card.classList.toggle("portrait",ratio<0.84);
        card.classList.toggle("portrait-slim",ratio<0.66);
        card.classList.toggle("landscape",ratio>1.18);
        card.classList.toggle("landscape-wide",ratio>1.65);
        card.classList.toggle("ultrawide",ratio>2.25);
        card.classList.toggle("square",ratio>=0.84&&ratio<=1.18);
    };
    if(img&&img.complete&&img.naturalWidth)apply();else if(img)img.addEventListener("load",apply,{once:true});else fallback();
};
const setAdventureCardFrame=(card,img)=>fitImageRatioCard(card,img,{targetHeight:350,maxWidth:900,maxHeight:430,minWidth:168,minHeight:210});
const bindAdventureCardMotion=card=>{if(!card)return;card.addEventListener("pointermove",event=>{const r=card.getBoundingClientRect(),nx=clamp((event.clientX-r.left)/Math.max(1,r.width),0,1)-.5,ny=clamp((event.clientY-r.top)/Math.max(1,r.height),0,1)-.5;card.style.setProperty("--card-rx",`${(-ny*4.5).toFixed(2)}deg`);card.style.setProperty("--card-ry",`${(nx*5.5).toFixed(2)}deg`);card.style.setProperty("--image-x",`${(-nx*7).toFixed(1)}px`);card.style.setProperty("--image-y",`${(-ny*7).toFixed(1)}px`);});card.addEventListener("pointerleave",()=>{card.style.setProperty("--card-rx","0deg");card.style.setProperty("--card-ry","0deg");card.style.setProperty("--image-x","0px");card.style.setProperty("--image-y","0px");});};
const alekNextPaint=()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve)));
const alekMoonVisualNode=element=>{
    if(!element)return null;
    if(element.tagName==="IMG")return element;
    return element.querySelector?.("img")||element;
};
const alekMoonVisualRect=element=>{
    const visual=alekMoonVisualNode(element);if(!visual)return null;
    const rect=visual.getBoundingClientRect();if(!rect.width||!rect.height)return null;
    const diameter=Math.max(1,Math.min(rect.width,rect.height));
    return{visual,diameter,cx:rect.left+rect.width/2,cy:rect.top+rect.height/2,rect};
};
const flyMoonBetween=async(sourceEl,targetEl,{duration=880,route="default",handoff=true}={})=>{
    if(!sourceEl||!targetEl||!sourceEl.isConnected||!targetEl.isConnected)return null;
    const targetImg=alekMoonVisualNode(targetEl);
    try{if(targetImg?.decode&&!targetImg.complete)await targetImg.decode();}catch(_){ }
    await alekNextPaint();
    const a=alekMoonVisualRect(sourceEl),b=alekMoonVisualRect(targetEl);
    if(!a||!b)return null;

    const oldTargetVisibility=targetEl.style.visibility;
    const oldTargetPlayState=targetEl.style.animationPlayState;
    const oldTargetOpacity=targetEl.style.opacity;
    targetEl.style.animationPlayState="paused";
    targetEl.style.opacity="0";
    targetEl.style.visibility="visible";

    const ghost=document.createElement("img");
    ghost.src=a.visual.currentSrc||a.visual.src||getDynamicUrl("Assets/Bluemoon.png");ghost.alt="";
    Object.assign(ghost.style,{
        position:"fixed",left:`${a.cx}px`,top:`${a.cy}px`,width:`${a.diameter}px`,height:`${a.diameter}px`,
        zIndex:"2147483646",pointerEvents:"none",objectFit:"contain",opacity:"1",
        filter:"brightness(1.04) drop-shadow(0 0 28px rgba(65,199,255,.66))",
        transform:"translate(-50%,-50%) translate3d(0,0,0) scale(1)",transformOrigin:"center center",willChange:"transform,filter,opacity"
    });
    document.body.appendChild(ghost);
    const oldSourceOpacity=sourceEl.style.opacity;
    const oldSourcePlayState=sourceEl.style.animationPlayState;
    sourceEl.style.animationPlayState="paused";
    sourceEl.style.opacity="0";

    const dx=b.cx-a.cx,dy=b.cy-a.cy,distance=Math.hypot(dx,dy);
    const scale=Math.max(.02,b.diameter/a.diameter);
    const arc=Math.min(route==="logo"?118:74,Math.max(route==="logo"?42:18,distance*(route==="logo"?.145:.105)));
    const midScale=Math.max(scale,Math.min(1.08,.72+scale*.34));
    const frames=route==="logo"?[
        {offset:0,transform:"translate(-50%,-50%) translate3d(0,0,0) scale(1)",filter:"brightness(1.04) drop-shadow(0 0 28px rgba(65,199,255,.66))",opacity:1},
        {offset:.14,transform:`translate(-50%,-50%) translate3d(${dx*.025}px,${dy*.025-14}px,0) scale(1.055)`,filter:"brightness(1.38) drop-shadow(0 0 50px rgba(100,225,255,.88))",opacity:1},
        {offset:.42,transform:`translate(-50%,-50%) translate3d(${dx*.31}px,${dy*.31-arc}px,0) scale(${Math.max(midScale,.72)})`,filter:"brightness(1.30) drop-shadow(0 0 44px rgba(74,210,255,.82))",opacity:1},
        {offset:.72,transform:`translate(-50%,-50%) translate3d(${dx*.72}px,${dy*.72-arc*.38}px,0) scale(${Math.max(scale*1.18,midScale*.72)})`,filter:"brightness(1.20) drop-shadow(0 0 34px rgba(66,202,255,.70))",opacity:1},
        {offset:.94,transform:`translate(-50%,-50%) translate3d(${dx*.96}px,${dy*.96-4}px,0) scale(${scale*1.035})`,filter:"brightness(1.10) drop-shadow(0 0 22px rgba(65,199,255,.52))",opacity:1},
        {offset:1,transform:`translate(-50%,-50%) translate3d(${dx}px,${dy}px,0) scale(${scale})`,filter:"brightness(1) drop-shadow(0 0 16px rgba(65,199,255,.38))",opacity:1}
    ]:[
        {offset:0,transform:"translate(-50%,-50%) translate3d(0,0,0) scale(1)",filter:"brightness(1.04) drop-shadow(0 0 28px rgba(65,199,255,.66))",opacity:1},
        {offset:.16,transform:`translate(-50%,-50%) translate3d(${dx*.045}px,${dy*.045-10}px,0) scale(1.065)`,filter:"brightness(1.42) drop-shadow(0 0 52px rgba(100,225,255,.9))",opacity:1},
        {offset:.58,transform:`translate(-50%,-50%) translate3d(${dx*.58}px,${dy*.58-arc}px,0) scale(${midScale})`,filter:"brightness(1.26) drop-shadow(0 0 40px rgba(70,205,255,.76))",opacity:1},
        {offset:.90,transform:`translate(-50%,-50%) translate3d(${dx*.93}px,${dy*.93-arc*.15}px,0) scale(${scale*1.055})`,filter:"brightness(1.15) drop-shadow(0 0 28px rgba(65,199,255,.58))",opacity:1},
        {offset:1,transform:`translate(-50%,-50%) translate3d(${dx}px,${dy}px,0) scale(${scale})`,filter:"brightness(1) drop-shadow(0 0 16px rgba(65,199,255,.38))",opacity:1}
    ];
    try{await ghost.animate(frames,{duration,easing:route==="logo"?"cubic-bezier(.18,.74,.16,1)":"cubic-bezier(.2,.76,.18,1)",fill:"forwards"}).finished;}catch(_){ }

    const finish=async({duration:fadeDuration=180}={})=>{
        if(!ghost.isConnected)return;
        targetEl.style.opacity="0";
        targetEl.style.visibility="visible";
        const targetFade=targetEl.animate([{opacity:0},{opacity:1}],{duration:fadeDuration,easing:"ease-out",fill:"forwards"});
        const ghostFade=ghost.animate([{opacity:1},{opacity:0}],{duration:fadeDuration,easing:"ease-out",fill:"forwards"});
        try{await Promise.all([targetFade.finished,ghostFade.finished]);}catch(_){ }
        ghost.remove();
        targetEl.style.opacity=oldTargetOpacity||"1";
        targetEl.style.visibility=oldTargetVisibility||"visible";
        targetEl.style.animationPlayState=oldTargetPlayState||"running";
        sourceEl.style.animationPlayState=oldSourcePlayState||"running";
        sourceEl.style.opacity=oldSourceOpacity;
    };
    const handle={ghost,targetEl,finish};
    if(handoff)await finish();
    return handle;
};
const revealAdventureInterface=async(portal,record,sourceCard)=>{
    if(!portal||portal.dataset.entering==="true")return;
    const returnSurface=__alekAdventurePortalReturnSurface||__alekResolveAdventureReturnSurface();
    portal.dataset.entering="true";portal.querySelectorAll("button").forEach(button=>button.disabled=true);sourceCard?.classList.add("adventure-entering");
    portal.querySelectorAll(".adventure-card").forEach(card=>{if(card!==sourceCard)card.animate([{opacity:1},{opacity:.12,filter:"blur(3px)"}],{duration:360,fill:"forwards"});});
    if(record?.id!==activeAdventure?.id)await loadAdventureRuntime(record,{notice:false});
    else{restoreAdventureUiState();updateAdventureNavButton();activateMediaTarget(activeV2View,{persist:false});await renderV2(activeV2View);}

    // Hedef Ayın ölçümü son masthead konumundan alınır. Eski açılış translate'i hedefi yukarı kaydırıp
    // uçuş sonunda sıçrama oluşturuyordu; hedef artık uçuş boyunca final koordinatında sabittir.
    v9Masthead.style.transform="translateY(0)";
    v9Masthead.style.opacity="0";
    v2Nav.style.opacity="0";v2Nav.style.transform="translateY(0)";
    v2Content.style.opacity="0";v2Content.style.transform="translateY(0)";
    v2Shell.style.opacity="1";v2Shell.style.pointerEvents="none";
    await alekNextPaint();

    const portalMoon=portal.querySelector(".adventure-portal-moon");
    const flight=mastheadMoon?await flyMoonBetween(portalMoon,mastheadMoon,{duration:1080,route:"logo",handoff:false}):null;

    // Hayalet Ay hedefte kalırken arayüz onun arkasında uyanır; gerçek logoya geçiş en son yapılır.
    portal.animate([{opacity:1,filter:"blur(0)"},{opacity:0,filter:"blur(10px)"}],{duration:560,easing:"ease-out",fill:"forwards"});
    v2Shell.getAnimations?.().forEach(animation=>animation.cancel());
    [v9Masthead,v2Nav,v2Content].forEach(node=>node.getAnimations?.().forEach(animation=>animation.cancel()));
    v2Shell.style.pointerEvents="auto";
    v2Shell.animate([{opacity:.01,filter:"blur(9px) brightness(.76)"},{opacity:1,filter:"blur(0) brightness(1)"}],{duration:940,easing:"cubic-bezier(.16,.8,.2,1)",fill:"both"});
    v9Masthead.animate([{opacity:0,filter:"blur(4px)"},{opacity:1,filter:"blur(0)"}],{duration:620,delay:80,easing:"cubic-bezier(.16,.8,.2,1)",fill:"both"});
    v2Nav.animate([{opacity:0,transform:"translateY(-8px)",filter:"blur(4px)"},{opacity:1,transform:"translateY(0)",filter:"blur(0)"}],{duration:680,delay:190,easing:"cubic-bezier(.16,.8,.2,1)",fill:"both"});
    v2Content.animate([{opacity:0,transform:"translateY(16px)",filter:"blur(5px)"},{opacity:1,transform:"translateY(0)",filter:"blur(0)"}],{duration:880,delay:280,easing:"cubic-bezier(.16,.8,.2,1)",fill:"both"});
    await new Promise(resolve=>setTimeout(resolve,390));
    if(flight)await flight.finish({duration:230});
    await new Promise(resolve=>setTimeout(resolve,210));
    portal.remove();
    if(adventureManagerShade===portal)adventureManagerShade=null;
    settleAdventureInterfaceVisibility();

    // R58 · Zaman mührü geçidin arkasında değil, geçit tamamen kalktıktan sonra
    // görünür ve etkileşimli arayüzde açılır. Tamamlanınca kullanıcı hangi ana
    // yüzeyden geldiyse aynı F1/F2/F3 yüzeyine temiz bir geçiş yapılır.
    const wasOpeningLocked=window.__ALEK_COSMIC_OPENING_LOCKED__===true;
    window.__ALEK_COSMIC_OPENING_LOCKED__=false;
    if(wasOpeningLocked){try{window.dispatchEvent(new CustomEvent("alek:opening-unlocked"));}catch(_){}}
    const configured=await ensureNonRealtimeStartTimeConfigured();
    const stillActive=String(record?.id||"")===String(activeAdventure?.id||"");
    __alekAdventurePortalReturnSurface="";
    if(configured&&stillActive)await window.__alekNavigatePrimarySurface?.(returnSurface);
    new Notice(`Adventure açıldı: ${record?.name||activeAdventure?.name||DEFAULT_ADVENTURE_NAME}`);
};
const renderAdventureManager=({fromOpening=false,fromMoon=false}={})=>{
    void __alekQuiescePrimarySurfacesForAdventure({saveWorld:true,rememberReturn:true});
    adventureManagerShade?.remove();mainPanel.style.opacity="1";mainPanel.style.pointerEvents="auto";
    const portal=document.createElement("section");portal.className="adventure-portal-shade";
    portal.innerHTML=`<div class="adventure-portal-stars"></div><div class="adventure-portal-panel"><div class="adventure-portal-crown"><button type="button" class="adventure-portal-moon" aria-label="Mavi Ay"><img src="${getDynamicUrl("Assets/Bluemoon.png")}" alt=""></button><small>AŁEK’RYŦHÆ</small><h1>Bir Macera Seç</h1><p>Bir maceraya dokun ve kozmik geçidi aç.</p></div><div class="adventure-portal-toolbar"></div><div class="adventure-portal-grid adventure-card-grid"></div></div>`;
    mainPanel.appendChild(portal);adventureManagerShade=portal;
    const toolbar=portal.querySelector(".adventure-portal-toolbar"),grid=portal.querySelector(".adventure-portal-grid"),portalMoon=portal.querySelector(".adventure-portal-moon");
    const add=document.createElement("button"),edit=document.createElement("button"),nameEdit=document.createElement("button"),leave=document.createElement("button");
    add.textContent="Yeni Macera";edit.textContent=adventureImageEditMode?"Kapak Düzenleme: Açık":"Kapak Düzenle";edit.classList.toggle("active",adventureImageEditMode);nameEdit.textContent="Adı Düzenle";leave.textContent="Macerayı Sil";leave.className="danger";toolbar.append(add,edit,nameEdit,leave);
    (adventureRegistry.adventures||[]).forEach((record,idx)=>{
        const card=document.createElement("button");card.className="adventure-card portal-adventure-card";card.dataset.adventureId=String(record.id);card.classList.toggle("active",record.id===activeAdventure?.id);card.classList.toggle("selected",record.id===adventureManagerSelectionId);
        const visual=document.createElement("span");visual.className="adventure-card-visual";let img=null;
        if(record.cover){img=document.createElement("img");img.src=getDynamicUrl(record.cover);img.alt=record.name;img.onerror=()=>{if(record.coverPolicy==="alekrythae-default"&&img.dataset.bundledPosterRetried!=="1"){img.dataset.bundledPosterRetried="1";img.src=getDynamicUrl("Assets/alekrythae_logo.png");return;}visual.textContent="◈";card.style.width="220px";card.style.minWidth="220px";card.style.maxWidth="220px";};visual.appendChild(img);}else if(record.coverPolicy==="alekrythae-default"){img=document.createElement("img");img.src=getDynamicUrl("Assets/alekrythae_logo.png");img.alt=record.name;img.onerror=()=>{visual.textContent="◈";};visual.appendChild(img);}else{visual.textContent="◈";card.style.width="220px";card.style.minWidth="220px";card.style.maxWidth="220px";}
        const label=document.createElement("span");label.className="adventure-card-title";label.textContent=record.name;card.append(visual,label);
        const modeBadge=document.createElement("small");modeBadge.className="adventure-mode-badge";modeBadge.textContent=gameModeLabel(record.mode);card.appendChild(modeBadge);
        if(record.id===activeAdventure?.id){const badge=document.createElement("small");badge.textContent="AKTİF";card.appendChild(badge);}
        setAdventureCardFrame(card,img);bindAdventureCardMotion(card);
        card.onclick=async()=>{adventureManagerSelectionId=record.id;if(adventureImageEditMode){replaceAdventureCover(record);return;}await revealAdventureInterface(portal,record,card);};grid.appendChild(card);
        card.animate([{opacity:0,transform:"translateY(24px) scale(.97)"},{opacity:1,transform:"translateY(0) scale(1)"}],{duration:560,delay:120+idx*70,easing:"cubic-bezier(.16,.8,.2,1)",fill:"both"});
    });
    if(!(adventureRegistry.adventures||[]).length){const empty=document.createElement("div");empty.className="adventure-empty-state";empty.innerHTML="<strong>Henüz macera yok</strong><small>Başlangıç Ałek’ryŧhæ macerası dâhil bütün oyunlar silinebilir. Yeniden başlamak için “Yeni Macera”ya basıp üç moddan birini seç.</small>";grid.appendChild(empty);edit.disabled=true;nameEdit.disabled=true;leave.disabled=true;}
    add.onclick=createAdventureRecord;edit.onclick=()=>{adventureImageEditMode=!adventureImageEditMode;renderAdventureManager();};nameEdit.onclick=()=>renameAdventureRecord(adventureRegistry.adventures.find(item=>item.id===adventureManagerSelectionId)||activeAdventure);leave.onclick=()=>deleteAdventureRecord(adventureRegistry.adventures.find(item=>item.id===adventureManagerSelectionId)||activeAdventure);
    v2Shell.style.pointerEvents="none";const hideUi=()=>{v2Shell.getAnimations?.().forEach(animation=>animation.cancel());[v9Masthead,v2Nav,v2Content].forEach(node=>node.getAnimations?.().forEach(animation=>animation.cancel()));v2Shell.style.opacity="0";};
    if(fromMoon&&mastheadMoon)requestAnimationFrame(async()=>{await flyMoonBetween(mastheadMoon,portalMoon,{duration:760});hideUi();});else hideUi();
    portal.animate([{opacity:0},{opacity:1}],{duration:fromOpening?620:420,easing:"ease-out",fill:"both"});return portal;
};
