const calendarMonthsForMode=()=>{
    const mode=normalizeGameRuntime().mode;
    return calendarMonthsForGameMode(mode);
};
const calendarMonthLabel=month=>calendarMonthsForMode()[Math.max(1,Number(month)||1)-1]||`Ay ${month}`;

const getMessagesForSelectedDay = () => {
    const d=ensureSelectedDate();
    return storyData.messages.filter(m=>Number(m.year)===Number(d.year)&&Number(m.month)===Number(d.month)&&Number(m.day)===Number(d.day)).sort((a,b)=>(Number(a.order)||0)-(Number(b.order)||0));
};

