const ALEK_MEGGY_MV_COUNT=ALEK_MEGGY_MV_LINES.length;
let __alekMeggyMvAudio=null;
let __alekMeggyMvPlaybackToken=0;

const rollUniformMeggyMvId=()=>{
    // WebView2 exposes crypto.getRandomValues. Rejection sampling avoids modulo bias,
    // therefore every integer from 1 through 240 has exactly the same selection chance.
    const cryptoApi=globalThis.crypto;
    if(cryptoApi&&typeof cryptoApi.getRandomValues==="function"){
        const range=0x100000000;
        const limit=Math.floor(range/ALEK_MEGGY_MV_COUNT)*ALEK_MEGGY_MV_COUNT;
        const cell=new Uint32Array(1);
        do{cryptoApi.getRandomValues(cell);}while(cell[0]>=limit);
        return (cell[0]%ALEK_MEGGY_MV_COUNT)+1;
    }
    return Math.floor(Math.random()*ALEK_MEGGY_MV_COUNT)+1;
};

const stopMeggyMvVoice=()=>{
    __alekMeggyMvPlaybackToken+=1;
    if(__alekMeggyMvAudio){
        try{__alekMeggyMvAudio.pause();__alekMeggyMvAudio.currentTime=0;}catch(_error){}
        __alekMeggyMvAudio=null;
    }
    document.querySelectorAll(".meggy-orb-shell.mv-speaking").forEach(node=>{node.classList.remove("mv-speaking");node.removeAttribute("data-mv-voice");});
};

const playMeggyMvVoice=mvId=>{
    stopMeggyMvVoice();
    const numericId=Math.max(1,Math.min(ALEK_MEGGY_MV_COUNT,Math.trunc(Number(mvId)||1)));
    const source=getDynamicUrl(`Assets/mv-voice/MV${numericId}.mp3`);
    const orb=v2Content?.querySelector?.(".meggy-orb")||document.querySelector(".meggy-orb");
    const shell=orb?.closest?.(".meggy-orb-shell")||null;
    if(!source){new Notice(`MV${numericId} ses dosyası bulunamadı.`);return;}
    const token=++__alekMeggyMvPlaybackToken;
    const audio=new Audio(source);
    __alekMeggyMvAudio=audio;
    audio.preload="auto";
    audio.volume=1;
    const speakingOn=()=>{
        if(token!==__alekMeggyMvPlaybackToken)return;
        shell?.classList.add("mv-speaking");
        shell?.setAttribute("data-mv-voice",String(numericId));
    };
    const speakingOff=()=>{
        if(token!==__alekMeggyMvPlaybackToken)return;
        shell?.classList.remove("mv-speaking");
        shell?.removeAttribute("data-mv-voice");
        if(__alekMeggyMvAudio===audio)__alekMeggyMvAudio=null;
    };
    audio.addEventListener("playing",speakingOn,{once:true});
    audio.addEventListener("ended",speakingOff,{once:true});
    audio.addEventListener("error",speakingOff,{once:true});
    speakingOn();
    const playResult=audio.play();
    if(playResult&&typeof playResult.catch==="function")playResult.catch(error=>{console.warn(`MV${numericId} oynatılamadı.`,error);speakingOff();});
};

const ALEK_TAVERN_LORE_SEPARATOR="---";
const getTavernLoreLanguage=()=>{
    const engine=window.__ALEK_LORE_LANGUAGE__;
    if(!engine||typeof engine.translate!=="function"||Number(engine.alphabetSize)!==240)throw new Error("240 harfli lore dil motoru hazır değil.");
    return engine;
};
const translateTavernLoreText=source=>{
    const input=String(source||"").trim();if(!input)return null;
    const engine=getTavernLoreLanguage(),result=engine.translate(input,"turkish");
    const glyph=String(result?.glyph||"").trim();if(!glyph)throw new Error("Lore dili dönüşümü boş sonuç verdi.");
    return{
        source:input,
        glyph,
        fingerprint:String(result?.fingerprint||""),
        engineVersion:String(engine.version||"6.0.1"),
        engineEdition:String(engine.edition||"POLYMORPH"),
        alphabetSize:Number(engine.alphabetSize)||240
    };
};
const ensureTavernLoreTranslation=message=>{
    const source=String(message?.text||"").trim();if(!source)return{translation:null,changed:false};
    const engine=getTavernLoreLanguage(),engineVersion=String(engine.version||"6.0.1");
    if(String(message.loreSourceText||"")===source&&String(message.loreText||"").trim()&&String(message.loreEngineVersion||"")===engineVersion){
        return{translation:{source,glyph:String(message.loreText),fingerprint:String(message.loreFingerprint||""),engineVersion,engineEdition:String(message.loreEngineEdition||engine.edition||"POLYMORPH"),alphabetSize:Number(message.loreAlphabetSize)||240},changed:false};
    }
    const translation=translateTavernLoreText(source);
    message.loreSourceText=translation.source;
    message.loreText=translation.glyph;
    message.loreFingerprint=translation.fingerprint;
    message.loreEngineVersion=translation.engineVersion;
    message.loreEngineEdition=translation.engineEdition;
    message.loreAlphabetSize=translation.alphabetSize;
    return{translation,changed:true};
};

const ALEK_TAVERN_IMAGE_PICKER_ID="alekrythae-tavern-image";
const ALEK_TAVERN_IMAGE_MAX_BYTES=16*1024*1024;
const ALEK_TAVERN_IMAGE_MAX_EDGE=1920;
let __alekTavernPendingImage=null;
let __alekTavernImagePickerBusy=false;

const readTavernImageFile=file=>new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(new Error("Görsel dosyası okunamadı."));
    reader.onload=()=>resolve(String(reader.result||""));
    reader.readAsDataURL(file);
});

const loadTavernImage=dataUrl=>new Promise((resolve,reject)=>{
    const image=new Image();
    image.onload=()=>resolve(image);
    image.onerror=()=>reject(new Error("Seçilen dosya geçerli bir görsel değil."));
    image.src=dataUrl;
});

const prepareTavernImage=async file=>{
    if(!file||!String(file.type||"").toLowerCase().startsWith("image/"))throw new Error("Yalnızca görsel dosyası seçebilirsin.");
    if((Number(file.size)||0)>ALEK_TAVERN_IMAGE_MAX_BYTES)throw new Error("Görsel 16 MB sınırını aşıyor.");
    const original=await readTavernImageFile(file),image=await loadTavernImage(original);
    const sourceWidth=Math.max(1,Number(image.naturalWidth)||1),sourceHeight=Math.max(1,Number(image.naturalHeight)||1);
    const scale=Math.min(1,ALEK_TAVERN_IMAGE_MAX_EDGE/Math.max(sourceWidth,sourceHeight));
    if(scale===1&&(Number(file.size)||0)<=3*1024*1024)return{dataUrl:original,width:sourceWidth,height:sourceHeight};
    const width=Math.max(1,Math.round(sourceWidth*scale)),height=Math.max(1,Math.round(sourceHeight*scale));
    const canvas=document.createElement("canvas");canvas.width=width;canvas.height=height;
    const context=canvas.getContext("2d",{alpha:true});if(!context)throw new Error("Görsel hazırlanamadı.");
    context.imageSmoothingEnabled=true;context.imageSmoothingQuality="high";context.drawImage(image,0,0,width,height);
    let dataUrl=canvas.toDataURL("image/webp",.9);
    if(!String(dataUrl).startsWith("data:image/webp"))dataUrl=canvas.toDataURL("image/png");
    return{dataUrl,width,height};
};

const chooseTavernImageWithInput=()=>new Promise(resolve=>{
    const input=document.createElement("input");input.type="file";input.accept="image/*";input.hidden=true;
    let settled=false;const finish=file=>{if(settled)return;settled=true;input.remove();resolve(file||null);};
    input.addEventListener("change",()=>finish(input.files?.[0]||null),{once:true});
    input.addEventListener("cancel",()=>finish(null),{once:true});
    document.body.appendChild(input);input.click();
});

const chooseTavernImageFile=async()=>{
    if(typeof window.showOpenFilePicker==="function"){
        try{
            // Chromium/WebView2, bu sabit kimlik için son seçilen klasörü kendisi hatırlar.
            const handles=await window.showOpenFilePicker({id:ALEK_TAVERN_IMAGE_PICKER_ID,multiple:false,excludeAcceptAllOption:false,types:[{description:"Görseller",accept:{"image/*":[".png",".jpg",".jpeg",".webp",".gif",".bmp",".avif"]}}]});
            return handles?.[0]?await handles[0].getFile():null;
        }catch(error){
            if(error?.name==="AbortError")return null;
            console.warn("Tavern kalıcı klasör seçicisi açılamadı; standart seçici kullanılıyor.",error);
        }
    }
    return chooseTavernImageWithInput();
};

const syncTavernPendingImageUi=()=>{
    const shell=v2Content?.querySelector?.(".tavern-composer-shell"),preview=shell?.querySelector?.(".tavern-image-preview"),image=preview?.querySelector?.("img"),composer=shell?.querySelector?.("#tavernTextInput");
    const hasImage=!!__alekTavernPendingImage?.dataUrl;
    shell?.classList.toggle("has-image",hasImage);
    if(preview)preview.hidden=!hasImage;
    if(image){if(hasImage)image.src=__alekTavernPendingImage.dataUrl;else image.removeAttribute("src");}
    composer?.dispatchEvent?.(new Event("input"));
};

const selectTavernImage=async()=>{
    if(__alekTavernImagePickerBusy)return false;
    __alekTavernImagePickerBusy=true;
    try{
        const file=await chooseTavernImageFile();if(!file)return false;
        __alekTavernPendingImage=await prepareTavernImage(file);
        syncTavernPendingImageUi();
        v2Content?.querySelector?.("#tavernTextInput")?.focus?.({preventScroll:true});
        new Notice("Görsel mesaja eklendi. Meggy’ye veya konuşmacıya basınca gönderilir.");
        return true;
    }catch(error){new Notice(error?.message||"Görsel eklenemedi.");return false;}
    finally{__alekTavernImagePickerBusy=false;}
};

const clearTavernPendingImage=()=>{__alekTavernPendingImage=null;syncTavernPendingImageUi();};

const openTavernImageViewer=(source,label="Tavern görseli")=>{
    if(!source)return;
    document.querySelector(".tavern-image-viewer")?.remove();
    const shade=document.createElement("div");shade.className="tavern-image-viewer";shade.tabIndex=-1;
    const frame=document.createElement("div");frame.className="tavern-image-viewer-frame";
    const close=document.createElement("button");close.type="button";close.className="tavern-image-viewer-close";close.textContent="×";close.title="Kapat";
    const image=document.createElement("img");image.src=source;image.alt=label;
    const caption=document.createElement("strong");caption.textContent=label;
    const dismiss=()=>{document.removeEventListener("keydown",onKey,true);shade.remove();};
    const onKey=event=>{if(String(event.key||"").toLowerCase()!=="escape")return;event.preventDefault();event.stopPropagation();event.stopImmediatePropagation?.();dismiss();};
    close.onclick=dismiss;shade.onclick=event=>{if(event.target===shade)dismiss();};
    frame.append(close,image,caption);shade.appendChild(frame);document.body.appendChild(shade);document.addEventListener("keydown",onKey,true);shade.focus({preventScroll:true});
};

const appendStoryMessage=async(speakerType,speaker)=>{
    const isMeggy=speakerType==="meggy";
    if(!isMeggy&&!characterCanJoinMeggyDialogue(speaker)){new Notice(`${fullNameOf(speaker)} Metaneti çöktüğü için konuşamaz. Metanet %50 veya üzerine çıkınca konuşma yeniden açılır.`);renderTavernStage();return;}
    const input=v2Content.querySelector("#tavernTextInput");if(!input)return;
    const typedText=input.value.trim(),pendingImage=__alekTavernPendingImage?.dataUrl?{...__alekTavernPendingImage}:null;
    if(!typedText&&!pendingImage){new Notice("Önce bir metin yaz veya G ile görsel ekle.");return;}
    const mvVoiceId=isMeggy&&typedText?rollUniformMeggyMvId():null;
    const mvLine=mvVoiceId?ALEK_MEGGY_MV_LINES[mvVoiceId-1]:"";
    const text=isMeggy&&typedText?`${typedText}\n\n${mvLine}`:typedText;
    let loreTranslation=null;
    if(text){
        try{loreTranslation=translateTavernLoreText(text);}
        catch(error){new Notice(error?.message||"Lore dili dönüşümü yapılamadı.");return;}
    }
    const d=ensureSelectedDate(),existing=getMessagesForSelectedDay();
    const durationSeconds=isMeggy?0:estimateSpeechSeconds(text),timeStartedAt=formatGameTime();
    {const activeDay=getCalendarDay(d.year,d.month,d.day,true);storyData.messages.push({id:makeId("message"),year:d.year,month:d.month,day:d.day,order:existing.length+1,encounterId:activeDay.activeEncounterId||null,speakerType,speakerId:isMeggy?"meggy":speaker.id,speakerName:isMeggy?"Meggy":fullNameOf(speaker),speakerTitle:isMeggy?"DM Master":(speaker.title||""),speechColor:isMeggy?"#7357a7":speaker.speechColor,text,loreSourceText:loreTranslation?.source||"",loreText:loreTranslation?.glyph||"",loreFingerprint:loreTranslation?.fingerprint||"",loreEngineVersion:loreTranslation?.engineVersion||"",loreEngineEdition:loreTranslation?.engineEdition||"",loreAlphabetSize:loreTranslation?.alphabetSize||0,imageData:pendingImage?.dataUrl||"",imageWidth:pendingImage?.width||0,imageHeight:pendingImage?.height||0,durationSeconds,timeStartedAt,locationId:activeDay.locationId||null,mvVoiceId,createdAt:new Date().toISOString()});}
    let timeResult=null;if(!isMeggy&&typedText)timeResult=advanceGameSeconds(durationSeconds,{persist:false,reason:`${fullNameOf(speaker)} konuştu (${text.length} karakter)`,resourceCharacterIds:[String(speaker?.id||"")]});
    storyData.messages.sort((a,b)=>Number(a.year)-Number(b.year)||Number(a.month)-Number(b.month)||Number(a.day)-Number(b.day)||Number(a.order)-Number(b.order));
    input.value="";__alekTavernPendingImage=null;
    if(isMeggy){
        // Render first, then start audio before the first await so WebView2 keeps this inside the click gesture.
        renderTavernStage();
        if(mvVoiceId)playMeggyMvVoice(mvVoiceId);
        await saveToDB(null);
        return;
    }
    await saveToDB(null);
    if(typedText)new Notice(`⏳ ${text.length} karakter · ${formatDurationSeconds(durationSeconds)} oyun zamanı geçti${timeResult?.recovery?` · Can +${timeResult.recovery.health}, Mana +${timeResult.recovery.mana}`:""}.`);
    else new Notice("Görsel konuşmacının balonuna gönderildi; oyun zamanı ilerlemedi.");
    renderTavernStage();
};

