document.addEventListener("keydown",event=>{
    if(event.defaultPrevented||event.repeat||event.ctrlKey||event.altKey||event.metaKey||event.code!=="KeyG")return;
    if(activeV2View!=="encounter"||!v2Content?.querySelector?.(".tavern-stage"))return;
    const target=event.target,editing=!!target?.closest?.("input,textarea,select,[contenteditable='true']");
    if(editing&&!(target?.id==="tavernTextInput"&&event.shiftKey))return;
    event.preventDefault();event.stopPropagation();event.stopImmediatePropagation?.();void selectTavernImage();
},true);

// -------------------------- Referans-dokulu yaşayan büyü nehri (v0.0.0-16) --------------------------
// Bu motor, GPT referansındaki gerçek bar dokularını paket içi kaynak olarak kullanır.
// Dokular tek kare gibi kaydırılmaz; iki bağımsız katman, sütun bazlı yumuşak deformasyon,
// ters yönlü akış, zamanla değişen kaynak ofseti ve geniş ışık kabarmalarıyla canlı tutulur.
// Sonuç elektrik teli değil; hacimli, sisli, katmanlı ve performans dostu büyü akışıdır.
let __alekEnergyFlowStyleInjected=false;
let __alekEnergyCanvasUid=0;
const __alekEnergyCanvases=new Set();
const __alekEnergyTextures=new Map();
let __alekEnergyTimer=0;
let __alekEnergyRaf=0;
let __alekEnergyLastFrame=0;
const __alekMountedResourceTracks=new Set();
let __alekResourceSyncRaf=0;

function alekResourceAppCanAnimate(){
    const governor=window.__ALEK_RESOURCE_GOVERNOR__;
    return !document.hidden&&(!governor||governor.isAppActive())&&!document.documentElement.classList.contains("alek-suspend");
}
function alekSyncAllResourceBars(){
    if(__alekResourceSyncRaf)return;
    __alekResourceSyncRaf=requestAnimationFrame(()=>{
        __alekResourceSyncRaf=0;
        for(const track of Array.from(__alekMountedResourceTracks)){
            if(!track?.isConnected){try{track?.__efCleanup?.();}catch(_){}__alekMountedResourceTracks.delete(track);continue;}
            try{track.__alekSyncResourceFlow?.();}catch(_){}
        }
    });
}
function alekResourceTrackIsVisible(track){
    if(!track?.isConnected||!track.getClientRects().length)return false;
    const rect=track.getBoundingClientRect();
    return rect.width>1&&rect.height>1&&rect.bottom>=0&&rect.right>=0&&rect.top<=innerHeight&&rect.left<=innerWidth;
}
function alekWakeResourceBars(scope=document,settleFrames=10){
    const root=scope instanceof Element||scope instanceof Document?scope:document;
    const rootIsAlive=()=>!(root instanceof Element)||root.isConnected;
    const wakeForeground=()=>{
        if(document.hidden||!rootIsAlive())return false;
        document.documentElement.classList.remove("alek-suspend");
        if(typeof window.__ALEK_FOREGROUND_ACTIVITY__==="function")window.__ALEK_FOREGROUND_ACTIVITY__();
        else window.dispatchEvent(new CustomEvent("alek:foreground-activity"));
        // Renderer ve kaynak yöneticisi ayrı modüller olduğu için ikisini de
        // görünür kart açılışında aynı karede uyandır. Böylece geç kalmış bir
        // WebView2 blur olayı barları ilk klavye girdisine kadar donduramaz.
        window.__ALEK_RENDERER__?.setAppActive?.(true);
        window.__ALEK_RESOURCE_GOVERNOR__?.wake?.(root instanceof Element?root:null);
        return true;
    };
    const syncTracks=()=>{
        let sawTracked=false,sawVisible=false;
        for(const track of Array.from(__alekMountedResourceTracks)){
            if(!track?.isConnected)continue;
            if(root!==document&&root!==track&&!root.contains(track))continue;
            sawTracked=true;
            const visible=alekResourceTrackIsVisible(track);
            if(visible){
                sawVisible=true;
                delete track.dataset.alekRuntimeOffscreen;
                track.querySelectorAll?.(".energy-flow,[data-alek-runtime-offscreen]").forEach(node=>delete node.dataset.alekRuntimeOffscreen);
            }
            track.__alekSyncResourceFlow?.();
            track.querySelectorAll?.(".energy-flow-canvas").forEach(canvas=>canvas.__alekResourceController?.prime?.());
        }
        return {sawTracked,sawVisible};
    };
    wakeForeground();
    // Kart paneli sağdan gelirken ölçüler birkaç turda oturuyor. Tek bir rAF
    // yerine kısa, sonlu yeniden uyandırma nöbetleri kullanılır; kullanıcıdan
    // klavye veya ikinci tık beklenmez.
    [0,50,150,360,720].forEach(delay=>window.setTimeout(()=>{
        if(!rootIsAlive()||document.hidden)return;
        wakeForeground();
        syncTracks();
    },delay));
    // Eski sürüm görünür kart açılışında EN AZ 180 kare boyunca bütün kaynak
    // raylarını tekrar ölçüyordu. Bu, WebView2 ana thread'ini saniyelerce meşgul
    // ediyordu. Gecikmeli uyandırmalar zaten mevcut; yalnız birkaç yerleşme karesi yeterli.
    let remaining=Math.max(4,Math.min(12,Math.round(Number(settleFrames)||6))),visibleStreak=0;
    const settle=()=>{
        if(!rootIsAlive()||document.hidden)return;
        if(!alekResourceAppCanAnimate())wakeForeground();
        const {sawTracked,sawVisible}=syncTracks();
        if(!sawTracked){
            if(--remaining>0)requestAnimationFrame(settle);
            return;
        }
        visibleStreak=sawVisible?visibleStreak+1:0;
        remaining--;
        if(remaining>0&&visibleStreak<3)requestAnimationFrame(settle);
    };
    requestAnimationFrame(settle);
}
function alekEnergyFlowGlobalGuard(){
    if(window.__alekEfGuard)return;window.__alekEfGuard=true;
    // Resource tracks use native-renderer's shared clock. The old Canvas
    // scheduler was retired; wake/suspend only resynchronizes mounted tracks.
    const upd=()=>alekSyncAllResourceBars();
    window.addEventListener("alek:resource-state",upd,{passive:true});
    window.addEventListener("alek:resource-wake",upd,{passive:true});
    document.addEventListener("visibilitychange",upd,{passive:true});
    upd();
}

