function alekLoadResourceBarIndexSync(){
    try{
        const xhr=new XMLHttpRequest();
        xhr.open("GET",`${getDynamicUrl("Assets/resource-bars/resource-bar-index.json")}?alek_revision=129`,false);
        xhr.send(null);
        if(xhr.status>=200&&xhr.status<300){
            const parsed=JSON.parse(xhr.responseText||"{}");
            const raw=parsed.resources||parsed.Resources;
            if(raw&&typeof raw==="object")return raw;
        }
    }catch(error){console.warn("Kaynak bari enerji indeksi okunamadi; guvenli katmanlar kullaniliyor.",error)}
    return __alekResourceBarFallback;
}
function alekParseResourceBarFile(kind,fileName){
    const spec=__alekResourceBarFolders[kind],name=String(fileName||"").trim();
    if(!spec||!name)return null;
    const escapedPrefix=spec.prefix.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
    const match=name.match(new RegExp(`^${escapedPrefix}-(\\d+(?:[.,]\\d+)?)-(\\d+(?:[.,]\\d+)?)(?:-(.+))?\\.png$`,"i"));
    if(!match)return null;
    const opacityPercent=Math.max(0,Math.min(100,Number(match[1].replace(",","."))));
    const durationSeconds=Math.max(.1,Number(match[2].replace(",","."))||0);
    if(!Number.isFinite(opacityPercent)||!Number.isFinite(durationSeconds))return null;
    return{
        fileName:name,
        relativePath:`${spec.folder}/${name}`,
        opacityPercent,
        opacity:opacityPercent/100,
        durationSeconds,
        variant:String(match[3]||"")
    };
}
async function alekDiscoverResourceBarIndex(indexed){
    const merged={...(indexed&&typeof indexed==="object"?indexed:__alekResourceBarFallback)};
    if(!_hasBridge||typeof window.__alekList!=="function")return merged;
    await Promise.all(Object.entries(__alekResourceBarFolders).map(async([kind,spec])=>{
        try{
            const folder=`Assets/resource-bars/${spec.folder}`;
            const listed=await window.__alekList(folder);
            if(!listed?.ok)return;
            const discovered=(listed.items||[])
                .filter(item=>item?.type==="file")
                .map(item=>alekParseResourceBarFile(kind,item.name))
                .filter(Boolean)
                .sort((a,b)=>b.opacity-a.opacity||b.durationSeconds-a.durationSeconds||a.fileName.localeCompare(b.fileName,"tr",{numeric:true,sensitivity:"base"}));
            // Klasörde geçerli en az bir PNG varsa o klasör tek gerçektir. Sabit JSON
            // yalnız boş/erişilemeyen klasörler için geriye dönük güvenlik ağıdır.
            if(discovered.length)merged[kind]=discovered;
        }catch(error){console.warn(`Kaynak bari klasoru okunamadi: ${spec.folder}`,error)}
    }));
    return merged;
}
const __alekResourceBarIndex=await alekDiscoverResourceBarIndex(alekLoadResourceBarIndexSync());
