        opacity:Math.max(0,Math.min(1,Number(layer.opacity??layer.Opacity??((Number(layer.opacityPercent??layer.OpacityPercent)||100)/100)))),
        durationSeconds:Math.max(.1,Number(layer.durationSeconds??layer.DurationSeconds)||12),
        index
