    return `<span class="energy-flow ef-${normalized}" data-kind="${normalized}" data-orientation="${orientation}" aria-hidden="true"><canvas class="energy-flow-canvas" data-kind="${normalized}" data-orientation="${orientation}"></canvas></span>`;
