        const layers=alekResourceBarLayers(kind).map(layer=>({url:getDynamicUrl(`Assets/resource-bars/${layer.relativePath}`),opacity:layer.opacity,duration:layer.durationSeconds}));
        const controller=window.__ALEK_RENDERER__?.mountResourceFlow(canvas,{layers,orientation:flow.dataset.orientation||canvas.dataset.orientation||"horizontal"});
