const JOURNEY_TAXONOMY_LABEL_BY_TYPE=Object.freeze({character:"Varlık",being:"Varlık",species:"Tür",people:"Halk",group:"Grup",dynasty:"Hanedan",society:"Cemiyet",sovereignty:"Hükümranlık",civilization:"Medeniyet",settlement:"Yerleşke",land:"Diyar",plane:"Âlem",location:"Mekân",structure:"Yapı",geography:"Coğrafya",habitat:"Yaşam Alanı",celestial:"Göksel Oluşum",realm:"Uçan Ada",item:"Öğe",mount:"Binek / Taşıt",mechanism:"Düzenek",facility:"Tesis",resource:"Kaynak",network:"Ağ"});
