const taxonomyNodePolarPosition=(sectorId,index)=>{
    const angle=(TAXONOMY_NODE_START_ANGLES[sectorId]??7.5)+(index*15);
    const radians=(angle-90)*(Math.PI/180);
    return Object.freeze({
        x:50+(Math.cos(radians)*TAXONOMY_NODE_RADIUS_PERCENT),
        y:50+(Math.sin(radians)*TAXONOMY_NODE_RADIUS_PERCENT),
        angle
    });
};
