const taxonomyNodePercentStyle=pos=>`left:${pos.x}%;top:${pos.y}%;`;
const taxonomyAssetUrl=file=>getDynamicUrl(`Assets/taxonomy/${file}`);
const TAXONOMY_ENERGY_TAGS=Object.freeze(['P','S','M','T']);
const TAXONOMY_ENERGY_ORDER=Object.freeze({P:0,S:1,M:2,T:3});
const taxonomySortEnergyLayers=(a,b)=>{
    const tagDiff=(TAXONOMY_ENERGY_ORDER[a.colorTag]??99)-(TAXONOMY_ENERGY_ORDER[b.colorTag]??99);
    if(tagDiff!==0)return tagDiff;
    if(b.visibility!==a.visibility)return b.visibility-a.visibility;
    if(b.durationSeconds!==a.durationSeconds)return b.durationSeconds-a.durationSeconds;
    const variantDiff=String(a.variant||'').localeCompare(String(b.variant||''),'tr',{numeric:true,sensitivity:'base'});
    return variantDiff||String(a.fileName||'').localeCompare(String(b.fileName||''),'tr',{numeric:true,sensitivity:'base'});
};
const normalizeTaxonomyEnergyLayer=layer=>{
    const fileName=String(layer?.fileName??layer?.FileName??'').trim();
    const colorTag=String(layer?.colorTag??layer?.ColorTag??'').toUpperCase();
    if(!fileName||!Object.prototype.hasOwnProperty.call(TAXONOMY_ENERGY_ORDER,colorTag))return null;
    const visibility=Math.max(0,Math.min(100,Number(layer?.visibility??layer?.Visibility??0)));
    const explicitOpacity=Number(layer?.opacity??layer?.Opacity);
    return{
        fileName,
        colorTag,
        visibility,
        opacity:Number.isFinite(explicitOpacity)?Math.max(0,Math.min(1,explicitOpacity)):visibility/100,
        durationSeconds:Math.max(.05,Number(layer?.durationSeconds??layer?.DurationSeconds)||0),
        variant:String(layer?.variant??layer?.Variant??'')
    };
};
const loadTaxonomyEnergyIndexSync=()=>{
    const fallback={frameFile:'taxonomy_frame.png',maskFile:'taxonomy_energy_channel.png',layers:[]};
    try{
        const xhr=new XMLHttpRequest();
        xhr.open('GET',`${taxonomyAssetUrl('taxonomy-energy-index.json')}?alek_revision=129`,false);
        xhr.send(null);
        if(xhr.status>=200&&xhr.status<300){
            const parsed=JSON.parse(xhr.responseText||'{}'),rawLayers=parsed.layers??parsed.Layers;
            const layers=Array.isArray(rawLayers)?rawLayers.map(normalizeTaxonomyEnergyLayer).filter(Boolean).sort(taxonomySortEnergyLayers):fallback.layers;
            return{frameFile:parsed.frameFile??parsed.FrameFile??fallback.frameFile,maskFile:parsed.maskFile??parsed.MaskFile??fallback.maskFile,layers};
        }
    }catch(err){console.warn('taxonomy-energy-index.json okunamadi, fallback kullaniliyor.',err)}
    return fallback;
};
const parseTaxonomyEnergyFile=fileName=>{
    const name=String(fileName||'').trim();
    const match=name.match(/^([PSMT])-(\d+(?:[.,]\d+)?)-(\d+(?:[.,]\d+)?)(?:-(.+))?\.png$/i);
    if(!match)return null;
    const visibility=Math.max(0,Math.min(100,Number(match[2].replace(',','.'))));
    const durationSeconds=Math.max(.05,Number(match[3].replace(',','.'))||0);
    if(!Number.isFinite(visibility)||!Number.isFinite(durationSeconds))return null;
    return{
        fileName:name,
        colorTag:match[1].toUpperCase(),
        visibility,
        opacity:visibility/100,
        durationSeconds,
        variant:String(match[4]||'')
    };
};
const discoverTaxonomyEnergyIndex=async indexed=>{
    const fallback=indexed&&typeof indexed==='object'?indexed:loadTaxonomyEnergyIndexSync();
    if(!_hasBridge||typeof window.__alekList!=='function')return fallback;
    try{
        const listed=await window.__alekList('Assets/taxonomy');
        if(!listed?.ok)return fallback;
        const layers=(listed.items||[])
            .filter(item=>item?.type==='file')
            .map(item=>parseTaxonomyEnergyFile(item.name))
            .filter(Boolean)
            .sort(taxonomySortEnergyLayers);
        // Dairenin P/S/M/T katmanları da klasörün kendisinden okunur. JSON yalnız
        // klasöre erişilemediğinde veya geçerli katman bulunmadığında güvenlik ağıdır.
        return layers.length?{...fallback,layers}:fallback;
    }catch(err){console.warn('Taksonomi enerji klasoru okunamadi; indeks kullaniliyor.',err);return fallback}
};
const TAXONOMY_ENERGY_INDEX=await discoverTaxonomyEnergyIndex(loadTaxonomyEnergyIndexSync());
const taxonomyMoonMarkup=()=>``;
const taxonomyLayerStackMarkup=()=>`\n<div class="taxonomy-layer-stack" aria-hidden="true">\n  <div class="taxonomy-energy-stage"><canvas class="taxonomy-energy-canvas"></canvas></div>\n  <img class="taxonomy-final-frame" src="${taxonomyAssetUrl(TAXONOMY_ENERGY_INDEX.frameFile)}" alt="" onerror="this.remove()">\n</div>`;
const mountTaxonomyEnergyCanvas=wheel=>{
    const canvas=wheel?.querySelector?.('.taxonomy-energy-canvas');if(!canvas)return null;
    const tagOffsets={P:.07,S:.29,M:.53,T:.79};
    const layers=TAXONOMY_ENERGY_TAGS.flatMap(tag=>TAXONOMY_ENERGY_INDEX.layers.filter(layer=>layer.colorTag===tag).map((layer,index)=>({
        url:taxonomyAssetUrl(layer.fileName),tag,
        opacity:Number.isFinite(Number(layer.opacity))?Math.max(0,Math.min(1,Number(layer.opacity))):Math.max(0,Math.min(1,(Number(layer.visibility)||100)/100)),
        duration:Math.max(.05,Number(layer.durationSeconds)||12),
        startTurn:(tagOffsets[tag]+(index*.173)+((index%3)*.041))%1
    })));
    return window.__ALEK_RENDERER__?.mountTaxonomy(canvas,{layers})||null;
};
