const unifiedIdentityEditorMarkup=entity=>{const locked=!!entity.isLocked;return `<div class="character-identity-editor" data-identity-locked="${locked}"><div class="character-name-seal-row"><button type="button" id="rndName" class="identity-rune-button" ${locked?'disabled':''}>✦</button><input type="text" id="i_name" value="${escapeHtmlValue(entity.name||"")}" ${locked?'disabled':''} placeholder="Ad"><span class="identity-diamond">⟡</span><button type="button" id="rndSur" class="identity-rune-button surname-rune" ${locked?'disabled':''}>◇</button><input type="text" id="i_sur" value="${escapeHtmlValue(entity.surname||"")}" ${locked?'disabled':''} placeholder="Soyad / Bağ"></div><label class="character-title-seal"><span>♜</span><input type="text" id="i_title" value="${escapeHtmlValue(entity.title||"")}" ${locked?'disabled':''} placeholder="Ünvan"></label></div>`;};
