    normalizeNarrativeRelationKeys(record.entity.relationKeys).forEach(key=>{const linked=entityFromSpatialKey(key);if(linked&&linked.key!==record.key)byKey.set(linked.key,linked);});
    narrativeReverseOriginRecords(record).forEach(linked=>byKey.set(linked.key,linked));
