    // yalnız açık kartın gerçek konteyner anahtarından başlar. Böylece kökteki
    // bağımsız kartlar karakterin içindeymiş gibi görünmez. Doğrudan çocuklar
    // listelenir; onların alt mevcudatları ancak kendi dalları açılınca görünür.
    const containedChildren=parentKey=>mevcudatSortedChildren(String(parentKey||record.key));
    const refresh=()=>{
        const globalSnapshot=captureAlekStableScroll();
        const scroller=host.closest(".character-tab-scroll,.character-detail-content");
        const keepTop=scroller?.scrollTop||0;
        const oldViewport=host.querySelector(".mevcudat-tree-viewport");
        const keepLeft=oldViewport?.scrollLeft||0;
        host.replaceChildren();renderMevcudatPanel(record,host);
        requestAnimationFrame(()=>{if(scroller)scroller.scrollTop=keepTop;const nextViewport=host.querySelector(".mevcudat-tree-viewport");if(nextViewport)nextViewport.scrollLeft=keepLeft;restoreAlekStableScroll(globalSnapshot);});
    };
    const shell=document.createElement("section");shell.className="mevcudat-browser mevcudat-tree-browser";shell.style.setProperty("--mevcudat-self-accent",cardIdentityAccentOf(record.type));
    const parentKey=entityContainerKey(record.entity,record.type);
    const parentRecord=parentKey!=="root"?entityFromSpatialKey(parentKey):null;
    const parentTravelRecord=!parentRecord&&parentKey!=="root"?mevcudatTravelGroupRecords().find(item=>String(item.key)===String(parentKey)):null;
    const upperOfParentKey=parentRecord?entityContainerKey(parentRecord.entity,parentRecord.type):(parentTravelRecord?mevcudatRecordParentKey(parentTravelRecord):"root");
    const targetRow=document.createElement("div");targetRow.className="mevcudat-drop-targets";
    const parentGlyph=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 10.5 12 4l7 6.5M12 4v11M7 20h10"/></svg>`;
    const currentGlyph=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h16v11H4zM8 4h8v4M12 10v6m0 0-3-3m3 3 3-3"/></svg>`;
    const liftGlyph=`<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="5" y="7" width="10" height="12" rx="2"/><path d="M10 12 17 5m0 0h-5m5 0v5"/></svg>`;

    const parentTarget=document.createElement("button");parentTarget.type="button";parentTarget.className="mevcudat-parent-target";parentTarget.innerHTML=`<span class="mevcudat-parent-wave mevcudat-action-sigil" aria-hidden="true">${parentGlyph}</span><span><small>ÜST KONTEYNER</small><strong>Üst Kümeye Taşı</strong><em>${escapeHtmlValue(containerLabel(parentKey))}</em></span><kbd>W</kbd>`;
    parentTarget.title=`W + tık: seçili kartları doğrudan ${containerLabel(parentKey)} içine taşı`;
    parentTarget.onclick=async event=>{
        event.preventDefault();event.stopPropagation();
        if(!isWPointerIntent()){new Notice("Üst kümeye taşımak için W tuşunu basılı tutup bu hedefe tıkla.");return;}
        consumeWPointerIntent();
        const pending=[...journeySelected].filter(key=>key!==record.key&&key!==parentKey);
        if(!pending.length){new Notice("Önce Q + tık ile üst kümeye taşınacak kartları seç.");return;}
        const moved=await moveJourneySelectionTo(parentKey,{render:false,clearSelection:true,notice:true,sectionId:null,keys:pending});
        if(moved)refresh();
    };

    const currentTarget=document.createElement("button");currentTarget.type="button";currentTarget.className="mevcudat-current-target";
    currentTarget.innerHTML=`<span class="mevcudat-current-sigil mevcudat-action-sigil" aria-hidden="true">${currentGlyph}</span><span><small>MEVCUT KONTEYNER</small><strong>Bu Mevcudata Bırak</strong><em>${escapeHtmlValue(fullNameOf(record.entity))}</em></span><kbd>W</kbd>`;
    currentTarget.title="W + tık: seçili kartları açık kartın doğrudan içine bırak";
    currentTarget.onclick=async event=>{
        event.preventDefault();event.stopPropagation();
        if(!isWPointerIntent()){new Notice("Bu karta bırakmak için W tuşunu basılı tutup bu hedefe tıkla.");return;}
        consumeWPointerIntent();
        const pending=[...journeySelected].filter(key=>key!==record.key);
        if(!pending.length){new Notice("Önce Q + tık ile bu karta bırakılacak kartları seç.");return;}
        const moved=await moveJourneySelectionTo(record.key,{render:false,clearSelection:true,notice:true,sectionId:null,keys:pending});
        if(moved)refresh();
    };
    const currentCardUpTarget=document.createElement("button");currentCardUpTarget.type="button";currentCardUpTarget.className="mevcudat-current-card-up-target";
    currentCardUpTarget.disabled=parentKey==="root";
    currentCardUpTarget.innerHTML=`<span class="mevcudat-current-card-up-sigil mevcudat-action-sigil" aria-hidden="true">${liftGlyph}</span><span><small>MEVCUT MEVCUDAT</small><strong>Mevcudatı Bir Üst Kümeye Taşı</strong><em>${parentKey==="root"?"Zaten en üst düzeyde":escapeHtmlValue(containerLabel(upperOfParentKey))}</em></span><kbd>W</kbd>`;
    currentCardUpTarget.title=parentKey==="root"?"Bu kart zaten Ana Dünya düzeyinde":"W + tık: açık kartın kendisini bulunduğu konteynerden bir üst konteynere taşı";
    currentCardUpTarget.onclick=async event=>{
        event.preventDefault();event.stopPropagation();
        if(currentCardUpTarget.disabled)return;
        if(!isWPointerIntent()){new Notice("Açık kartı bir üst kümeye taşımak için W tuşunu basılı tutup altın hedefe tıkla.");return;}
        consumeWPointerIntent();
        const scrollSnapshot=captureAlekStableScroll();
        const moved=await moveJourneySelectionTo(upperOfParentKey,{render:false,clearSelection:false,notice:false,sectionId:null,keys:[record.key]});
        if(!moved){new Notice("Açık kart bir üst kümeye taşınamadı.");restoreAlekStableScroll(scrollSnapshot);return;}
        new Notice(`↟ ${fullNameOf(record.entity)} bir üst kümeye taşındı.`);
        openUnifiedEntityDetail(record,{pushCurrent:false,initialTab:"members"});
        restoreAlekStableScroll(scrollSnapshot);
    };
    targetRow.append(parentTarget,currentTarget,currentCardUpTarget);shell.appendChild(targetRow);

    const treeViewport=document.createElement("div");treeViewport.className="mevcudat-tree-viewport";
    const tree=document.createElement("div");tree.className="mevcudat-tree mevcudat-file-tree";
    let maxVisibleDepth=0;

