    host.querySelectorAll("input[data-institution-pool]").forEach(input=>input.onkeydown=async event=>{event.stopPropagation();if(event.key!=="Enter")return;event.preventDefault();const key=input.dataset.institutionPool,action=input.dataset.action,pool=entity[key],value=Math.max(action==="maximum"?1:0,Math.round(Number(input.value)||0));if(action!=="maximum")input.value="";if(action==="maximum"){pool.maximum=value;pool.current=Math.min(pool.current,pool.maximum);}else pool.current=Math.max(0,Math.min(pool.maximum,pool.current+(action==="increase"?value:-value)));sync(key);await saveToDB(null);});
