const makeLeafAccordion=(record,tab,currentKey)=>{
    const openSet=containerOpenLeafSet(currentKey,tab),open=openSet.has(record.key),box=document.createElement("section");box.className=`container-leaf-accordion ${record.type}`;box.classList.toggle("open",open);
    const header=document.createElement("button");header.type="button";header.className="container-leaf-header";header.innerHTML=`<span class="container-leaf-chevron">${open?"▾":"▸"}</span><span class="container-leaf-kind">${escapeHtmlValue(entityTypeDisplayLabel(record.type))}</span><span class="container-leaf-name">${escapeHtmlValue(fullNameOf(record.entity))}</span><span class="container-leaf-subtitle">${escapeHtmlValue(entitySubtitleForContainer(record))}</span>`;
    const body=document.createElement("div");body.className="container-leaf-body";body.hidden=!open;const draw=()=>{if(!body.hidden&&!body.dataset.rendered){body.dataset.rendered="1";renderContainerEntityTabContent(record,tab,body);}};
    header.onclick=()=>{const next=!box.classList.contains("open");box.classList.toggle("open",next);body.hidden=!next;header.querySelector(".container-leaf-chevron").textContent=next?"▾":"▸";if(next)openSet.add(record.key);else{openSet.delete(record.key);if(tab==="sheet"){destroyCharacterVitals(body);destroyArcanaReserve(body);destroyStamina(body);destroyMetanet(body);body.replaceChildren();delete body.dataset.rendered;}}draw();};box.append(header,body);draw();return box;
};
const renderJourneyContainerDetail=(record)=>{
    const entity=ensureFunctionalEntityFields(record.entity,record.type);
    const shell=document.createElement("section");shell.className=`journey-container-detail journey-container-character-view behavior-${entityBehaviorFamily(record.type)}`;
    const currentKey=record.key,tabDefs=containerTabDefsFor(record);let activeTab=__alekContainerActiveTabs.get(currentKey)||"sheet";if(!tabDefs.some(def=>def.id===activeTab))activeTab="sheet";
    const children=directJourneyEntityRecords(currentKey).sort((a,b)=>fullNameOf(a.entity).localeCompare(fullNameOf(b.entity),"tr"));
    const containers=children.filter(child=>isContainerEntityType(child.type)),leaves=children.filter(child=>isLeafEntityType(child.type));
    const family=entityBehaviorFamily(record.type);

    const left=document.createElement("aside");left.className="journey-container-portrait-column";
    left.innerHTML=`<div class="journey-container-portrait-shell"><div class="journey-container-portrait-stage">${containerPortraitMarkup(record)}<span class="character-detail-avatar-vignette" aria-hidden="true"></span></div><div class="journey-container-portrait-meta"><small>${escapeHtmlValue(entityTypeDisplayLabel(record.type))}</small><strong>${escapeHtmlValue(fullNameOf(entity))}</strong><span>${escapeHtmlValue(entitySubtitleForContainer(record))}</span></div></div>`;

    const right=document.createElement("section");right.className="journey-container-main-card";
    const parentKey=entityContainerKey(entity,record.type);
    const header=document.createElement("div");header.className="journey-container-main-head";
    header.innerHTML=`<div class="journey-container-main-copy"><small>${family==="collective"?"TOPLU KONTEYNER":family==="mount"?"BİNEK / TAŞIT":family==="institution"?"KURUMSAL MEVCUDAT":"VARLIK"}</small><strong>${escapeHtmlValue(fullNameOf(entity))}</strong><span>${escapeHtmlValue(entitySubtitleForContainer(record))}</span></div><div class="journey-container-main-actions"><button type="button" class="container-back-button">${parentKey==="root"?"← Ana Dünyaya Dön":"← Üst Konteynere Dön"}</button><button type="button" class="journey-container-edit-button">Düzenle</button></div>`;
    header.querySelector(".container-back-button").onclick=()=>enterJourneyContainer(parentKey,{preserveSelection:true});
    header.querySelector(".journey-container-edit-button").onclick=()=>openEntityEditorForRecord(record);

    const tabs=document.createElement("nav");tabs.className="journey-container-tabs journey-container-tabs-card";tabs.style.setProperty("--tab-count",String(tabDefs.length));
    tabDefs.forEach(def=>{const button=document.createElement("button");button.type="button";button.classList.toggle("active",def.id===activeTab);button.innerHTML=`<span>${def.icon}</span><strong>${escapeHtmlValue(def.label)}</strong>`;button.onclick=()=>{__alekContainerActiveTabs.set(currentKey,def.id);renderJourney();};tabs.appendChild(button);});

    const scroll=document.createElement("div");scroll.className="journey-container-sheet-scroll";
    const selfSection=document.createElement("section");selfSection.className="journey-container-self-panel";
    const selfBody=document.createElement("div");selfBody.className="journey-container-self-body";renderContainerEntityTabContent(record,activeTab,selfBody,{self:true});selfSection.appendChild(selfBody);scroll.appendChild(selfSection);

    if(family==="mount"&&activeTab!=="members")scroll.insertAdjacentHTML("afterbegin",collectiveSummaryMarkup(record));
    else if(family==="collective"&&activeTab!=="sheet")scroll.insertAdjacentHTML("afterbegin",collectiveSummaryMarkup(record));
    else if(family==="institution"&&activeTab!=="sheet")scroll.insertAdjacentHTML("afterbegin",institutionSummaryMarkup(record));

    if(activeTab==="members"){
        renderMevcudatPanel(record,scroll);
    }else if(family==="collective"){
        const navSection=document.createElement("section");navSection.className="journey-container-roster-panel";navSection.innerHTML=`<div class="container-section-heading"><div><small>İÇ KONTEYNERLER</small><strong>${containers.length} mevcudat</strong></div><span>Basınca doğrudan ilgili konteynere gidilir.</span></div>`;
        const navGrid=document.createElement("div");navGrid.className="container-navigation-grid";containers.forEach(child=>navGrid.appendChild(makeContainerNavigationCard(child,currentKey)));if(!containers.length)navGrid.innerHTML='<div class="container-empty-note">İçte başka konteyner yok.</div>';navSection.appendChild(navGrid);scroll.appendChild(navSection);
        const leafSection=document.createElement("section");leafSection.className="journey-container-roster-panel";leafSection.innerHTML=`<div class="container-section-heading"><div><small>${escapeHtmlValue(tabDefs.find(item=>item.id===activeTab)?.label||"İÇERİK")}</small><strong>${leaves.length} bireysel mevcudat</strong></div><span>Karakter ve N kartları bu sekmede açılır-kapanır görünür.</span></div>`;
        const leafList=document.createElement("div");leafList.className="container-leaf-list";leaves.forEach(child=>leafList.appendChild(makeLeafAccordion(child,activeTab,currentKey)));if(!leaves.length)leafList.innerHTML='<div class="container-empty-note">Doğrudan Karakter veya N Varlığı bulunmuyor.</div>';leafSection.appendChild(leafList);scroll.appendChild(leafSection);
    }

    right.append(header,tabs,scroll);
    shell.innerHTML=containerResourceRailMarkup(record);
    shell.prepend(left);shell.appendChild(right);
    return shell;
};


const alekLaunchVisualShift=(waitingRect,stackRect,contentRect,panelRect,scaleX=1,scaleY=1,viewportWidth=innerWidth,viewportHeight=innerHeight)=>{
    const left=Math.max(0,Number(contentRect?.left)||0,Number(panelRect?.left)||0);
    const top=Math.max(0,Number(contentRect?.top)||0,Number(panelRect?.top)||0);
    const right=Math.min(Math.max(left,Number(viewportWidth)||0),Number(contentRect?.right)||left,Number(panelRect?.right)||left);
    const bottom=Math.min(Math.max(top,Number(viewportHeight)||0),Number(contentRect?.bottom)||top,Number(panelRect?.bottom)||top);
    const targetX=(left+right)/2,targetY=(top+bottom)/2;
    const stackX=((Number(stackRect?.left)||0)+(Number(stackRect?.right)||0))/2;
    const stackY=((Number(stackRect?.top)||0)+(Number(stackRect?.bottom)||0))/2;
    return{x:(targetX-stackX)/Math.max(.01,Number(scaleX)||1),y:(targetY-stackY)/Math.max(.01,Number(scaleY)||1)};
};
const primeJoALaunchLayout=waiting=>{
    const stack=waiting?.querySelector?.('.joa-launch-center-stack');if(!stack)return null;
    const force=(node,properties)=>Object.entries(properties).forEach(([name,value])=>node.style.setProperty(name,value,'important'));
    // Geç yüklenen runtime stillerini beklemeden ilk karede ikinci referanstaki
    // dikey kompozisyonu kur: Ay, iki satırlı başlık ve alt yazı tek merkez gruptur.
    force(waiting,{
        position:'absolute',inset:'0',width:'100%',height:'100%',margin:'0',padding:'24px',
        'box-sizing':'border-box',display:'grid','place-content':'center','place-items':'center',
        'text-align':'center',transform:'none',background:'#03070b'
    });
    force(stack,{
        position:'relative',width:'max-content','max-width':'min(760px,82vw)',display:'grid',
        'grid-template-columns':'max-content','grid-auto-flow':'row','grid-auto-rows':'max-content',
        'place-content':'center','place-items':'center',gap:'10px',margin:'0','text-align':'center',
        isolation:'isolate','will-change':'transform'
    });
    Array.from(stack.children).forEach(node=>force(node,{
        'justify-self':'center','align-self':'center','margin-left':'auto','margin-right':'auto','text-align':'center'
    }));
    const image=stack.querySelector('img');if(image)force(image,{display:'block'});
    const title=stack.querySelector('strong');if(title)force(title,{display:'block','white-space':'normal'});
    const subtitle=stack.querySelector('small');if(subtitle)force(subtitle,{display:'block','white-space':'nowrap'});
    return stack;
};
const alignJoALaunchPlaceholder=waiting=>{
    const stack=primeJoALaunchLayout(waiting);if(!stack)return;
    const sync=()=>{
        if(!waiting.isConnected||!stack.isConnected)return;
        // Önceki ölçümün transformu getBoundingClientRect'e katılırsa hesap sağ-sol
        // arasında gidip gelir. Her tur çıplak konumu ölçüp aynı kesin kaymayı uygula.
        stack.style.removeProperty('transform');
        const waitingRect=waiting.getBoundingClientRect(),stackRect=stack.getBoundingClientRect();
        const contentRect=v2Content.getBoundingClientRect(),panelRect=mainPanel.getBoundingClientRect();
        const scaleX=waiting.offsetWidth?waitingRect.width/waiting.offsetWidth:1;
        const scaleY=waiting.offsetHeight?waitingRect.height/waiting.offsetHeight:1;
        const shift=alekLaunchVisualShift(waitingRect,stackRect,contentRect,panelRect,scaleX,scaleY,window.innerWidth,window.innerHeight);
        stack.style.setProperty('transform',`translate3d(${shift.x}px,${shift.y}px,0)`,'important');
    };
    requestAnimationFrame(()=>requestAnimationFrame(sync));
    [40,120,320].forEach(delay=>setTimeout(sync,delay));
};

const renderJourney = () => {
    const suppressJoAAuto=window.__ALEK_SUPPRESS_JOA_AUTO_OPEN__===true;
    // Journey'nin tek canlı yüzeyi JO A modülüdür. Eski kart ızgarasına geri
    // dönüş yolu kaldırıldı; modül hazırlanırken yalnız hafif bir host gösterilir.
    const waiting=document.createElement("div");
    waiting.className="joa-launch-placeholder";
    waiting.innerHTML=`<div class="joa-launch-center-stack"><img src="${getDynamicUrl("Assets/Bluemoon.png")}" alt=""><strong>Journey of<br>Adventurer</strong><small>Yaşayan yüzey hazırlanıyor…</small></div>`;
    primeJoALaunchLayout(waiting);
    v2Content.replaceChildren(waiting);
    alignJoALaunchPlaceholder(waiting);
    if(!suppressJoAAuto&&window.__ALEK_COSMIC_OPENING_LOCKED__!==true&&typeof window.__alekOpenJoAWorld==="function"){
        requestAnimationFrame(()=>window.__alekOpenJoAWorld({force:true}));
    }
};

// -------------------------- Hassas grid ve yakalama motoru --------------------------
const GRID_SIZE_OPTIONS=[5,10,20,40,80,160];
const normalizeGridSize=value=>{const n=Number(value)||40;return GRID_SIZE_OPTIONS.reduce((best,item)=>Math.abs(item-n)<Math.abs(best-n)?item:best,40);};
const snapWorkspacePoint=(point,gridSize,enabled)=>{if(!enabled)return{x:Number(point.x)||0,y:Number(point.y)||0};const size=Math.max(1,normalizeGridSize(gridSize));return{x:Math.round((Number(point.x)||0)/size)*size,y:Math.round((Number(point.y)||0)/size)*size};};
const nextGridSize=(current,direction)=>{const value=normalizeGridSize(current),index=Math.max(0,GRID_SIZE_OPTIONS.indexOf(value));return GRID_SIZE_OPTIONS[clamp(index+direction,0,GRID_SIZE_OPTIONS.length-1)];};

// -------------------------- Sonsuz çalışma alanı motoru --------------------------
// v60: Kullanılmayan WebGL 3D/CAD motoru ve arayüzü paket dışına çıkarıldı.
const createInfiniteWorkspace = ({camera, hasContent, className="", gridSize=40, allowRotation=false, allow3D=false}) => {
    const viewport=document.createElement("div");viewport.className=`infinite-workspace ${className}`;
    const world=document.createElement("div");world.className="infinite-world";viewport.appendChild(world);
    const snapCursor=document.createElement("div");snapCursor.className="grid-snap-cursor";viewport.appendChild(snapCursor);
    const state={lastClientX:null,lastClientY:null,panning:false,rotating3d:false,startX:0,startY:0,baseX:0,baseY:0,baseYaw:0,basePitch:0,gridSize:normalizeGridSize(gridSize),onViewChange:null};
    camera.zoom=clamp(Number(camera.zoom)||1,.12,5);camera.rotation=allowRotation?normalizeSignedAngle(Number(camera.rotation)||0):0;
    camera.mode3d=!!(allow3D&&camera.mode3d);camera.yaw=Number.isFinite(Number(camera.yaw))?Number(camera.yaw):-35;camera.pitch=clamp(Number.isFinite(Number(camera.pitch))?Number(camera.pitch):55,-78,78);
    const is3D=()=>!!(allow3D&&camera.mode3d);
    const planeMatrix=()=>{
        const zoom=Number(camera.zoom)||1;
        if(is3D()){
            const yaw=(Number(camera.yaw)||0)*Math.PI/180,pitch=(Number(camera.pitch)||0)*Math.PI/180,cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.max(.16,Math.cos(pitch));
            return{a:zoom*cy,b:zoom*cp*sy,c:-zoom*sy,d:zoom*cp*cy};
        }
        const rotation=(allowRotation?normalizeSignedAngle(camera.rotation):0)*Math.PI/180,c=Math.cos(rotation),s=Math.sin(rotation);
        return{a:zoom*c,b:zoom*s,c:-zoom*s,d:zoom*c};
    };
    const transformVector=point=>{const m=planeMatrix(),x=Number(point.x)||0,y=Number(point.y)||0;return{x:m.a*x+m.c*y,y:m.b*x+m.d*y};};
    const apply=()=>{
        if(!is3D())camera.rotation=allowRotation?normalizeSignedAngle(camera.rotation):0;
        const m=planeMatrix();world.style.transform=`matrix(${m.a},${m.b},${m.c},${m.d},${Number(camera.x)||0},${Number(camera.y)||0})`;
        viewport.classList.toggle("mode-3d",is3D());viewport.classList.toggle("mode-2d",!is3D());
        viewport.style.setProperty("--grid-size",`${state.gridSize*camera.zoom}px`);viewport.style.setProperty("--grid-x",`${Number(camera.x)||0}px`);viewport.style.setProperty("--grid-y",`${Number(camera.y)||0}px`);viewport.style.setProperty("--world-grid-size",`${state.gridSize}px`);
        state.onViewChange?.();
    };
    requestAnimationFrame(()=>{if(!camera.__ready){camera.x=viewport.clientWidth/2;camera.y=viewport.clientHeight/2;camera.zoom=1;camera.rotation=0;camera.__ready=true;}apply();});
    const viewportMetrics=()=>{const r=viewport.getBoundingClientRect(),cssW=Math.max(1,viewport.offsetWidth||viewport.clientWidth||r.width||1),cssH=Math.max(1,viewport.offsetHeight||viewport.clientHeight||r.height||1);return{r,scaleX:(r.width/cssW)||1,scaleY:(r.height/cssH)||1};};
    const clientToViewport=(clientX,clientY)=>{const {r,scaleX,scaleY}=viewportMetrics();return{x:(clientX-r.left)/scaleX,y:(clientY-r.top)/scaleY,scaleX,scaleY};};
    const screenToWorld=(clientX,clientY)=>{const local=clientToViewport(clientX,clientY),dx=local.x-(Number(camera.x)||0),dy=local.y-(Number(camera.y)||0),m=planeMatrix(),det=m.a*m.d-m.b*m.c||1;return{x:(m.d*dx-m.c*dy)/det,y:(-m.b*dx+m.a*dy)/det};};
    const worldToViewport=point=>{const v=transformVector(point);return{x:(Number(camera.x)||0)+v.x,y:(Number(camera.y)||0)+v.y};};
    const keepPointUnderCursor=(worldPoint,clientX,clientY)=>{const local=clientToViewport(clientX,clientY),v=transformVector(worldPoint);camera.x=local.x-v.x;camera.y=local.y-v.y;};
    const currentPointer=()=>{const r=viewport.getBoundingClientRect();return state.lastClientX==null?screenToWorld(r.left+r.width/2,r.top+r.height/2):screenToWorld(state.lastClientX,state.lastClientY);};
    const setGridSize=value=>{state.gridSize=normalizeGridSize(value);apply();};
    const setSnapIndicator=(point,visible=true)=>{if(!visible||!point){snapCursor.classList.remove("visible");return;}const p=worldToViewport(point);snapCursor.style.left=`${p.x}px`;snapCursor.style.top=`${p.y}px`;snapCursor.classList.add("visible");};
    const resetRotation=()=>{const r=viewport.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,before=screenToWorld(cx,cy);if(is3D()){camera.yaw=-35;camera.pitch=55;}else if(allowRotation)camera.rotation=0;keepPointUnderCursor(before,cx,cy);apply();scheduleAutoSave(null,120);};
    const set3DMode=enabled=>{if(!allow3D)return;const r=viewport.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,before=screenToWorld(cx,cy);camera.mode3d=!!enabled;if(camera.mode3d){if(!Number.isFinite(Number(camera.yaw)))camera.yaw=-35;if(!Number.isFinite(Number(camera.pitch)))camera.pitch=55;}keepPointUnderCursor(before,cx,cy);apply();};
    const setViewChangeHandler=handler=>{state.onViewChange=typeof handler==="function"?handler:null;};
    viewport.addEventListener("pointermove",e=>{state.lastClientX=e.clientX;state.lastClientY=e.clientY;});
    viewport.addEventListener("pointerleave",()=>snapCursor.classList.remove("visible"));
    viewport.addEventListener("wheel",e=>{e.preventDefault();const before=screenToWorld(e.clientX,e.clientY);if(!is3D()&&allowRotation&&e.altKey){camera.rotation=normalizeSignedAngle((Number(camera.rotation)||0)+(e.deltaY<0?4:-4));keepPointUnderCursor(before,e.clientX,e.clientY);apply();scheduleAutoSave(null,160);return;}camera.zoom=clamp(camera.zoom*(e.deltaY<0?1.12:.89),.12,5);keepPointUnderCursor(before,e.clientX,e.clientY);apply();scheduleAutoSave(null,220);},{passive:false});
    viewport.addEventListener("pointerdown",e=>{if(e.button!==1)return;e.preventDefault();const local=clientToViewport(e.clientX,e.clientY);state.startX=local.x;state.startY=local.y;if(is3D()&&e.altKey){state.rotating3d=true;state.baseYaw=Number(camera.yaw)||0;state.basePitch=Number(camera.pitch)||0;viewport.classList.add("rotating-3d");}else{state.panning=true;state.baseX=Number(camera.x)||0;state.baseY=Number(camera.y)||0;viewport.classList.add("panning");}try{viewport.setPointerCapture(e.pointerId);}catch(_){}});
    viewport.addEventListener("pointermove",e=>{const local=clientToViewport(e.clientX,e.clientY);if(state.rotating3d){camera.yaw=normalizeSignedAngle(state.baseYaw+(local.x-state.startX)*.38);camera.pitch=clamp(state.basePitch-(local.y-state.startY)*.32,-78,78);apply();return;}if(!state.panning)return;camera.x=state.baseX+(local.x-state.startX);camera.y=state.baseY+(local.y-state.startY);apply();});
    const endPan=e=>{if(!state.panning&&!state.rotating3d)return;state.panning=false;state.rotating3d=false;viewport.classList.remove("panning","rotating-3d");scheduleAutoSave(null,160);try{viewport.releasePointerCapture(e.pointerId);}catch(_){}};
    viewport.addEventListener("pointerup",endPan);viewport.addEventListener("pointercancel",endPan);viewport.addEventListener("auxclick",e=>{if(e.button===1)e.preventDefault();});
    return{viewport,world,camera,apply,screenToWorld,worldToViewport,currentPointer,setGridSize,setSnapIndicator,resetRotation,set3DMode,setViewChangeHandler,is3D,getGridSize:()=>state.gridSize};
};
const createLayer=(world,className,z,tag="div")=>{const el=tag==="svg"?document.createElementNS(svgNS,"svg"):document.createElement(tag);el.classList.add("workspace-layer");String(className||"").split(/\s+/).filter(Boolean).forEach(token=>el.classList.add(token));el.style.zIndex=String(z);if(tag==="svg"){el.setAttribute("width","1");el.setAttribute("height","1");el.style.overflow="visible";}world.appendChild(el);return el;};
const pinImagePath = pin => {
    const direct=String(pin?.imagePath||"");
    const legacyType=ALEK_PIN_TYPES.includes(pin?.pinType)?pin.pinType:(storyData.settings.boardPinType||"");
    const path=direct || ALEK_PIN_FILES.get(legacyType) || selectedPinCatalogItem()?.path || "";
    if(pin && !pin.imagePath && path) pin.imagePath=path;
    return getDynamicUrl(path)||getDynamicUrl("Raptiye/Raptiye.png")||"";
};
const makePinVisual = pin => {
    const el=document.createElement("button");el.className="board-pin";el.style.left=`${pin.x}px`;el.style.top=`${pin.y}px`;el.dataset.id=pin.id;
    const img=document.createElement("img");img.alt=`${pin.pinType||"A̤ɐ͜ɨǣ́ꞎ͡ƣ"} raptiyesi`;img.style.visibility="hidden";
    const fallback=document.createElement("span");fallback.textContent="📌";fallback.style.display="none";
    img.onload=()=>{img.style.visibility="visible";fallback.style.display="none";};img.onerror=()=>{img.remove();fallback.style.display="block";};img.src=pinImagePath(pin);
    const label=document.createElement("small");label.textContent=pin.title||"";el.append(img,fallback,label);return el;
};
const makeLabeledField = (caption,field) => {const label=document.createElement("label");const text=document.createElement("span");text.textContent=caption;label.append(text,field);return label;};
const makeToolbarGroup = (className,_label,...controls) => {
    const group=document.createElement("div");group.className=`toolbar-control-group ${className||""}`.trim();
    controls.flat().filter(Boolean).forEach(control=>group.appendChild(control));return group;
};
const openPinEditor = ({pin,pins,links,onDone,title="Raptiye"}) => {
    const wrap=document.createElement("div");wrap.className="pin-editor-grid";
    let selectedPath=pin.imagePath||pinCatalogItems().find(item=>item.name===pin.pinType)?.path||selectedPinCatalogItem()?.path||"";
    const preview=document.createElement("button");preview.type="button";preview.className="pin-editor-preview";
    const drawPreview=()=>{preview.replaceChildren();const img=document.createElement("img");img.src=getDynamicUrl(selectedPath);img.alt="Raptiye görseli";const text=document.createElement("span");text.textContent="Görseli Değiştir";preview.append(img,text);};drawPreview();
    preview.onclick=()=>openPinPalette(async item=>{selectedPath=item.path;await applySelectedPin(item);drawPreview();});
    const name=document.createElement("input");name.placeholder="İsteğe bağlı";name.value=pin.title||"";const note=document.createElement("textarea");note.placeholder="İsteğe bağlı mesaj veya araştırma notu";note.value=pin.note||"";
    wrap.append(makeLabeledField("Raptiye Görseli",preview),makeLabeledField("Başlık",name),makeLabeledField("Mesaj / Not",note));
    const modal=showV2Modal({title,body:wrap,saveText:"Kaydet",dangerText:"Raptiyeyi Sil",onSave:async()=>{pin.imagePath=selectedPath;pin.pinType=pinCatalogItems().find(item=>item.path===selectedPath)?.name||pin.pinType||"";storyData.settings.boardPinPath=selectedPath;pin.title=name.value.trim();pin.note=note.value;pin.updatedAt=new Date().toISOString();await saveToDB(null);onDone();}});
    if(modal.danger)modal.danger.onclick=async()=>{const idx=pins.findIndex(p=>p.id===pin.id);if(idx>=0)pins.splice(idx,1);for(let i=links.length-1;i>=0;i--)if(links[i].from===pin.id||links[i].to===pin.id)links.splice(i,1);modal.shade.remove();await saveToDB(null);onDone();};
};
const probeWorkspaceImageSize=(path,targetMax=380)=>new Promise(resolve=>{const fallback=Math.max(80,Number(targetMax)||380),img=new Image();let done=false;const finish=(w=fallback,h=Math.max(80,Math.round(fallback*0.68)))=>{if(done)return;done=true;resolve({width:w,height:h});};const timer=setTimeout(()=>finish(),700);img.onload=()=>{clearTimeout(timer);const iw=Math.max(1,img.naturalWidth||fallback),ih=Math.max(1,img.naturalHeight||fallback),scale=Math.min(1,fallback/Math.max(iw,ih));finish(Math.max(80,Math.round(iw*scale)),Math.max(80,Math.round(ih*scale)));};img.onerror=()=>{clearTimeout(timer);finish();};img.src=getDynamicUrl(path);});
const normalizeWorkspaceImage=img=>Object.assign(img,{width:Number(img.width)||360,height:Number(img.height)||240,rotation:Number(img.rotation)||0,defaultRotation:Number(img.defaultRotation)||0,opacity:img.opacity==null?1:Number(img.opacity),z:Number(img.z)||0,locked:!!img.locked});
const normalizeSignedAngle=value=>{let angle=((Number(value)||0)%360+360)%360;if(angle>180)angle-=360;return Math.abs(angle)<.0001?0:angle;};
const formatImageAngle=(image,precise=false)=>{const value=normalizeSignedAngle((Number(image.rotation)||0)-(Number(image.defaultRotation)||0));const rounded=precise?Math.round(value*10)/10:Math.round(value);return `${rounded>0?"+":""}${rounded}°`;};
const cloneWorkspaceImage=img=>({...JSON.parse(JSON.stringify(img)),id:makeId("image"),x:Number(img.x)+28,y:Number(img.y)+28,createdAt:new Date().toISOString()});
const imageBounds=img=>{const w=Number(img.width)||1,h=Number(img.height)||1;return{x1:Number(img.x)||0,y1:Number(img.y)||0,x2:(Number(img.x)||0)+w,y2:(Number(img.y)||0)+h};};
const mergeBounds=(bounds,b)=>{if(!b)return bounds;if(!bounds)return{...b};bounds.x1=Math.min(bounds.x1,b.x1);bounds.y1=Math.min(bounds.y1,b.y1);bounds.x2=Math.max(bounds.x2,b.x2);bounds.y2=Math.max(bounds.y2,b.y2);return bounds;};
const shapeBounds=shape=>{let pts=[];if(["triangle","rect3","ellipse3","polygon"].includes(shape?.type)&&typeof mapShapeToPolyline==="function")pts=mapShapeToPolyline(shape);else{if(shape.point)pts.push(shape.point);if(shape.start)pts.push(shape.start);if(shape.end)pts.push(shape.end);if(Array.isArray(shape.points))pts.push(...shape.points);}if(!pts.length)return null;const pad=Math.max(12,Number(shape.width)||3)*3;return{x1:Math.min(...pts.map(p=>p.x))-pad,y1:Math.min(...pts.map(p=>p.y))-pad,x2:Math.max(...pts.map(p=>p.x))+pad,y2:Math.max(...pts.map(p=>p.y))+pad};};
const fitAllInWorkspace=(workspace,bounds)=>{if(!bounds){workspace.camera.x=workspace.viewport.clientWidth/2;workspace.camera.y=workspace.viewport.clientHeight/2;workspace.camera.zoom=1;workspace.camera.__ready=true;workspace.apply();return;}const pad=80,w=Math.max(1,bounds.x2-bounds.x1),h=Math.max(1,bounds.y2-bounds.y1);const zoom=clamp(Math.min((workspace.viewport.clientWidth-pad*2)/w,(workspace.viewport.clientHeight-pad*2)/h),.12,3);workspace.camera.zoom=zoom;workspace.camera.x=workspace.viewport.clientWidth/2-(bounds.x1+bounds.x2)/2*zoom;workspace.camera.y=workspace.viewport.clientHeight/2-(bounds.y1+bounds.y2)/2*zoom;workspace.camera.__ready=true;workspace.apply();scheduleAutoSave(null,100);};
const makeEditableImage=(image,ctx)=>{
    normalizeWorkspaceImage(image);const item=document.createElement("div");item.className="workspace-image-item";item.dataset.id=image.id;
    const angleBadge=document.createElement("div");angleBadge.className="image-angle-badge";
    const apply=()=>{item.style.left=`${image.x}px`;item.style.top=`${image.y}px`;item.style.width=`${image.width}px`;item.style.height=`${image.height}px`;item.style.opacity=String(image.opacity);item.style.transform=`rotate(${image.rotation}deg)`;item.style.zIndex=String(10+image.z);item.classList.toggle("locked",image.locked);angleBadge.textContent=`Açı ${formatImageAngle(image,true)}`;angleBadge.style.transform=`translateX(-50%) rotate(${-Number(image.rotation||0)}deg)`;};
    const img=document.createElement("img");img.src=getDynamicUrl(image.path);img.alt="Çalışma alanı resmi";const controls=document.createElement("div");controls.className="image-edit-controls";
    const up=document.createElement("button");up.textContent="↑";up.title="Öne al";const down=document.createElement("button");down.textContent="↓";down.title="Arkaya al";const copy=document.createElement("button");copy.textContent="⧉";copy.title="Kopyala";const lock=document.createElement("button");lock.textContent=image.locked?"🔒":"🔓";lock.title="Kilitle / aç";const del=document.createElement("button");del.textContent="×";del.title="Sil";const opacity=document.createElement("input");opacity.type="range";opacity.min="0.1";opacity.max="1";opacity.step="0.05";opacity.value=String(image.opacity);controls.append(down,up,copy,lock,opacity,del);
    const resize=document.createElement("span");resize.className="image-resize-handle";const rotate=document.createElement("span");rotate.className="image-rotate-handle";rotate.textContent="↻";rotate.title="Serbest döndür · Shift: varsayılan duruşa göre 1° adımlar";item.append(img,controls,resize,rotate,angleBadge);apply();
    item.onclick=e=>{e.stopPropagation();if(ctx.mode()!=="select")return;ctx.select(image.id);ctx.syncSelection();};
    let drag=null;item.addEventListener("pointerdown",e=>{if(e.button!==0||ctx.mode()!=="select"||image.locked||e.target.closest("button,input,.image-resize-handle,.image-rotate-handle"))return;e.stopPropagation();const world=typeof ctx.screenToWorld==="function"?ctx.screenToWorld(e.clientX,e.clientY):null;drag={x:e.clientX,y:e.clientY,wx:world?.x,wy:world?.y,ox:image.x,oy:image.y};item.setPointerCapture?.(e.pointerId);});
    item.addEventListener("pointermove",e=>{if(!drag)return;let next;if(typeof ctx.screenToWorld==="function"&&Number.isFinite(drag.wx)&&Number.isFinite(drag.wy)){const world=ctx.screenToWorld(e.clientX,e.clientY);next={x:drag.ox+world.x-drag.wx,y:drag.oy+world.y-drag.wy};}else next={x:drag.ox+(e.clientX-drag.x)/ctx.zoom(),y:drag.oy+(e.clientY-drag.y)/ctx.zoom()};if(typeof ctx.snap==="function")next=ctx.snap(next);image.x=next.x;image.y=next.y;apply();});item.addEventListener("pointerup",async e=>{if(!drag)return;drag=null;item.releasePointerCapture?.(e.pointerId);await saveToDB(null);});
    let rs=null;resize.addEventListener("pointerdown",e=>{if(image.locked)return;e.stopPropagation();const world=typeof ctx.screenToWorld==="function"?ctx.screenToWorld(e.clientX,e.clientY):null;rs={x:e.clientX,y:e.clientY,wx:world?.x,wy:world?.y,w:image.width,h:image.height,ratio:Math.max(.01,image.width/Math.max(1,image.height))};resize.setPointerCapture?.(e.pointerId);});resize.addEventListener("pointermove",e=>{if(!rs)return;let dx,dy;if(typeof ctx.screenToWorld==="function"&&Number.isFinite(rs.wx)&&Number.isFinite(rs.wy)){const world=ctx.screenToWorld(e.clientX,e.clientY);dx=world.x-rs.wx;dy=world.y-rs.wy;}else{dx=(e.clientX-rs.x)/ctx.zoom();dy=(e.clientY-rs.y)/ctx.zoom();}let nextW=Math.max(60,rs.w+dx),nextH=Math.max(60,rs.h+dy);if(e.shiftKey){const relativeW=Math.abs(nextW-rs.w)/Math.max(1,rs.w),relativeH=Math.abs(nextH-rs.h)/Math.max(1,rs.h);if(relativeW>=relativeH)nextH=Math.max(60,nextW/rs.ratio);else nextW=Math.max(60,nextH*rs.ratio);}image.width=nextW;image.height=nextH;apply();});resize.addEventListener("pointerup",async e=>{if(!rs)return;rs=null;resize.releasePointerCapture?.(e.pointerId);await saveToDB(null);});
    let rr=null;rotate.addEventListener("pointerdown",e=>{if(image.locked)return;e.stopPropagation();const r=item.getBoundingClientRect();rr={base:Number(image.rotation)||0,start:Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2)),defaultRotation:Number(image.defaultRotation)||0};item.classList.add("rotating");rotate.setPointerCapture?.(e.pointerId);});rotate.addEventListener("pointermove",e=>{if(!rr)return;const r=item.getBoundingClientRect();const a=Math.atan2(e.clientY-(r.top+r.height/2),e.clientX-(r.left+r.width/2));const raw=rr.base+(a-rr.start)*180/Math.PI;image.rotation=e.shiftKey?rr.defaultRotation+Math.round(raw-rr.defaultRotation):raw;apply();});rotate.addEventListener("pointerup",async e=>{if(!rr)return;rr=null;item.classList.remove("rotating");rotate.releasePointerCapture?.(e.pointerId);await saveToDB(null);apply();});
    up.onclick=async e=>{e.stopPropagation();image.z=Math.max(...ctx.images.map(i=>Number(i.z)||0),0)+1;apply();await saveToDB(null);};down.onclick=async e=>{e.stopPropagation();image.z=Math.min(...ctx.images.map(i=>Number(i.z)||0),0)-1;apply();await saveToDB(null);};copy.onclick=async e=>{e.stopPropagation();ctx.images.push(cloneWorkspaceImage(image));await saveToDB(null);ctx.rerender();};lock.onclick=async e=>{e.stopPropagation();image.locked=!image.locked;await saveToDB(null);ctx.rerender();};del.onclick=async e=>{e.stopPropagation();const i=ctx.images.findIndex(x=>x.id===image.id);if(i>=0)ctx.images.splice(i,1);await saveToDB(null);ctx.rerender();};opacity.oninput=()=>{image.opacity=Number(opacity.value);apply();};opacity.onchange=()=>saveToDB(null);
    return item;
};

// -------------------------- Tide Of A̤ɐ͜ɨǣ́ꞎ͡ƣ --------------------------
const tideLinkText=rel=>[rel.eventName,rel.note].map(value=>String(value||"").trim()).filter(Boolean).join(" · ");
const openTideLinkEditor=(rel,data,onDone)=>{
    const wrap=document.createElement("div"),direction=document.createElement("button"),eventName=document.createElement("input"),note=document.createElement("textarea"),reverse=document.createElement("button");
    let directionValue=rel.direction||"two-way";
    const drawDirection=()=>{direction.type="button";direction.className="tide-direction-toggle";direction.textContent=directionValue==="one-way"?"→ Tek Yönlü":"↔ Çift Yönlü";direction.classList.toggle("active",directionValue==="two-way");};
    drawDirection();direction.onclick=()=>{directionValue=directionValue==="one-way"?"two-way":"one-way";drawDirection();};
    eventName.value=rel.eventName||"";eventName.placeholder="Örn. Feryat Buhranı, evlilik, ihanet...";note.value=rel.note||"";note.placeholder="Bağın orta noktasında gösterilecek açıklama";reverse.type="button";reverse.className="tide-reverse-link";reverse.textContent="⇄ Bağın yönünü ters çevir";reverse.onclick=()=>{const from=rel.from;rel.from=rel.to;rel.to=from;new Notice("Bağın yönü ters çevrildi.");};
    wrap.append(makeLabeledField("Bağ türü",direction),makeLabeledField("Olay",eventName),makeLabeledField("Not",note),reverse);
    const modal=showV2Modal({title:"Tide Of A̤ɐ͜ɨǣ́ꞎ͡ƣ Bağı",body:wrap,saveText:"Bağı Kaydet",dangerText:"Bağı Sil",onSave:async()=>{rel.direction=directionValue;rel.eventName=eventName.value.trim();rel.note=note.value.trim();rel.updatedAt=new Date().toISOString();await saveToDB(null);onDone();}});
    if(modal.danger)modal.danger.onclick=async()=>{data.links=data.links.filter(item=>item.id!==rel.id);modal.shade.remove();await saveToDB(null);onDone();};
};
const nextTideSketchNumber=()=>{const root=storyData.connections;return Math.max(Number(root.lastSketchNumber)||0,...(root.sketches||[]).map(s=>Number(s.number)||0))+1;};
const blankTideSketch=number=>({id:makeId("tide_realm"),number,name:`Realm-${number}`,camera:{x:0,y:0,zoom:1},gridSize:40,snapToGrid:false,pins:[],links:[],images:[],createdAt:new Date().toISOString()});
const ensureTideSketchSystem=()=>{
    const root=storyData.connections;
    if(!Array.isArray(root.sketches))root.sketches=[];
    const hasLegacy=(Array.isArray(root.pins)&&root.pins.length)||(Array.isArray(root.links)&&root.links.length)||(Array.isArray(root.images)&&root.images.length)||root.camera?.__ready;
    if(!root.sketches.length&&hasLegacy){const migrated=blankTideSketch(1);migrated.name="Realm-1";migrated.camera=root.camera||migrated.camera;migrated.pins=Array.isArray(root.pins)?root.pins:[];migrated.links=Array.isArray(root.links)?root.links:[];migrated.images=Array.isArray(root.images)?root.images:[];migrated.gridSize=normalizeGridSize(root.gridSize||40);migrated.snapToGrid=!!root.snapToGrid;root.sketches.push(migrated);root.activeSketchId=migrated.id;root.lastSketchNumber=Math.max(Number(root.lastSketchNumber)||0,1);}
    if(!root.sketches.length){const first=blankTideSketch(1);root.sketches.push(first);root.activeSketchId=first.id;root.lastSketchNumber=1;}
    root.sketches.forEach((item,index)=>{item.number=Number(item.number)||index+1;if(!item.name||/^Sketch[-_ ]*\d+$/i.test(item.name))item.name=`Realm-${item.number}`;});
    return root;
};
const ensureActiveTideSketch=()=>{const root=ensureTideSketchSystem();let sketch=root.sketches.find(item=>item.id===root.activeSketchId)||root.sketches[0];root.activeSketchId=sketch.id;if(!sketch.camera)sketch.camera={x:0,y:0,zoom:1};sketch.gridSize=normalizeGridSize(sketch.gridSize||40);sketch.snapToGrid=!!sketch.snapToGrid;if(!Array.isArray(sketch.pins))sketch.pins=[];if(!Array.isArray(sketch.links))sketch.links=[];if(!Array.isArray(sketch.images))sketch.images=[];return sketch;};
const createTideSketch=async()=>{const root=ensureTideSketchSystem(),number=nextTideSketchNumber(),sketch=blankTideSketch(number);root.lastSketchNumber=number;root.sketches.push(sketch);root.activeSketchId=sketch.id;await saveToDB(null);return sketch;};
