// -------------------------- Map --------------------------
const sectionTitleFromLegacyName=section=>{
    if(typeof section.sectionTitle==="string")return section.sectionTitle.trim();
    const raw=String(section.name||"").trim();
    if(!raw||/^(?:Sketch|Section)[-_ ]*-?\d+$/i.test(raw))return"";
    return raw.replace(/^(?:Sketch|Section)[-_ ]*-?\d+\s*(?:[·:–—-]\s*)?/i,"").trim();
};
const sectionNumberValue=section=>{const value=Number(section?.number);return Number.isFinite(value)&&value!==0?Math.trunc(value):1;};
const sectionDisplayName=section=>String(section?.sectionTitle||"").trim()||`Section ${sectionNumberValue(section)}`;
const parseLegacySectionNumber=section=>{
    const direct=Number(section?.number);if(Number.isFinite(direct)&&direct!==0)return Math.trunc(direct);
    const match=String(section?.name||"").match(/(?:Sketch|Section)[-_ ]*(-?\d+)/i);const parsed=Number(match?.[1]);return Number.isFinite(parsed)&&parsed!==0?Math.trunc(parsed):null;
};
const realmTitleFromLegacyName=realm=>{
    if(typeof realm.realmTitle==="string")return realm.realmTitle.trim();
    const raw=String(realm.name||"").trim();
    if(!raw||/^(?:Sketch|Realm)[-_ ]*\d+$/i.test(raw))return"";
    return raw.replace(/^(?:Sketch|Realm)[-_ ]*\d+\s*(?:[·:–—-]\s*)?/i,"").trim();
};
const realmDisplayName=realm=>String(realm?.realmTitle||"").trim()||`Realm ${Number(realm?.number)||1}`;
const blankSketch=(number,template=null)=>({
    id:makeId("section"),number,sectionTitle:"",name:`Section ${number}`,
    camera:template?.camera?{...template.camera}:{x:0,y:0,zoom:1,rotation:0,mode3d:false,yaw:-45,pitch:35,roll:0,distance:900,targetX:0,targetY:0,targetZ:0,perspective:true},
    gridSize:normalizeGridSize(template?.gridSize||40),snapToGrid:!!template?.snapToGrid,view3d:!!template?.view3d,depth3d:clamp(Number(template?.depth3d)||40,1,1000000),
    elements:[],strokes:[],redoStrokes:[],pins:[],solids:[],workplanes:[],activeWorkplaneId:"base",createdAt:new Date().toISOString()
});
const blankRealm=(number,sections=null)=>{
    const list=Array.isArray(sections)?sections:[blankSketch(1)];
    return{id:makeId("realm"),number,realmTitle:"",name:`Realm ${number}`,activeSectionId:list[0]?.id||null,sectionGroundId:list[0]?.id||null,sections:list,createdAt:new Date().toISOString()};
};
const normalizeMapRealms=()=>{
    const map=storyData.map;
    // v22.3 ve öncesindeki düz sketches dizisini tek Realm içine kayıpsız taşı.
    if(!Array.isArray(map.realms)){
        const legacySections=Array.isArray(map.sketches)?map.sketches.filter(item=>item&&typeof item==="object"):[];
        const migrated=blankRealm(1,legacySections.length?legacySections:[blankSketch(1)]);
        migrated.realmTitle=String(map.realmTitle||"").trim();
        migrated.activeSectionId=map.activeSketchId||migrated.sections[0]?.id||null;
        migrated.sectionGroundId=map.sectionGroundId||migrated.sections.find(section=>parseLegacySectionNumber(section)===1)?.id||migrated.sections[0]?.id||null;
        map.realms=[migrated];
    }
    map.realms=map.realms.filter(realm=>realm&&typeof realm==="object");
    if(!map.realms.length)map.realms.push(blankRealm(1));
    map.realms.forEach((realm,index)=>{
        if(!realm.id)realm.id=makeId("realm");
        realm.number=index+1;
        realm.realmTitle=realmTitleFromLegacyName(realm);
        realm.name=realmDisplayName(realm);
        if(!Array.isArray(realm.sections))realm.sections=[];
        realm.sections=realm.sections.filter(section=>section&&typeof section==="object");
        if(!realm.sections.length)realm.sections.push(blankSketch(1));
    });
    if(!map.realms.some(realm=>realm.id===map.activeRealmId))map.activeRealmId=map.realms[0].id;
    map.lastRealmNumber=map.realms.length;
    map.realmModelVersion=1;
    if(!Number.isFinite(Number(map.sectionModelVersion)))map.sectionModelVersion=0;
    if(typeof map.showUpperSectionGhost!=="boolean")map.showUpperSectionGhost=true;
    delete map.sketches;delete map.activeSketchId;delete map.sectionGroundId;delete map.lastSketchNumber;
    return map.realms;
};
const ensureActiveRealm=()=>{
    const realms=normalizeMapRealms();
    let realm=realms.find(item=>item.id===storyData.map.activeRealmId)||realms[0];
    storyData.map.activeRealmId=realm.id;
    return realm;
};
const sectionStepNumber=(number,direction)=>{
    const value=Number.isFinite(Number(number))&&Number(number)!==0?Math.trunc(Number(number)):1;
    if(direction>0)return value===-1?1:value+1;
    return value===1?-1:value-1;
};
const normalizeMapSections=(realm=ensureActiveRealm())=>{
    const sections=realm.sections;
    const used=new Set();
    let fallback=1;
    sections.forEach(section=>{
        if(!section.id)section.id=makeId("section");
        let number=parseLegacySectionNumber(section);
        if(!Number.isFinite(number)||number===0||used.has(number)){
            while(used.has(fallback)||fallback===0)fallback=sectionStepNumber(fallback,1);
            number=fallback;
        }
        section.number=Math.trunc(number);
        used.add(section.number);
        fallback=sectionStepNumber(section.number,1);
    });
    sections.sort((a,b)=>sectionNumberValue(a)-sectionNumberValue(b));
    let ground=sections.find(section=>section.id===realm.sectionGroundId)||sections.find(section=>sectionNumberValue(section)===1)||sections[0]||null;
    realm.sectionGroundId=ground?.id||null;
    sections.forEach(section=>{
        section.sectionTitle=sectionTitleFromLegacyName(section);
        section.name=sectionDisplayName(section);
        if(!section.camera)section.camera={x:0,y:0,zoom:1,rotation:0,mode3d:false,yaw:-45,pitch:35,roll:0,distance:900,targetX:0,targetY:0,targetZ:0,perspective:true};section.camera.rotation=normalizeSignedAngle(Number(section.camera.rotation)||0);section.camera.yaw=normalizeSignedAngle(Number.isFinite(Number(section.camera.yaw))?Number(section.camera.yaw):-45);section.camera.pitch=clamp(Number.isFinite(Number(section.camera.pitch))?Number(section.camera.pitch):35,-88,88);section.camera.roll=normalizeSignedAngle(Number(section.camera.roll)||0);section.camera.distance=clamp(Number(section.camera.distance)||900,20,1000000);section.camera.targetX=Number(section.camera.targetX)||0;section.camera.targetY=Number(section.camera.targetY)||0;section.camera.targetZ=Number(section.camera.targetZ)||0;section.camera.perspective=section.camera.perspective!==false;section.view3d=false;section.depth3d=clamp(Number(section.depth3d)||40,1,1000000);section.camera.mode3d=false;
        section.gridSize=normalizeGridSize(section.gridSize||40);
        section.snapToGrid=!!section.snapToGrid;
        if(!Array.isArray(section.elements))section.elements=Array.isArray(section.images)?section.images:[];
        if(!Array.isArray(section.strokes))section.strokes=Array.isArray(section.drawings)?section.drawings:[];
        if(!Array.isArray(section.redoStrokes))section.redoStrokes=[];
        if(!Array.isArray(section.pins))section.pins=[];
        if(!Array.isArray(section.solids))section.solids=[];
        if(!Array.isArray(section.workplanes))section.workplanes=[];
        if(typeof section.activeWorkplaneId!=="string")section.activeWorkplaneId="base";
        section.workplanes=section.workplanes.filter(item=>item&&typeof item==="object").map(item=>({id:String(item.id||makeId("workplane")),name:String(item.name||"Ek Düzlem"),origin:Array.isArray(item.origin)?item.origin.slice(0,3).map(v=>Number(v)||0):[0,0,0],rotation:Array.isArray(item.rotation)?item.rotation.slice(0,3).map(v=>normalizeSignedAngle(Number(v)||0)):[0,0,0],visible:item.visible!==false&&!item.archived,temporary:false,archived:!!item.archived,createdAt:item.createdAt||new Date().toISOString()}));
        if(section.activeWorkplaneId!=="base"&&!section.workplanes.some(item=>item.id===section.activeWorkplaneId))section.activeWorkplaneId="base";
        section.solids=section.solids.filter(item=>item&&typeof item==="object");
        section.elements=section.elements.filter(item=>item&&typeof item==="object");
        section.strokes=section.strokes.filter(item=>item&&typeof item==="object");
        section.redoStrokes=section.redoStrokes.filter(item=>item&&typeof item==="object");
        section.pins=section.pins.filter(item=>item&&typeof item==="object");
    });
    storyData.map.sectionModelVersion=4;
    if(!sections.some(section=>section.id===realm.activeSectionId))realm.activeSectionId=sections[0]?.id||null;
    return sections;
};
const createRealm=async()=>{
    const realms=normalizeMapRealms(),realm=blankRealm(realms.length+1);
    realms.push(realm);normalizeMapRealms();storyData.map.activeRealmId=realm.id;
    await saveToDB(null);return realm;
};
const createSketch=async(position="above")=>{
    const realm=ensureActiveRealm(),sections=normalizeMapSections(realm);
    const active=sections.find(section=>section.id===realm.activeSectionId)||sections[0]||null;
    const activeNumber=sectionNumberValue(active),isAbove=position!=="below";
    if(isAbove){
        [...sections].sort((a,b)=>sectionNumberValue(b)-sectionNumberValue(a)).forEach(item=>{
            if(sectionNumberValue(item)>activeNumber)item.number=sectionStepNumber(item.number,1);
        });
    }else{
        [...sections].sort((a,b)=>sectionNumberValue(a)-sectionNumberValue(b)).forEach(item=>{
            if(sectionNumberValue(item)<activeNumber)item.number=sectionStepNumber(item.number,-1);
        });
    }
    const section=blankSketch(sectionStepNumber(activeNumber,isAbove?1:-1),active);
    sections.push(section);
    normalizeMapSections(realm);realm.activeSectionId=section.id;
    await saveToDB(null);return section;
};
const sectionHasMapContent=section=>!!section&&((section.elements?.length||0)+(section.strokes?.length||0)+(section.pins?.length||0)+(section.solids?.length||0)>0);
const ensureActiveSketch=(realm=ensureActiveRealm())=>{
    const sections=normalizeMapSections(realm);
    let section=sections.find(item=>item.id===realm.activeSectionId);
    if(!section&&sections.length)section=[...sections].reverse().find(sectionHasMapContent)||sections.find(item=>item.id===realm.sectionGroundId)||sections[0];
    if(!section){section=blankSketch(1);sections.push(section);realm.sectionGroundId=section.id;normalizeMapSections(realm);}
    realm.activeSectionId=section.id;
    return section;
};
