let alekMapTooltipTimer=0,alekMapTooltip=null,alekMapTooltipTarget=null;
function closeAlekMapTooltip(){clearTimeout(alekMapTooltipTimer);alekMapTooltipTimer=0;alekMapTooltip?.remove();alekMapTooltip=null;alekMapTooltipTarget=null;}
function getAlekMapTooltipText(target){return String(target?.dataset?.tip||target?.getAttribute?.("aria-label")||target?.getAttribute?.("title")||"").trim();}
function showAlekMapTooltipNow(target){
    if(!target?.isConnected)return;const tip=getAlekMapTooltipText(target);if(!tip)return;
    alekMapTooltip?.remove();const rect=target.getBoundingClientRect(),el=document.createElement("div");el.className="alek-map-portal-tooltip";el.textContent=tip;document.body.appendChild(el);
    const width=el.offsetWidth,height=el.offsetHeight,left=Math.min(window.innerWidth-width-10,Math.max(10,rect.left+rect.width/2-width/2));let top=rect.top-height-10;if(top<8)top=rect.bottom+10;
    el.style.left=`${left}px`;el.style.top=`${top}px`;alekMapTooltip=el;
}
function scheduleAlekMapTooltip(target){
    if(!target||target===alekMapTooltipTarget)return;closeAlekMapTooltip();alekMapTooltipTarget=target;alekMapTooltipTimer=setTimeout(()=>showAlekMapTooltipNow(target),0);
}
