let __alekWorldMapToggleAt=0;
const __alekLegacyWorldMapToggle=()=>{
    const now=Date.now();if(now-__alekWorldMapToggleAt<900)return false;__alekWorldMapToggleAt=now;
    void(journeyWorldOverlay?closeJourneyWorld():openJourneyWorld());return true;
};
window.__alekLegacyToggleWorldMap=__alekLegacyWorldMapToggle;
if(typeof window.__alekSetWorldMapToggleHandler==="function")
    window.__alekSetWorldMapToggleHandler(__alekLegacyWorldMapToggle);
else
    window.__alekToggleWorldMap=__alekLegacyWorldMapToggle;

