// İmge Paleti küresel kısayolu. Alt+G paleti açar; F2 daima Map açar.
document.addEventListener("keydown",e=>{
    const key=String(e.key||"").toLowerCase();
    const altG=e.altKey&&!e.ctrlKey&&!e.shiftKey&&!e.metaKey&&key==="g";
    const altS=e.altKey&&!e.ctrlKey&&!e.metaKey&&key==="s";
    if(altG){
        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        if(!e.repeat) openEmojiKeyboard();
    }
    if(altS){/* Eski Runtime bildirimi yalnız sessizce tüketilir. */}
},true);
document.addEventListener("keyup",e=>{
    const key=String(e.key||"").toLowerCase();
    if(e.altKey&&!e.ctrlKey&&!e.metaKey&&key==="s"){e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();}
},true);

// Tam Kağıt ESC ile kapanır; üstte bir modal varsa önce o modal kendi ESC davranışını kullanır.
document.addEventListener("keydown",e=>{
    if(e.key!=="Escape"||!__alekUnifiedActiveRecord)return;
    // Üstte başka bir geçici pencere varsa ESC önce onu kapatır; alttaki Kağıt korunur.
    if(document.querySelector(".taxonomy-circle-shade.r70,.shortcut-atlas-shade,.alek-primary-radial-shade,.joa-crop-modal.open,.joa-global-modal,.v2-modal-overlay,.alek-v2-modal-shade,.seal-modal-overlay,.alek-stat-modal-overlay,.adventure-portal-shade,.map-draw-palette-shade,.notes-modal-wrap"))return;
    e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();closeLegacyCharacter({useHistory:false});
},true);

// Kağıt ayrıntısı geçmişi yalnız Alt+E tarafından kullanılır.
document.addEventListener("keydown",e=>{
    const target=e.target,key=String(e.key||"").toLowerCase();
    if(!e.altKey||e.ctrlKey||e.metaKey||key!=="e"||!__alekUnifiedActiveRecord)return;
    if(target&&((target.matches&&target.matches("input,textarea,select"))||target.isContentEditable))return;
    e.preventDefault();e.stopPropagation();e.stopImmediatePropagation();closeLegacyCharacter();
},true);

const ALEK_MAP_LIBRARY_ENABLED=false;
const ALEK_RAPTIYE_ENABLED=false;
// · AltGr+M kaldırıldı; Cartographer’s Table ana daire diliminden açılır.

// Map ve Tide için gerçek işlem geçmişi. Metin alanlarında tarayıcı editörü çalışmaya devam eder.
document.addEventListener("keydown",async e=>{
    if(journeyWorldOverlay)return;
    const key=String(e.key||"").toLowerCase(),target=e.target;
    if(target&&((target.matches&&target.matches("input,textarea,select"))||target.isContentEditable))return;
    if(!(e.ctrlKey||e.metaKey)||e.altKey||!["map","connections"].includes(activeV2View))return;
    const kind=activeV2View==="map"?"map":"tide";
    if(key==="z"){
        e.preventDefault();e.stopPropagation();
        await applyViewHistory(kind,e.shiftKey?"redo":"undo");
    }else if(key==="y"&&!e.shiftKey){
        e.preventDefault();e.stopPropagation();
        await applyViewHistory(kind,"redo");
    }
},true);

document.addEventListener("keydown",e=>{
    const target=e.target;
    if(journeyWorldOverlay||activeV2View!=="journey"||e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;
    if(target&&((target.matches&&target.matches("input,textarea,select"))||target.isContentEditable))return;
    const key=String(e.key||"").toLowerCase();
    if(alekTaxonomyShade?.isConnected){
        if(key==="escape"){e.preventDefault();e.stopPropagation();closeJourneyTaxonomyCircle();}
        return;
    }
    if(key==="k"){
        const inventoryOpen=window.__alekCurrentPrimarySurface==="inventory"||!!document.querySelector(".joa-world-shell.joa-inventory-page-shell");
        if(!inventoryOpen)return;
        e.preventDefault();e.stopPropagation();e.stopImmediatePropagation?.();void createNewCharacter();
    }
    else if(key==="t"){e.preventDefault();e.stopPropagation();openTimeCampModal();}
    else if(e.key==="Delete"){e.preventDefault();e.stopPropagation();archiveJourneyKeys([...journeySelected]);}
},true);

document.addEventListener("keydown",e=>{
    if(journeyWorldOverlay)return;
    if(e.target&&["INPUT","TEXTAREA","SELECT"].includes(e.target.tagName))return;const key=e.key.toLowerCase();
    if(key==="q"&&!e.repeat){keyQDown=true;qKeyUsedForSelection=false;}
    if(key==="e"&&!e.repeat&&!e.altKey&&!e.ctrlKey&&!e.metaKey){keyEDown=true;keyEIntentUntil=Date.now()+2500;}
    if(key==="w"&&!e.repeat&&!e.altKey&&!e.ctrlKey&&!e.metaKey){keyWDown=true;keyWIntentUntil=Date.now()+2500;}
    if(key==="s"&&!e.repeat&&!e.altKey&&!e.ctrlKey&&!e.metaKey){keySDown=true;keySIntentUntil=Date.now()+2500;}
    if(e.key==="Shift"&&activeV2View==="map")activeMapRuntime?.refreshPointDraftShift?.(true);if(key==="r"&&!e.repeat){e.preventDefault();if(activeV2View==="connections")addConnectionPinAtPointer();else if(activeV2View==="map")addMapPinAtPointer();}if(key==="f"&&!e.repeat&&activeV2View==="map"){e.preventDefault();addMapLibraryItemAtPointer();}
    if(activeV2View==="map"&&activeMapRuntime?.isAreaSelectionMode?.()){if(e.key==="Enter"){e.preventDefault();e.stopPropagation();activeMapRuntime.commitAreaSelection?.();return;}if(e.key==="Delete"){e.preventDefault();e.stopPropagation();activeMapRuntime.deleteAreaSelection?.();return;}if(e.key==="Escape"){e.preventDefault();e.stopPropagation();activeMapRuntime.cancelAreaSelection?.();return;}}
    if(activeV2View==="map"&&mapSplineDraft){if(e.key==="Enter"){e.preventDefault();finishSpline(false).then(shape=>{activeMapRuntime?.redrawStrokes?.();});}else if(e.key==="Backspace"){e.preventDefault();mapSplineDraft.shape.points.pop();mapSplineDraft.liveEl?.remove();mapSplineDraft.liveEl=renderMapShape(activeMapRuntime.drawLayer,mapSplineDraft.shape,true);}else if(e.key==="Escape"){e.preventDefault();finishSpline(true);}}
    if(e.key==="Escape"&&!mapSplineDraft){activeMapRuntime?.cancelArc3?.();activeMapRuntime?.cancelPointDraft?.();if(journeySelected.size){const scrollSnapshot=captureAlekStableScroll();journeySelected.clear();const membersButton=__alekUnifiedActiveRecord?detailPanel.querySelector('.tabBtn[data-tab="members"].is-active'):null;if(membersButton)membersButton.click();else if(activeV2View==="journey")renderJourney();restoreAlekStableScroll(scrollSnapshot);new Notice("Q seçimi temizlendi.");}connectionLinkStartId=null;connectionLinkMode=false;if(activeV2View==="map"&&mapMode!=="select"){const scrollSnapshot=captureAlekStableScroll();mapMode="select";renderMap();restoreAlekStableScroll(scrollSnapshot);}}
});
document.addEventListener("keyup",async e=>{
    if(journeyWorldOverlay)return;
    const key=String(e.key||"").toLowerCase();
    if(e.key==="Shift"&&activeV2View==="map")activeMapRuntime?.refreshPointDraftShift?.(false);
    if(key==="q"){
        keyQDown=false;qKeyUsedForSelection=false;
    }
    if(key==="e"){keyEDown=false;keyEIntentUntil=0;}
    if(key==="w"){keyWDown=false;keyWIntentUntil=0;}
    if(key==="s"){keySDown=false;keySIntentUntil=0;}
});


// R22: Ctrl + tekerlek UI/WebView zoom yapmaz. Harita normal tekerleği kendi içinde kullanır.
if(!window.__alekCtrlWheelZoomBlockR22){window.__alekCtrlWheelZoomBlockR22=true;window.addEventListener("wheel",event=>{if(!event.ctrlKey)return;event.preventDefault();event.stopPropagation();event.stopImmediatePropagation?.();},{capture:true,passive:false});}

