const performanceLayoutStyle=document.createElement("style");performanceLayoutStyle.id="alekPerformanceAndLayout";performanceLayoutStyle.textContent=`
/* Takvim kumanda güvertesi */
.calendar-head{display:grid!important;grid-template-columns:42px 44px minmax(180px,1fr) minmax(120px,180px) 44px auto!important;gap:7px!important;align-items:center!important;margin:0 0 10px!important;padding:8px 9px!important;min-height:48px!important}
.calendar-head>button,.calendar-head>select,.calendar-head>input,.calendar-head>.jn-picker{min-width:0!important;height:34px!important;min-height:34px!important}.calendar-head>button{padding:0 10px!important}.calendar-head>button:nth-last-child(1){white-space:nowrap!important}.calendar-head select,.calendar-head input{width:100%!important;padding:0 8px!important}.calendar-head .jn-trigger{height:34px!important}.tavern-calendar{max-width:1300px!important}.calendar-week{margin-top:0!important}.calendar-grid-v2{gap:8px!important}.calendar-day-v2{min-height:112px!important;transform:none!important}.calendar-day-v2:hover{transform:none!important}
/* Map/Tide semantik, katmanlı araç grupları */
.board-tools{overflow:visible!important}.board-top-row{display:grid!important;grid-template-columns:minmax(205px,auto) minmax(0,1fr)!important;align-items:start!important;gap:10px!important}.board-action-row{display:flex!important;flex-wrap:wrap!important;align-items:flex-start!important;justify-content:flex-end!important;gap:7px!important;overflow:visible!important}.toolbar-control-group{position:relative;display:flex;align-items:center;flex-wrap:wrap;gap:4px;padding:15px 6px 5px;border:1px solid rgba(67,97,111,.52);border-radius:9px;background:rgba(4,13,18,.55);min-height:34px;box-sizing:border-box}.toolbar-group-label{position:absolute;left:8px;top:3px;color:#6f96a8;font-size:.57rem;font-weight:900;letter-spacing:.12em;line-height:1;pointer-events:none}.toolbar-control-group>button,.toolbar-control-group>select,.toolbar-control-group>input{height:30px!important;min-height:30px!important;padding:0 7px!important;font-size:.72rem!important;border-radius:7px!important}.toolbar-control-group>select{min-width:110px!important;max-width:180px!important}.realm-control-group .realm-select{min-width:145px!important}.section-control-group select{min-width:112px!important}.map-view-group{margin-left:auto}.map-drawbar{display:grid!important;grid-template-columns:minmax(410px,1fr) auto auto auto!important;gap:7px!important;padding:0!important;background:transparent!important;border:0!important;overflow:visible!important}.map-drawbar>.toolbar-control-group{align-content:center}.map-drawbar .map-tool-group{padding:0!important;border:0!important;background:transparent!important}.map-drawbar .draw-tools-group{min-width:410px}.map-drawbar .draw-tools-group .map-tool-group{display:flex;flex-wrap:wrap!important}.map-drawbar .map-tool-symbol{width:30px!important;min-width:30px!important;height:30px!important;font-size:.9rem!important}.map-drawbar input[type="color"]{width:34px!important}.map-drawbar .pin-palette-trigger img{width:21px!important;height:21px!important}.board-help{margin-top:0!important;padding:4px 8px!important;min-height:0!important;font-size:.64rem!important;opacity:.82}.tide-root .board-action-row{justify-content:flex-end!important}.tide-root .tide-board-group{flex:1 1 auto}.tide-root .tide-view-group{margin-left:auto}
/* Görünen yüzeyler tam animasyonlu kalır; yalnız ECO profili görsel hareketi azaltır. */
.alek-v2-content{contain:layout paint style!important}.board-root,.harmonizer-shell,.tavern-calendar,.journey-root,.lore-shell{contain:layout paint!important}.infinite-workspace,.workspace-viewport{contain:strict!important}html[data-alek-performance="eco"] .v9-core-moon,html[data-alek-performance="eco"] .v9-core-orb,html[data-alek-performance="eco"] .v9-cosmic-backdrop img{animation:none!important;will-change:auto!important}html[data-alek-performance="eco"] .v9-view-enter{animation:none!important}html[data-alek-performance="eco"] .workspace-image-item,html[data-alek-performance="eco"] .calendar-day-v2,html[data-alek-performance="eco"] .story-bubble,html[data-alek-performance="eco"] .toolbar-control-group{box-shadow:none!important}
html[data-alek-performance="eco"] .v9-core-moon,html[data-alek-performance="eco"] .calendar-day-v2:after{animation:none!important}html[data-alek-performance="eco"] .vertical-resource,html[data-alek-performance="balanced"] .vertical-resource{backdrop-filter:none!important}html[data-alek-performance="eco"] .bg-overlay{background:rgba(2,7,11,.34)!important}html[data-alek-performance="eco"] *{scroll-behavior:auto!important}html[data-alek-performance="balanced"] .v9-core-moon{animation:none!important}html[data-alek-performance="cinematic"] .v9-core-moon{animation:v9MoonBreath 5.5s ease-in-out infinite!important}
/* Performans ve GPU paneli */
.performance-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin:14px 0}.performance-card,.renderer-report{border:1px solid rgba(67,97,111,.58);border-radius:12px;background:linear-gradient(155deg,rgba(12,25,33,.95),rgba(5,11,16,.98));padding:14px}.performance-card h3,.renderer-report h3{margin:0 0 12px;color:#ead490;font-family:Georgia,serif}.performance-card label{display:flex;flex-direction:column;gap:6px;color:#8fa3ad;font-size:.78rem;margin-bottom:10px}.performance-card select{height:39px;border:1px solid #36515e;background:#071016;color:white;border-radius:8px;padding:0 10px}.sleep-status{display:grid;gap:7px;color:#7fd7a7;font-size:.77rem}.gpu-actions{display:flex;flex-wrap:wrap;gap:7px}.gpu-actions button{min-height:36px;border:1px solid #36515e;background:#10232c;color:#d9eef6;border-radius:8px;padding:7px 10px;cursor:pointer}.gpu-actions button:hover{border-color:#70c8e9}.renderer-report{display:grid;gap:7px}.renderer-report>.renderer-name{color:#dcebf1;overflow-wrap:anywhere}.renderer-report>.renderer-api,.gpu-bridge-state{color:#748a96}.adapter-list{display:grid;gap:6px;margin-top:6px}.adapter-row{display:flex;justify-content:space-between;gap:12px;padding:8px 10px;border:1px solid rgba(57,83,96,.55);border-radius:8px;background:rgba(4,12,17,.65)}.adapter-row b{color:#cfe6ef}.adapter-row span{color:#788d98;text-align:right}.gpu-bridge-state.ready{color:#7ed8a7}.gpu-bridge-state.warning{color:#e1b764}
.performance-profile-buttons{display:flex;flex-wrap:wrap;gap:8px;margin:14px 0}.performance-profile-buttons button{min-height:36px;padding:7px 12px;border:1px solid #36515e;border-radius:9px;background:#0c1d26;color:#c8e0ea;cursor:pointer}.performance-profile-buttons button:hover{border-color:#70c8e9}.performance-profile-buttons button.active{border-color:#d7b85c;background:linear-gradient(145deg,#263323,#172c34);color:#ffe5a0;box-shadow:0 0 16px rgba(215,184,92,.14)}
@media(max-width:1250px){.board-top-row{grid-template-columns:1fr!important}.board-action-row{justify-content:flex-start!important}.map-view-group,.tide-root .tide-view-group{margin-left:0}.map-drawbar{grid-template-columns:1fr auto auto!important}.map-drawbar .draw-assets-group{grid-column:1/-1}.calendar-head{grid-template-columns:42px 44px minmax(150px,1fr) 140px 44px auto!important}}
@media(max-width:900px){.calendar-head{grid-template-columns:42px 42px minmax(140px,1fr) 42px!important}.calendar-head>input{grid-column:1/3}.calendar-head>button:last-child{grid-column:3/5}.map-drawbar{grid-template-columns:1fr!important}.map-drawbar>.toolbar-control-group{min-width:0!important}.performance-grid{grid-template-columns:1fr}.harmonizer-side{grid-template-columns:repeat(4,minmax(145px,1fr))!important}.adapter-row{flex-direction:column}.adapter-row span{text-align:left}}
`;
