        const introNodes=[v9Masthead,v2Nav,v2Content].filter(Boolean);
        introNodes.forEach((node,index)=>{
            node.style.opacity="0";
            node.style.transform=index===0?"translateY(-16px)":index===1?"translateY(-10px)":"translateY(18px)";
        });
        const mastheadMoon=v9Masthead?.querySelector?.(".v9-core-orb");
        if(mastheadMoon)mastheadMoon.style.opacity="0";

        overlay.appendChild(mainPanel);
        document.body.appendChild(overlay);

        const runCosmicOpening=()=>{
            const splash=document.createElement("div");splash.className="alek-cosmic-opening";
            splash.innerHTML=`<div class="alek-opening-spark-field" aria-hidden="true"></div><div class="alek-opening-flight"><button class="alek-opening-moon" type="button" aria-label="Ałek’ryŧhæ kapısını aç"><span class="alek-opening-moon-aura" aria-hidden="true"></span><img src="${getDynamicUrl("Assets/Bluemoon.png")}" alt=""></button></div><div class="alek-opening-caption">Başlamak için aya tıkla</div>`;
            document.body.appendChild(splash);
            // R31 · Açılış katmanı JoA yüzeylerinin üstünde kalırken Ay uçuş hayaleti
            // onun da üstünde hareket edebilmelidir. Ayrıca WebView2 başlangıçta kısa bir
            // suspend sinyali bırakmışsa açılış rendererını doğrudan uyandır.
            try{
                document.documentElement.classList.remove("alek-suspend");
                window.__ALEK_RENDERER__?.setAppActive?.(true);
                window.dispatchEvent(new CustomEvent("alek:foreground-activity"));
            }catch(_){}
            const sparkField=splash.querySelector(".alek-opening-spark-field");
            // 240 kıvılcım korunur; her biri ayrı HTML/compositor katmanı olmak
            // yerine tek Canvas yüzeyinde ortak kare saatiyle çizilir.
            const sparkController=window.__ALEK_RENDERER__?.mountOpeningSparks(sparkField,{count:240})||null;
            const flight=splash.querySelector(".alek-opening-flight"),moon=splash.querySelector(".alek-opening-moon"),caption=splash.querySelector(".alek-opening-caption");let started=false;

            // FaeraTh v0.1.1 giriş sözleşmesi: her meteor tık anındaki gerçek
            // akışından yakalanır, kendi dış uç noktasına ilerleyip 2,4 saniyede söner.
            const OPENING_DRAIN_MS=2400;
            const extinguishOpeningSparks=()=>sparkController?.drain?.(OPENING_DRAIN_MS)
                ||new Promise(resolve=>window.setTimeout(resolve,OPENING_DRAIN_MS));

            const launch=async()=>{
                if(started)return;
                started=true;
                try{window.dispatchEvent(new CustomEvent("alek:user-activated"));}catch(_){}
                const heldFlightTransform=getComputedStyle(flight).transform;
                flight.style.setProperty("animation","none","important");
                if(heldFlightTransform&&heldFlightTransform!=="none")flight.style.transform=heldFlightTransform;
                splash.classList.add("alek-opening-locked","alek-opening-draining");
                moon.disabled=true;
                caption?.animate([{opacity:.8},{opacity:0}],{duration:220,fill:"forwards"});
                document.removeEventListener("keydown",onIntroKey,true);

                // Hedef arayüz partiküller sönerken görünmeden hazırlanır. Böylece son
                // kıvılcım ile Ay uçuşu arasına render kaynaklı boş bekleme girmez.
                const portal=renderAdventureManager({fromOpening:true});
                const target=portal?.querySelector?.(".adventure-portal-moon");

                const drainStartedAt=performance.now();
                await extinguishOpeningSparks();
                const drainRemaining=OPENING_DRAIN_MS-(performance.now()-drainStartedAt);
                if(drainRemaining>0)await new Promise(resolve=>setTimeout(resolve,drainRemaining));
                if(!document.body.contains(splash))return;

                splash.classList.remove("alek-opening-draining");
                moon.style.setProperty("animation","none","important");
                const moonImage=moon.querySelector("img");
                if(moonImage)moonImage.style.setProperty("animation","none","important");
                mainPanel.style.opacity="1";
                mainPanel.style.pointerEvents="auto";

                if(target)await flyMoonBetween(flight,target,{duration:940});
                splash.animate([{opacity:1},{opacity:0}],{duration:420,easing:"ease-out",fill:"forwards"}).finished.finally(()=>splash.remove());
            };
            const hitMoon=e=>{const r=moon.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2);if(Math.hypot(dx,dy)<=Math.min(r.width,r.height)*.48)launch();};
            moon.addEventListener("pointerdown",hitMoon);
            moon.addEventListener("keydown",e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();launch();}});
            // R29 · Esc artık açılışı atlatamaz. Kullanıcı Ayı gerçekten etkinleştirmeden
            // uygulama/Adventure geçidi açılmaz.
            const onIntroKey=e=>{if(e.key==="Escape"){e.preventDefault();e.stopPropagation();}};
            document.addEventListener("keydown",onIntroKey,true);
        };
        mastheadMoon?.setAttribute("role","button");mastheadMoon?.setAttribute("tabindex","0");mastheadMoon?.setAttribute("title","Macera geçidine dön");if(mastheadMoon){mastheadMoon.style.cursor="pointer";mastheadMoon.onclick=()=>renderAdventureManager({fromMoon:true});mastheadMoon.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();renderAdventureManager({fromMoon:true});}};}
        requestAnimationFrame(()=>requestAnimationFrame(runCosmicOpening));
        
        const cleanup = (val) => {
            if (document.body.contains(overlay)) document.body.removeChild(overlay); 
            pauseAmbianceRuntime({release:true}); 
            disposeViewRuntime(activeV2View); 
            
            if (typeof audioPlayer !== 'undefined') {
                snapshotActiveBard();
                audioPlayer.pause();
                saveToDB(null);
            }
            
            return val;
        };
        window.__alekCleanup = cleanup;
        document.addEventListener("keydown", (e) => { if (e.key === "Escape" && e.ctrlKey && e.shiftKey) cleanup(null); });

        // Bu işlevler initEngine try bloğunda tanımlıdır. Köprüyü aynı
        // sözcüksel kapsamda kuruyoruz; aksi hâlde bootstrap sonunda ReferenceError oluşur.
        window.__ALEK_JOURNEY_SIMULATION__=Object.freeze({
            estimateSpeechSeconds,
            formatDurationSeconds,
            formatGameTime,
            advanceSeconds:(seconds,options)=>advanceGameSeconds(seconds,options||{}),
            openTimeCamp:options=>openTimeCampModal(options||{}),
            getLedger:()=>cloneData(normalizeGameRuntime().timeLedger||[])
        });

        // Sonraki görünüm, stat, zaman ve modüler köprü yamaları da
        // motorun aynı sözcüksel kapsamında çalışır. Böylece iç motor değişkenleri
        // kapsam dışına taşınıp bootstrap sırasında kaybolmaz.

