document.head.appendChild(v53LayoutStyle);

const syncV53ViewportLayout=()=>{
  const shell=document.getElementById("alekV2Shell");
  const content=shell?.querySelector(":scope > .alek-v2-content");
  const masthead=shell?.querySelector(".v9-masthead");
  const nav=shell?.querySelector(".alek-v2-nav");
  if(!shell?.isConnected||!content?.isConnected)return;
  const shellHeight=Math.max(0,shell.clientHeight||0);
  if(shellHeight<=0)return;
  const headerHeight=Math.max(0,masthead?.offsetHeight||0);
  const navHeight=Math.max(0,nav?.offsetHeight||0);
  const usable=Math.max(0,Math.floor(shellHeight-headerHeight-navHeight));
  content.style.setProperty("--alek-v53-content-height",`${usable}px`);
};
const scheduleV53ViewportLayout=()=>requestAnimationFrame(()=>requestAnimationFrame(syncV53ViewportLayout));
scheduleV53ViewportLayout();
window.addEventListener("resize",scheduleV53ViewportLayout,{passive:true});

try{
  const v53ResizeObserver=new ResizeObserver(scheduleV53ViewportLayout);
  const shell=document.getElementById("alekV2Shell");
  const masthead=shell?.querySelector(".v9-masthead");
  const nav=shell?.querySelector(".alek-v2-nav");
  const panel=document.getElementById("alekLegacyMainPanel");
  if(shell)v53ResizeObserver.observe(shell);if(masthead)v53ResizeObserver.observe(masthead);if(nav)v53ResizeObserver.observe(nav);if(panel)v53ResizeObserver.observe(panel);
}catch(_){}


