const joaSyncPartyFollowersState=(state,party)=>{
    if(!state||!party)return[];
    const members=joaPartyMemberRecords(),memberKeys=new Set(members.map(record=>String(record.key)));
    const entities=Array.isArray(state.entities)?state.entities:(state.entities=[]);let changed=false;
    // Gruptan çıkan eski takipçi silinmez: son bulunduğu noktada bağımsız piyon olur.
    // Böylece üyeyi gruptan çıkarmak haritadaki varlığını yok etmez.
    for(const item of entities){
        if(String(item.type)!=="joa-entity"||item.__partyFollower!==true||memberKeys.has(String(item.sourceEntityKey||"")))continue;
        delete item.__partyFollower;delete item.__partyFormationIndex;delete item.__partyFormationVersion;item.updatedAt=new Date().toISOString();changed=true;
    }
    // Eski Journey-character piyonları, aynı karakter Macera Grubu üyesiyse ikinci bir
    // bağımsız piyon olarak kalamaz. Kanonik JoA follower piyonuna migrate edilir.
    const memberCharacterIds=new Set(members.filter(record=>record.type==="character").map(record=>String(record.entity?.id||"")).filter(Boolean));
    if(memberCharacterIds.size){
        const before=state.entities.length;
        state.entities=state.entities.filter(item=>!(String(item.type)==="journey-character"&&memberCharacterIds.has(String(item.sourceCharacterId||""))));
        if(state.entities.length!==before)changed=true;
    }
    const followerEntityKeys=new Set(),result=[];
    members.forEach((record,index)=>{
        const offset=joaPartyFormationOffset(index),targetX=(Number(party.x)||0)+offset.x,targetZ=(Number(party.z)||0)+offset.z,targetLayer=__alekNormalizeWorldLayer(party.layerKey);
        let entity=state.entities.find(item=>String(item.type)==="joa-entity"&&String(item.sourceEntityKey)===String(record.key));
        if(!entity){
            const id=makeId("map_party_member");
            entity={id,key:`joa-entity:${id}`,type:"joa-entity",sourceEntityKey:String(record.key),x:targetX,z:targetZ,layerKey:targetLayer,__partyFollower:true,__partyFormationIndex:index,__partyFormationVersion:JOA_PARTY_FORMATION_VERSION,createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
            state.entities.push(entity);changed=true;
        }
        const needsSync=entity.__partyFollower!==true||Number(entity.__partyFormationIndex)!==index||Number(entity.__partyFormationVersion)!==JOA_PARTY_FORMATION_VERSION||__alekNormalizeWorldLayer(entity.layerKey)!==targetLayer||Math.abs((Number(entity.x)||0)-targetX)>.0001||Math.abs((Number(entity.z)||0)-targetZ)>.0001;
        entity.__partyFollower=true;entity.__partyFormationIndex=index;entity.__partyFormationVersion=JOA_PARTY_FORMATION_VERSION;
        if(needsSync){entity.x=targetX;entity.z=targetZ;entity.layerKey=targetLayer;entity.updatedAt=new Date().toISOString();changed=true;}
        followerEntityKeys.add(String(entity.key));result.push(entity);
    });
    // Grup üyesi bağımsız rota taşıyamaz; hareket komutu yalnız Macera Grubu piyonuna verilir.
    if(Array.isArray(state.activeTravelRoutes)){
        const count=state.activeTravelRoutes.length;
        state.activeTravelRoutes=state.activeTravelRoutes.filter(route=>!followerEntityKeys.has(String(route?.key||"")));
        if(state.activeTravelRoutes.length!==count)changed=true;
    }
    return{followers:result,changed};
};
