// Q/E tuşu pencere odağını kaybedince takılı kalmasın; normal kart tıklaması her zaman normale dönebilsin.
const resetJourneyModifierKeys=()=>{keyQDown=false;keyEDown=false;keyWDown=false;keySDown=false;keyEIntentUntil=0;keyWIntentUntil=0;keySIntentUntil=0;qKeyUsedForSelection=false;};
window.addEventListener("blur",resetJourneyModifierKeys);
document.addEventListener("visibilitychange",()=>{if(document.hidden)resetJourneyModifierKeys();});
window.addEventListener("keyup",event=>{const key=String(event.key||"").toLowerCase();if(key==="e"){keyEDown=false;keyEIntentUntil=0;}if(key==="w"){keyWDown=false;keyWIntentUntil=0;}if(key==="s"){keySDown=false;keySIntentUntil=0;}},true);
window.addEventListener("pointercancel",resetJourneyModifierKeys,true);


