// ============================================================================
// · Ana daire dilimi, sıkı kaynak rayı ve sembol-only üst araçlar.
// ============================================================================
const __alekPrimaryPrimaryMenuItems=[
    {view:"encounter",label:"Tavern",full:"Tavern",glyph:"◫"}
];
let __alekPrimaryRadialShade=null;
let __alekPrimaryAiWasSuspended=false;
const __alekPrimaryCloseRadialMenu=({resumeAi=true}={})=>{
    if(__alekPrimaryRadialShade?.isConnected)__alekPrimaryRadialShade.remove();
    __alekPrimaryRadialShade=null;
    document.documentElement.classList.remove("alek-primary-radial-open");
    if(resumeAi&&__alekPrimaryAiWasSuspended&&activeV2View==="ai"){
        __alekPrimaryAiWasSuspended=false;
        requestAnimationFrame(()=>{try{renderSafeAiView();}catch(_){}});
    }else if(!resumeAi){
        __alekPrimaryAiWasSuspended=false;
    }
};
let __alekPrimaryF2ToggleAt=0;
const __alekPrimaryOpenRadialMenu=()=>{
    const now=Date.now();
    if(now-__alekPrimaryF2ToggleAt<180)return true;
    __alekPrimaryF2ToggleAt=now;
    try{__alekPrimaryCloseRadialMenu({resumeAi:false});}catch(_){}

    // F2 bir toggle değildir. Map açıksa yerinde kalır.
    if(document.querySelector(".joa-world-shell,.journey-world-overlay"))return true;

    void window.__alekOpenMapDirect?.();
    return true;
};
window.__alekOpenPrimaryRadial=__alekPrimaryOpenRadialMenu;

// v0.1.18 · ÇIKIŞ SAHNESİ GİRİŞTEN BAĞIMSIZDIR.
// Final kapanış, CosmicGate.cs tarafından enjekte edilen gerçek Promise köprüsünü kullanır.
// Renderer yalnız görseldir; pencereyi kapatma yetkisi Core'dadır.
let __alekMoonFarewellRunning=false;
let __alekMoonFarewellSplash=null;
let __alekMoonFarewellFinishing=false;
const __alekCanOpenFarewell=()=>{
    if(window.__alekHasBlockingWindow?.()===true)return false;
    return !!(document.querySelector('.joa-world-shell,.journey-world-overlay,.shortcut-atlas-shade')||["journey","encounter","ai"].includes(String(activeV2View||"")));
};
const __alekCoreExitExact=async()=>{
    // CosmicGate.cs'nin enjekte ettiği gerçek yol:
    // window.__alekAPI -> postMessage(JSON.stringify({op,id,payload})) -> case "app.exit" -> Close()
    if(typeof window.__alekAPI==="function"){
        try{
            const result=await window.__alekAPI("app.exit",{});
            if(result?.ok!==false)return true;
        }catch(_){ }
    }
    // Promise köprüsü yoksa yalnız aynı protokolün doğrudan biçimi denenir.
    try{
        if(window.chrome?.webview?.postMessage){
            const id=`__alek_exit_${Date.now()}_${Math.random().toString(16).slice(2)}`;
            window.chrome.webview.postMessage(JSON.stringify({op:"app.exit",id,payload:{}}));
            return true;
        }
    }catch(_){ }
    return false;
};
const __alekMoonFarewellExit=async()=>{
    if(__alekMoonFarewellRunning)return true;
    if(!__alekCanOpenFarewell())return false;
    __alekMoonFarewellRunning=true;
    try{captureAdventureUiState?.();scheduleAutoSave?.(null,0);}catch(_){ }

    const splash=document.createElement("div");
    splash.className="alek-cosmic-opening alek-cosmic-farewell";
    splash.innerHTML=`<div class="alek-opening-spark-field" aria-hidden="true"></div><div class="alek-opening-flight"><button class="alek-opening-moon" type="button" aria-label="Kapanışı tamamla"><span class="alek-opening-moon-aura" aria-hidden="true"></span><img src="${getDynamicUrl("Assets/Bluemoon.png")}" alt=""></button></div>`;
    const style=document.createElement("style");
    style.textContent=`
      .alek-cosmic-farewell{z-index:2147483647!important;opacity:0;animation:alekFarewellShow .16s ease-out forwards!important}
      .alek-cosmic-farewell .alek-opening-flight{animation:alekV50MoonFloat 7.2s ease-in-out infinite!important}
      .alek-cosmic-farewell .alek-opening-moon{pointer-events:auto!important;cursor:pointer!important}
      .alek-cosmic-farewell.alek-farewell-final .alek-opening-flight{animation:none!important}
      .alek-cosmic-farewell.alek-farewell-final .alek-opening-moon{pointer-events:none!important;cursor:default!important}
      @keyframes alekFarewellShow{to{opacity:1}}
    `;
    splash.appendChild(style);
    document.body.appendChild(splash);
    __alekMoonFarewellSplash=splash;
    __alekMoonFarewellFinishing=false;

    const sparkField=splash.querySelector(".alek-opening-spark-field");
    const moon=splash.querySelector(".alek-opening-moon");
    const sparkController=window.__ALEK_RENDERER__?.mountOpeningSparks?.(sparkField,{count:240,direction:"inward"})||null;
    const cancel=event=>{
        if(__alekMoonFarewellFinishing)return false;
        event?.preventDefault?.();event?.stopPropagation?.();event?.stopImmediatePropagation?.();
        try{sparkController?.dispose?.();}catch(_){}
        try{splash.remove();}catch(_){}
        __alekMoonFarewellSplash=null;__alekMoonFarewellRunning=false;__alekMoonFarewellFinishing=false;
        return true;
    };
    const finish=event=>{
        if(__alekMoonFarewellFinishing)return;
        __alekMoonFarewellFinishing=true;
        event?.preventDefault?.();event?.stopPropagation?.();event?.stopImmediatePropagation?.();
        moon.disabled=true;splash.classList.add("alek-farewell-final");
        const FINAL_MS=3000;
        try{void sparkController?.finishAtMoon?.(FINAL_MS);}catch(_){ }
        setTimeout(()=>{void __alekCoreExitExact();},FINAL_MS);
    };
    moon.addEventListener("click",finish,true);
    moon.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();finish(event);}});
    splash.__alekCancelFarewell=cancel;
    requestAnimationFrame(()=>moon.focus({preventScroll:true}));
    return true;
};
const __alekCancelMoonFarewell=event=>{
    const splash=__alekMoonFarewellSplash;
    if(!splash?.isConnected||__alekMoonFarewellFinishing)return false;
    return splash.__alekCancelFarewell?.(event)===true;
};
window.__alekMoonFarewellExit=__alekMoonFarewellExit;
window.__alekCancelMoonFarewell=__alekCancelMoonFarewell;
if(window.__ALEK_PENDING_MOON_FAREWELL__===true){
    try{delete window.__ALEK_PENDING_MOON_FAREWELL__;}catch(_){window.__ALEK_PENDING_MOON_FAREWELL__=false;}
    requestAnimationFrame(()=>void __alekMoonFarewellExit());
}

// Windows, Alt+S birleşimini WM_SYSCHAR olarak ikinci kez iletebilir.
// Görünmez access-key yutağı bu sistem karakterini Chromium katmanında sahiplenir;
// Core/keydown ana daireyi zaten açtıysa zaman kilidi ikinci aç-kapayı engeller.
const __alekInstallAltSSystemCharSink=()=>{
    let sink=document.getElementById("alek-alt-s-system-char-sink");
    if(sink)return sink;
    sink=document.createElement("button");
    sink.type="button";sink.id="alek-alt-s-system-char-sink";sink.accessKey="s";sink.tabIndex=-1;
    sink.setAttribute("aria-hidden","true");sink.setAttribute("data-alek-shortcut-sink","alt-s");
    Object.assign(sink.style,{position:"fixed",left:"-10000px",top:"-10000px",width:"1px",height:"1px",opacity:"0",overflow:"hidden",pointerEvents:"none"});
    sink.addEventListener("click",event=>{
        event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();
        // Eski Runtime Alt+S sistem karakterini gönderebilir; yalnızca sessizce tüket.
    },true);
    document.body.appendChild(sink);
    return sink;
};
if(document.body)__alekInstallAltSSystemCharSink();
else document.addEventListener("DOMContentLoaded",__alekInstallAltSSystemCharSink,{once:true});

if(window.__ALEK_PENDING_PRIMARY_RADIAL__===true){
    try{delete window.__ALEK_PENDING_PRIMARY_RADIAL__;}catch(_){window.__ALEK_PENDING_PRIMARY_RADIAL__=false;}
    requestAnimationFrame(()=>__alekPrimaryOpenRadialMenu());
}

// Üstte yalnız yardımcı semboller kalır. Ana görünüm başlıkları F2 dairesindedir.
(()=>{
    const edition=v9Masthead.querySelector(".v9-edition");
    if(!edition||edition.querySelector(".alek-primary-utility-dock"))return;
    const dock=document.createElement("div");dock.className="alek-primary-utility-dock";dock.setAttribute("role","group");dock.setAttribute("aria-label","Hızlı araçlar");
    const forgotten=v2Nav.querySelector('[data-action="forgotten-vault"]');
    const exportButton=v9Masthead.querySelector('[data-data-transfer="export"]');
    const importButton=v9Masthead.querySelector('[data-data-transfer="import"]');
    const prepare=(button,glyph,title,extra="")=>{if(!button)return null;button.className=`alek-primary-utility-button ${extra}`.trim();button.innerHTML=`<span aria-hidden="true">${glyph}</span>`;button.title=title;button.setAttribute("aria-label",title);return button;};
    [
        prepare(forgotten,"◌","Unutulmuşlar Mahzeni","forgotten"),
        prepare(exportButton,"↥","Dışarı Aktar · .alekdata","export"),
        prepare(importButton,"↧","İçeri Aktar · .alekdata","import")
    ].filter(Boolean).forEach(button=>dock.appendChild(button));
    edition.appendChild(dock);
    v9Masthead.querySelector(".v9-data-vault")?.remove();
    v2Nav.classList.add("alek-primary-primary-nav-hidden");v2Nav.setAttribute("aria-hidden","true");
})();

document.addEventListener("keydown",event=>{
    const target=event.target,key=String(event.key||"").toLowerCase();
    const editable=target&&((target.matches&&target.matches("input,textarea,select"))||target.isContentEditable);
    const altS=event.altKey&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&key==="s";
    if(altS&&!editable){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();return;}
    if(key==="escape"&&__alekPrimaryRadialShade?.isConnected){event.preventDefault();event.stopPropagation();event.stopImmediatePropagation();__alekPrimaryCloseRadialMenu();}
},true);


