;(()=>{const old=document.getElementById("r22-runtime-style");old?.remove();const style=document.createElement("style");style.id="r22-runtime-style";style.textContent="/* R22 gateways + inventory */\n.r22-help-hero{grid-template-columns:minmax(0,1fr) 76px!important}\n.r22-help-map-gate,.r22-surface-gate{width:62px;height:62px;border-radius:50%;padding:3px;border:1px solid rgba(229,190,83,.78);background:radial-gradient(circle at 38% 30%,rgba(101,220,255,.24),rgba(6,18,28,.96) 66%);box-shadow:0 0 0 1px rgba(81,196,255,.16),0 0 22px rgba(62,198,255,.14);overflow:hidden;cursor:pointer;transition:.18s ease}\n.r22-help-map-gate img,.r22-surface-gate img{width:100%;height:100%;object-fit:cover;border-radius:50%}\n.r22-help-map-gate:hover,.r22-surface-gate:hover{box-shadow:0 0 0 1px rgba(255,239,181,.52),0 0 30px rgba(66,206,255,.34),0 0 18px rgba(239,196,76,.25);transform:translateY(-1px)}\n.r22-inventory{height:100%;min-height:0;display:grid;grid-template-rows:auto minmax(0,1fr) auto;gap:10px}.r22-inventory>header{display:flex;align-items:center;justify-content:space-between;padding:2px 2px 8px;border-bottom:1px solid rgba(108,197,228,.22)}\n.r22-inventory>header small{display:block;color:#72cce7;letter-spacing:.18em;font-size:.66rem}.r22-inventory>header strong{font-family:Georgia,serif;color:#f2e7c4}\n.r22-inventory button,.r22-item-editor button,.r22-inv-modal button{font:inherit}.r22-inventory [data-add],.r22-item-editor button,.r22-inv-modal button{border:1px solid rgba(217,174,73,.45);background:linear-gradient(180deg,rgba(20,42,55,.96),rgba(7,16,24,.98));color:#e9ddbc;border-radius:10px;padding:8px 12px;cursor:pointer}\n.r22-inventory-grid{overflow:auto;display:grid;grid-template-columns:repeat(6,minmax(0,1fr));align-content:start;gap:7px;padding:3px}.r22-item-slot{position:relative;aspect-ratio:1/1;min-width:0;border:1px solid rgba(104,180,208,.28);border-radius:12px;background:radial-gradient(circle at 45% 38%,rgba(45,124,157,.10),rgba(4,12,19,.98) 70%);padding:8px;overflow:hidden;transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease}\n.r22-item-slot:not(.empty){cursor:pointer}.r22-item-slot:not(.empty):hover{transform:translateY(-2px);border-color:rgba(107,222,255,.68);box-shadow:0 0 20px rgba(45,185,235,.16),inset 0 0 18px rgba(242,198,76,.05)}.r22-item-slot img{width:100%;height:100%;object-fit:contain;display:block}.r22-item-slot b{position:absolute;right:6px;bottom:5px;min-width:22px;padding:2px 6px;border-radius:999px;background:rgba(3,10,16,.88);border:1px solid rgba(237,199,85,.48);color:#fff3c5;font-size:.72rem}.r22-item-slot.empty{opacity:.35;border-style:dashed}.r22-inventory>footer{font-size:.72rem;color:#6f8e9c;text-align:right}\n.r22-item-editor{height:100%;display:grid;grid-template-rows:auto auto minmax(0,1fr) auto;gap:12px;overflow:auto}.r22-item-editor>header,.r22-item-editor>footer{display:flex;justify-content:space-between;gap:8px}.r22-item-editor>footer>div{display:flex;gap:8px}.r22-item-preview{width:min(180px,34%);aspect-ratio:1;margin:auto;border-radius:18px;border:1px solid rgba(225,184,69,.58);background:radial-gradient(circle,rgba(39,159,204,.12),rgba(3,10,16,.98));padding:12px;box-shadow:0 0 28px rgba(43,182,232,.11)}.r22-item-preview img{width:100%;height:100%;object-fit:contain}\n.r22-item-form{display:grid;grid-template-columns:1fr 160px;gap:10px}.r22-item-form label{display:grid;gap:6px;color:#ccb879;font-size:.76rem}.r22-item-form .wide{grid-column:1/-1}.r22-item-form input,.r22-item-form select,.r22-item-form textarea,.r22-inv-field input,.r22-inv-field select{width:100%;box-sizing:border-box;background:#07121a;border:1px solid rgba(92,149,174,.35);color:#eef7fa;border-radius:9px;padding:9px;outline:none}.r22-item-form textarea{min-height:120px;resize:vertical}.r22-type-row{display:grid;grid-template-columns:52px minmax(0,1fr);gap:8px}.r22-type-row [data-type-mode]{padding:6px}\n.r22-inv-modal-shade{position:fixed;inset:0;z-index:120000;background:rgba(0,4,8,.83);backdrop-filter:blur(7px);display:grid;place-items:center;padding:22px}.r22-inv-modal{width:min(520px,94vw);max-height:88vh;overflow:auto;border-radius:18px;border:1px solid rgba(226,183,70,.55);background:linear-gradient(145deg,#07131d,#05090e);box-shadow:0 30px 100px rgba(0,0,0,.68),0 0 38px rgba(38,171,220,.12)}.r22-inv-modal.wide{width:min(920px,95vw)}.r22-inv-modal>header{display:flex;justify-content:space-between;align-items:center;padding:14px 16px;border-bottom:1px solid rgba(89,175,205,.22);color:#f0e5c4}.r22-inv-modal>header button{padding:4px 9px}.r22-inv-modal-body{padding:16px;display:grid;gap:14px}.r22-inv-field{display:grid;gap:7px;color:#cdb66e}.r22-inv-modal-actions{display:flex;justify-content:flex-end;gap:8px}.r22-inv-modal .primary,.r22-item-editor .primary{border-color:rgba(241,202,86,.75);box-shadow:inset 0 0 18px rgba(56,186,229,.08)}.r22-item-editor .danger{color:#ff9a9a;border-color:rgba(214,74,74,.45)}\n.r22-crop-viewport{width:min(480px,72vw);aspect-ratio:1;margin:auto;position:relative;overflow:hidden;border:2px solid rgba(235,194,75,.72);border-radius:16px;background:#02070b;touch-action:none}.r22-crop-viewport:after{content:\"\";position:absolute;inset:0;box-shadow:inset 0 0 0 1px rgba(116,221,255,.42),inset 0 0 44px rgba(0,0,0,.28);pointer-events:none}.r22-crop-viewport img{position:absolute;left:50%;top:50%;transform-origin:center center;max-width:none;max-height:none;user-select:none;pointer-events:none}.r22-crop-stage{display:grid;gap:14px}.r22-crop-stage label{display:grid;grid-template-columns:auto 1fr;gap:10px;align-items:center;color:#cdb66e}.r22-crop-actions{display:flex;justify-content:flex-end;gap:8px}\n.r22-trade-head{display:grid;grid-template-columns:1fr auto 1fr;text-align:center;gap:12px;color:#f1e5bf}.r22-trade-bags{display:grid;grid-template-columns:1fr 1fr;gap:14px}.r22-mini-bag{min-height:180px;padding:8px;border:1px solid rgba(76,158,190,.25);border-radius:14px;display:grid;grid-template-columns:repeat(4,1fr);gap:6px;align-content:start}.r22-mini-slot{aspect-ratio:1;padding:5px;position:relative}.r22-mini-slot img{width:100%;height:100%;object-fit:contain}.r22-mini-slot b{position:absolute;right:3px;bottom:2px}.r22-mini-slot.selected{border-color:#72dcff!important;box-shadow:0 0 18px rgba(75,200,240,.25)}.r22-trade-qty{display:grid;grid-template-columns:1fr 1fr;gap:14px}.r22-trade-qty label{display:grid;gap:6px;color:#cdb66e}\n";document.head.appendChild(style);})();

